    function restoreNavState() {



        let saved = null;



        try { saved = JSON.parse(sessionStorage.getItem('mantis_nav') || 'null'); } catch (e) { return; }



        if (!saved || !saved.tab || saved.tab === 'home') {



            if (typeof showHomePage === 'function') showHomePage();



            return;



        }



        // Restore IOC tab selection if saved



        if (saved.tab === 'ioc-search' && saved.iocTab) {



            activeIocTab = saved.iocTab;



        }



        let sel = null;



        if (saved.tab === 'ta' || saved.tab === 'mwtools') {



            sel = (saved.cat && document.querySelector(`.nav-subitem[data-tab='${saved.tab}'][data-galaxy-cat='${saved.cat}']`))



                || document.querySelector(`.nav-parent[data-tab='${saved.tab}']`);



        } else {



            sel = document.querySelector(`.nav-item[data-tab='${saved.tab}']`);



        }



        if (sel) sel.click();



        else if (typeof showHomePage === 'function') showHomePage();



    }







    function detectIndicatorType(val) {



        const raw = (val || '').trim();



        if (!raw) return 'hash';



        if (/^[a-fA-F0-9]{32,128}$/.test(raw)) return 'hash';



        if (/^(https?|hxxps?|ftp):\/\//i.test(raw)) return 'url';



        if (/^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(raw) || (raw.includes(':') && !raw.includes('/'))) return 'ip';



        if (/^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$/.test(raw)) return 'domain';



        return 'keyword';



    }







    // ── IOC Tab Bar: helper + click handler ──────────────────────────────────



    let lastDetectedType = null;







    function updateIocTabUI(detectedType = null) {



        document.querySelectorAll('.ioc-tab').forEach(btn => {



            btn.classList.toggle('active', btn.dataset.iocTab === activeIocTab);



        });







        const autoBtn = document.getElementById('ioc-tab-auto');



        if (autoBtn) {



            if (activeIocTab === 'auto' && detectedType) {



                const labels = { hash: 'Hash', domain: 'Domain', ip: 'IP', url: 'URL', keyword: 'Keyword', infra: 'Infra' };



                autoBtn.innerHTML = `<i class="fa-solid fa-bolt"></i> Auto-Detect (${labels[detectedType] || detectedType})`;



                autoBtn.classList.add('detected');



            } else {



                autoBtn.innerHTML = `<i class="fa-solid fa-bolt"></i> Auto-Detect`;



                autoBtn.classList.remove('detected');



            }



        }







        const IOC_PLACEHOLDERS = {



            auto: 'Enter any Hash, IP, Domain, URL, or Keyword...',



            hash: 'Enter MD5, SHA-1, SHA-256, SHA-512, or SHA3-384 hash...',



            domain: 'Enter domain (e.g. example.com)...',



            ip: 'Enter IPv4 or IPv6 address...',



            url: 'Enter full URL (e.g. https://example.com/path)...',



            keyword: 'Enter any keyword, tag, or indicator...',



            infra: 'Enter IP, CIDR, ASN, Domain, or filter (e.g. ssl.jarm:..., port:..., cloud.provider:..., vuln:...)...'



        };



        if (inputField) inputField.placeholder = IOC_PLACEHOLDERS[activeIocTab] || IOC_PLACEHOLDERS.auto;



        if (keywordTypeSelect) {



            const _effType = (activeIocTab === 'auto') ? (detectedType || 'hash') : activeIocTab;



            setKeywordModeVisible(_effType === 'keyword');



        }



    }







    function handleRealtimeAutoDetect() {



        if (activeIocTab !== 'auto') return;



        const val = inputField ? inputField.value.trim() : '';







        const detected = val ? detectIndicatorType(val) : null;



        if (detected !== lastDetectedType) {



            lastDetectedType = detected;



            currentTab = detected || 'auto';



            updateIocTabUI(detected);



            renderSourceSelector();



        }



    }







    // Wire up IOC tab bar pill clicks (runs once, delegated from document)



    document.addEventListener('click', (evt) => {



        const iocPill = evt.target.closest('.ioc-tab');



        if (!iocPill) return;



        const newIocTab = iocPill.dataset.iocTab;



        if (!newIocTab) return;



        if (!currentViewIsAuxiliary) saveCurrentTabState();



        activeIocTab = newIocTab;



        lastDetectedType = null;



        if (activeIocTab === 'auto') {



            const val = inputField ? inputField.value.trim() : '';



            const detected = val ? detectIndicatorType(val) : null;



            lastDetectedType = detected;



            currentTab = detected || 'auto';



            updateIocTabUI(detected);



            renderSourceSelector();



        } else {



            currentTab = activeIocTab;



            updateIocTabUI();



            renderSourceSelector();



        }



        // Restore per-type cache



        const iocCache = tabCaches[currentTab];



        if (iocCache) {



            activeKeywordType = currentTab === 'keyword' ? (iocCache.keywordType || 'all') : 'all';



            syncKeywordTypeSelect();



            inputField.value = iocCache.input;



            currentResults = iocCache.currResults;



            if (iocCache.resultsHtml !== null) {



                resultsContainer.innerHTML = iocCache.resultsHtml;



                restoreResultsNavigation(false);



                saveBtn.style.display = iocCache.showSave || 'inline-flex';



            } else {



                resultsContainer.innerHTML = '<div class="empty-state"><i class="fa-solid fa-magnifying-glass-chart"></i><p>Enter an IOC above to begin the intelligence lookup.</p></div>';



                hideResultsNavigation(true);



                saveBtn.style.display = 'none';



            }



        }



        currentViewIsAuxiliary = false;



    });







    // Helper: navigate to the IOC Search view with a specific type pill selected.



    // Used by pivot links, history re-lookup, mantisRunApprovedAction, etc.



    function switchToIocSearch(type) {



        const IOC_TYPES = ['hash', 'domain', 'ip', 'url', 'keyword', 'infra'];



        if (!IOC_TYPES.includes(type)) return; // infra, cti, etc. handled elsewhere



        activeIocTab = type;



        // Make sure the ioc-search nav item is active



        setActiveNavigation(type);



        saveNavState(type);



        // Show standard search UI



        const contentHeader = document.querySelector('.content-header');



        if (contentHeader) contentHeader.style.display = 'flex';



        if (searchContainer) searchContainer.style.display = 'block';



        if (sourceSelectorPanel) sourceSelectorPanel.style.display = 'block';



        if (resultsContainer) resultsContainer.style.display = 'block';



        if (headerActions) headerActions.style.display = 'flex';



        hideAuxiliaryPanes();



        currentTab = type;



        if (tabTitle) tabTitle.textContent = 'IOC Intelligence Search';



        if (settingsView) settingsView.style.display = 'none';



        if (settingsBtn) settingsBtn.classList.remove('active');



        if (settingsFooter) settingsFooter.classList.remove('settings-expanded');



        settingsNavItems.forEach(item => item.classList.remove('active'));



        updateIocTabUI();



        renderSourceSelector();



        syncSidebarRevealButton();



        currentViewIsAuxiliary = false;



    }







