    let SOURCES_BY_TAB = FALLBACK_SOURCES_BY_TAB;







    const hasApiKey = (keyName) => {



        if (keyName === null || keyName === undefined) return true;



        if (KEY_STORE[keyName]) return !!KEY_STORE[keyName]();



        return !!localStorage.getItem(`ioc_${keyName}_key`);



    };







    const hasSourceAccess = (src) => {



        if (!src) return false;



        if (!src.key) return true; // keyless providers are always available



        if (hasApiKey(src.key)) return true; // browser key configured



        if (src.server_key) return true; // server-side env key covers it



        // Optional-key providers that work without any key stay open



        // (Pulsedive, GitHub); the rest lock until a key exists somewhere.



        return !src.key_required && (src.requires_api_key === false || src.optional_api_key);



    };







    const applySourceMetadata = (tabs) => {



        if (!tabs || typeof tabs !== 'object') return false;



        const next = {};



        let valid = false;



        for (const [tab, list] of Object.entries(tabs)) {



            if (!Array.isArray(list) || list.length === 0) continue;



            const mapped = list.filter(s => s && s.id).map(s => ({



                id: s.id,



                label: s.label || s.id,



                icon: s.icon || 'fa-solid fa-circle-nodes',



                key: s.key === undefined ? null : s.key,



                requires_api_key: s.requires_api_key !== undefined ? !!s.requires_api_key : undefined,



                optional_api_key: !!s.optional_api_key,



                key_required: !!s.key_required,



                server_key: !!s.server_key



            }));



            if (mapped.length > 0) {



                next[tab] = mapped;



                valid = true;



            }



        }



        if (!valid) return false;



        // Preserve checkbox state across the re-render.



        const prevChecked = {};



        document.querySelectorAll('#source-checkboxes input[type=checkbox]').forEach(cb => {



            prevChecked[cb.dataset.source] = cb.checked;



        });



        SOURCES_BY_TAB = next;



        renderSourceSelector();



        if (Object.keys(prevChecked).length > 0) {



            document.querySelectorAll('#source-checkboxes input[type=checkbox]').forEach(cb => {



                if (cb.dataset.source in prevChecked && !cb.disabled) {



                    cb.checked = prevChecked[cb.dataset.source];



                    cb.dispatchEvent(new Event('change'));



                }



            });



        }



        return true;



    };







    fetch('/api/meta/sources')



        .then(resp => (resp.ok ? resp.json() : null))



        .then(tabs => { if (tabs) applySourceMetadata(tabs); })



        .catch(() => { /* keep hard-coded fallback */ });







