    function openTodaysIntel() {



        if (!todaysIntelBound) {



            todaysIntelBound = true;



            document.getElementById('todays-refresh')?.addEventListener('click', () => loadTodaysIntel(true));



            document.getElementById('todays-ai-brief')?.addEventListener('click', processTodaysIntelWithAi);



            document.getElementById('todays-ai-report')?.addEventListener('click', processTodaysIntelReport);



            document.getElementById('todays-filter-apply')?.addEventListener('click', () => loadTodaysIntel(true));



            document.getElementById('todays-filter-clear')?.addEventListener('click', () => {



                todaysClearFilters();



                loadTodaysIntel(true);



            });



            ['todays-filter-group', 'todays-filter-country', 'todays-filter-sector'].forEach(id => {



                document.getElementById(id)?.addEventListener('keydown', (e) => {



                    if (e.key === 'Enter') loadTodaysIntel(true);



                });



            });



            ['todays-filter-range', 'todays-filter-source', 'todays-filter-severity'].forEach(id => {



                document.getElementById(id)?.addEventListener('change', () => loadTodaysIntel(true));



            });



        }



        loadTodaysIntel(false);



    }







    // ---------------- X Monitor ----------------



    let xMonitorBound = false;



    let xMonitorSnapshot = null;



    const xMonitorState = { page: 1, category: 'all' };



    let xMonitorAccountFormOpen = false;



    let xMonitorManageQuery = '';



    const xMonitorCache = new Map();



    const xMonitorTwitterKey = () => document.getElementById('twitter-key')?.value?.trim() || localStorage.getItem('ioc_twitter_key') || '';



    const xMonitorFilters = () => ({



        q: document.getElementById('xmon-search')?.value?.trim() || '',



        range: document.getElementById('xmon-range')?.value || '7d',



        account: document.getElementById('xmon-account')?.value || '',



        entity: document.getElementById('xmon-entity')?.value || '',



        sort: document.getElementById('xmon-sort')?.value || 'newest',



        start_date: document.getElementById('xmon-start')?.value || '',



        end_date: document.getElementById('xmon-end')?.value || '',



        category: xMonitorState.category || 'all',



        page: xMonitorState.page || 1,



        page_size: 36,



    });



    const xMonitorCacheKey = (filters = xMonitorFilters()) => JSON.stringify(filters);



    const xMonitorDate = (value) => {



        const raw = String(value || '');



        return raw ? raw.replace('T', ' ').replace('Z', '').slice(0, 16) : '-';



    };



    const xMonitorInitials = (name = '') => String(name || 'X').trim().slice(0, 2).toUpperCase();



    const xMonitorIcon = (cls = '') => `<span class="xmon-xmark ${cls}">X</span>`;



    const xMonitorStatusText = (account = {}) => {



        if (!account.last_checked_at && (account.collection_status || 'pending') === 'pending') return 'Not checked yet';



        if (account.collection_error) return account.collection_error;



        return account.collection_status || 'Active';



    };







    function renderXMonitorMetric(label, value, icon, tone = '') {



        return `<div class="xmon-metric ${tone}">



            <i class="${escapeHtml(icon)}"></i>



            <div><strong>${escapeHtml(value ?? 0)}</strong><span>${escapeHtml(label)}</span></div>



        </div>`;



    }







    function renderXMonitorHealth(items = [], collector = {}) {



        const list = [...(items || [])];



        list.push({



            ok: collector?.requires_key ? Boolean(xMonitorTwitterKey()) : true,



            label: 'X Collector',



            status: xMonitorTwitterKey() ? 'key ready' : 'key missing',



            detail: 'Refresh collects direct account timelines through twitterapi.io. TweetFeed is not used in X Monitor.'



        });



        return `<div class="xmon-health">${list.map(item => {



            const status = String(item.status || '').toLowerCase() === 'never' ? 'No checks yet' : (item.status || '');



            return `<span class="${item.ok ? 'ok' : 'warn'}" title="${escapeHtml(item.detail || '')}">



            <i class="fa-solid ${item.ok ? 'fa-circle-check' : 'fa-circle-exclamation'}"></i>



            <b>${escapeHtml(item.label || '')}</b> ${escapeHtml(status)}



        </span>`;



        }).join('')}</div>`;



    }







    function renderXMonitorCategories(categories = []) {



        return `<div class="xmon-tabs">${(categories || []).map(cat => `



            <button type="button" class="${cat.id === xMonitorState.category ? 'active' : ''}" data-xmon-category="${escapeHtml(cat.id)}">



                ${escapeHtml(cat.label)} <b>${escapeHtml(String(cat.count || 0))}</b>



            </button>`).join('')}</div>`;



    }







    function renderXMonitorPosts(posts = []) {



        if (!posts.length) {



            const hasAccounts = (xMonitorSnapshot?.stats?.monitored_accounts || 0) > 0;



            const hasKey = Boolean(xMonitorTwitterKey());



            const emptyMessage = hasAccounts



                ? (hasKey



                    ? 'No direct X posts match this filter yet. Click Refresh Recent or widen the range/account filters.'



                    : 'Add a Twitter/X API key in Settings, then refresh to collect direct posts from monitored accounts.')



                : 'Add threat researchers, vendors, malware analysts, CERTs, or other public sources from Manage Accounts in the header.';



            return `<div class="xmon-empty">



                ${xMonitorIcon('xmon-empty-mark')}



                <h3>${hasAccounts ? 'No X timeline posts found for this view.' : 'No X accounts are currently monitored.'}</h3>



                <p>${escapeHtml(emptyMessage)} TweetFeed IOC observations are intentionally excluded here.</p>



            </div>`;



        }



        return `<div class="xmon-feed">${posts.map(renderXMonitorCard).join('')}</div>`;



    }







    function xMonitorMediaKey(url) {



        const raw = String(url || '').trim();



        if (!raw) return '';



        try {



            const parsed = new URL(raw, window.location.href);



            if (parsed.hostname.toLowerCase() === 'pbs.twimg.com' && (



                parsed.pathname.startsWith('/media/') ||



                parsed.pathname.startsWith('/card_img/')



            )) {



                return `${parsed.hostname.toLowerCase()}${parsed.pathname}`;



            }



            parsed.hash = '';



            if (parsed.pathname !== '/') parsed.pathname = parsed.pathname.replace(/\/+$/, '');



            return parsed.toString();



        } catch (_) {



            return raw;



        }



    }







    function dedupeXMonitorMedia(media = []) {



        const out = [];



        const seen = new Map();



        (Array.isArray(media) ? media : []).forEach(item => {



            if (!item || (!item.preview && !item.url)) return;



            let preview = String(item.preview || item.url || '').trim();



            let url = String(item.url || preview || '').trim();



            if (/^https?:\/\/t\.co\//i.test(preview)) preview = '';



            if (/^https?:\/\/t\.co\//i.test(url) && preview) url = preview;



            if (!preview && !url) return;



            const normalized = { ...item, preview, url };



            const key = xMonitorMediaKey(preview || url);



            const existingIndex = seen.get(key);



            if (existingIndex !== undefined) {



                const existing = out[existingIndex];



                const existingArea = Number(existing.width || 0) * Number(existing.height || 0);



                const newArea = Number(normalized.width || 0) * Number(normalized.height || 0);



                if (newArea > existingArea) out[existingIndex] = normalized;



                return;



            }



            seen.set(key, out.length);



            out.push(normalized);



        });



        return out;



    }







    function renderXMonitorCard(post = {}) {



        const cats = (post.categories || []).slice(0, 4).map(cat => `<span>${escapeHtml(cat.replace('-', ' '))}</span>`).join('');



        const urls = (post.urls || []).slice(0, 3).map(url => `<code>${escapeHtml(url)}</code>`).join('');



        const mediaItems = dedupeXMonitorMedia(post.media || [])



            .filter(item => item && (item.preview || item.url))



            .slice(0, 4);



        const mediaHtml = mediaItems.length ? `<div class="xmon-media-grid count-${mediaItems.length}">



            ${mediaItems.map(item => {



            let previewUrl = item.preview || item.url || '';



            let mediaUrl = item.url || item.preview || '#';



            const isDirectImage = previewUrl && (



                previewUrl.includes('pbs.twimg.com') ||



                /\.(png|jpe?g|gif|webp|svg)(\?.*)?$/i.test(previewUrl)



            ) && !previewUrl.includes('t.co/');



            if (isDirectImage) {



                return `<a href="${escapeHtml(mediaUrl)}" target="_blank" rel="noopener noreferrer" title="Open media">



                        <img src="${escapeHtml(previewUrl)}" alt="" loading="lazy">



                    </a>`;



            } else {



                return `<a href="${escapeHtml(mediaUrl)}" target="_blank" rel="noopener noreferrer" class="xmon-media-link-pill" title="Open media link">



                        <i class="fa-solid fa-arrow-up-right-from-square"></i> <span>View Attached Media</span>



                    </a>`;



            }



        }).join('')}



        </div>` : '';



        const entityBits = [



            ['CVE', post.entities?.cve],



            ['Hash', post.entities?.hash],



            ['IP', post.entities?.ip],



            ['Domain', post.entities?.domain],



        ].filter(([, values]) => Array.isArray(values) && values.length)



            .map(([label, values]) => `<span title="${escapeHtml(values.slice(0, 8).join(', '))}">${escapeHtml(label)} <b>${escapeHtml(String(values.length))}</b></span>`).join('');



        const tags = (post.hashtags || []).slice(0, 8).map(tag => `<span>${escapeHtml(tag)}</span>`).join('');



        const metrics = post.metrics || {};



        const metricBits = [



            ['fa-comment', metrics.replies],



            ['fa-retweet', metrics.retweets],



            ['fa-heart', metrics.likes],



            ['fa-eye', metrics.views],



        ].filter(([, value]) => Number(value || 0) > 0)



            .map(([icon, value]) => `<span><i class="fa-solid ${icon}"></i>${escapeHtml(String(value))}</span>`).join('');



        const stateBits = [



            post.is_repost ? '<span>Repost</span>' : '',



            post.is_quote ? '<span>Quote</span>' : '',



            post.is_reply ? '<span>Reply</span>' : '',



        ].filter(Boolean).join('');



        const avatar = post.author_avatar



            ? `<img src="${escapeHtml(post.author_avatar)}" alt="">`



            : `<div class="xmon-avatar-fallback">${escapeHtml(xMonitorInitials(post.author_display_name || post.author_username))}</div>`;



        return `<article class="xmon-card">



            <header>



                <div class="xmon-avatar">${avatar}</div>



                <div class="xmon-author">



                    <strong>${escapeHtml(post.author_display_name || post.author_username)}</strong>



                    <span>@${escapeHtml(post.author_username || '')} · ${xMonitorDate(post.published_at)}</span>



                </div>



                <a class="xmon-open-x" href="${escapeHtml(post.post_url || '#')}" target="_blank" rel="noopener noreferrer" title="Open original post on X">${xMonitorIcon()}</a>



            </header>



            <p>${escapeHtml(post.text || '')}</p>



            ${mediaHtml}



            ${urls ? `<div class="xmon-url-list">${urls}</div>` : ''}



            ${entityBits ? `<div class="xmon-entity-strip">${entityBits}</div>` : ''}



            ${(metricBits || stateBits) ? `<div class="xmon-tweet-meta">${metricBits}${stateBits}</div>` : ''}



            <footer>



                <div class="xmon-tags">${tags || cats}</div>



                ${cats ? `<div class="xmon-cats">${cats}</div>` : ''}



            </footer>



        </article>`;



    }







    function renderXMonitorPager(pagination = {}) {



        const pages = Number(pagination.pages || 1);



        const page = Number(pagination.page || 1);



        if (pages <= 1) return '';



        const buttons = [];



        for (let p = 1; p <= pages; p += 1) {



            if (p === 1 || p === pages || Math.abs(p - page) <= 2) {



                buttons.push(`<button type="button" class="${p === page ? 'active' : ''}" data-xmon-page="${p}">${p}</button>`);



            } else if (!buttons[buttons.length - 1]?.includes('xmon-page-gap')) {



                buttons.push('<span class="xmon-page-gap">...</span>');



            }



        }



        return `<div class="xmon-pager">${buttons.join('')}</div>`;



    }







    function renderXMonitor(data = {}) {



        xMonitorSnapshot = data || {};



        const stats = data.stats || {};



        const pagination = data.pagination || {};



        return `



            <section class="xmon-summary">



                ${renderXMonitorHealth(data.health || [], data.collector || {})}



                <div class="xmon-metrics">



                    ${renderXMonitorMetric('Active Accounts', stats.active_accounts, 'fa-solid fa-user-check')}



                    ${renderXMonitorMetric('Posts Today', stats.posts_today, 'fa-solid fa-calendar-day')}



                    ${renderXMonitorMetric('Total Posts', stats.total_posts, 'fa-solid fa-message')}



                    ${renderXMonitorMetric('URLs', stats.urls, 'fa-solid fa-link', 'warm')}



                    ${renderXMonitorMetric('Domains', stats.domains, 'fa-solid fa-globe')}



                    ${renderXMonitorMetric('IPs', stats.ips, 'fa-solid fa-location-dot', 'pink')}



                    ${renderXMonitorMetric('Hashes', stats.hashes, 'fa-solid fa-hashtag')}



                    ${renderXMonitorMetric('CVEs', stats.cves, 'fa-solid fa-bug', 'danger')}



                </div>



            </section>



            ${renderXMonitorCategories(data.categories || [])}



            <section class="xmon-feed-shell">



                <div class="xmon-feed-title">



                    <div>



                        <h3>X Account Timeline</h3>



                        <p>Direct posts from monitored X/Twitter accounts. IOC-only TweetFeed records are kept out of this deck.</p>



                    </div>



                    <span>${escapeHtml(String(pagination.total || 0))} stored X posts match this view</span>



                </div>



                ${renderXMonitorPosts(data.posts || [])}



                ${renderXMonitorPager(pagination)}



            </section>



        `;



    }







    async function loadXMonitor(force = false) {



        const content = document.getElementById('xmon-content');



        if (!content) return;



        const filters = xMonitorFilters();



        const key = xMonitorCacheKey(filters);



        const cached = xMonitorCache.get(key);



        if (!force && cached && Date.now() - cached.ts < 120000) {



            xMonitorSnapshot = cached.data;



            content.innerHTML = renderXMonitor(cached.data);



            hydrateXMonitorAccounts(cached.data.accounts || []);



            return;



        }



        if (!xMonitorSnapshot || force) {



            content.innerHTML = '<div class="empty-state"><i class="fa-solid fa-circle-notch mantis-spin"></i><p>Loading X Monitor...</p></div>';



        }



        try {



            const res = await fetch(`${API_BASE}/api/x-monitor/dashboard`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify(filters)



            });



            const data = await res.json();



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            xMonitorSnapshot = data;



            xMonitorCache.set(key, { data, ts: Date.now() });



            content.innerHTML = renderXMonitor(data);



            hydrateXMonitorAccounts(data.accounts || []);



        } catch (e) {



            content.innerHTML = `<div class="error-card"><i class="fa-solid fa-triangle-exclamation"></i><div>X Monitor failed: ${escapeHtml(e.message || e)}</div></div>`;



        }



    }







    function hydrateXMonitorAccounts(accounts = []) {



        const select = document.getElementById('xmon-account');



        if (!select) return;



        const current = select.value;



        select.innerHTML = '<option value="">All accounts</option>' + accounts.map(a => `<option value="${escapeHtml(a.username)}">@${escapeHtml(a.username)}</option>`).join('');



        select.value = current;



    }







    async function refreshXMonitor() {



        const btn = document.getElementById('xmon-refresh');



        const key = xMonitorTwitterKey();



        if (btn) {



            btn.disabled = true;



            btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Collecting';



        }



        try {



            const res = await fetch(`${API_BASE}/api/x-monitor/refresh`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({



                    twitter_key: key,



                    max_accounts: 20,



                    accounts_per_batch: 20,



                    mode: 'monitor',



                    range: document.getElementById('xmon-range')?.value || '7d',



                    start_date: document.getElementById('xmon-start')?.value || '',



                    end_date: document.getElementById('xmon-end')?.value || ''



                })



            });



            const data = await res.json();



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            if (data.ok || data.checked) {



                showNotification(`X Monitor checked ${data.accounts_checked || data.checked || 0}/${data.total_active_accounts || data.accounts_selected || 0} accounts: ${data.provider_posts || data.provider_tweets || 0} provider posts, ${data.inserted || 0} new, ${data.duplicates || 0} duplicates, ${data.accounts_timeout || data.accounts_timed_out || 0} timeouts.`);



            } else {



                showNotification(data.reason || 'X Monitor refresh completed with warnings.');



            }



            xMonitorCache.clear();



            await loadXMonitor(true);



        } catch (e) {



            showNotification(e.message || 'X Monitor refresh failed.');



        } finally {



            if (btn) {



                btn.disabled = false;



                btn.innerHTML = '<i class="fa-solid fa-rotate"></i> Refresh Recent';



            }



        }



    }







    function xMonitorModalHtml() {



        const accounts = xMonitorSnapshot?.accounts || [];



        const q = xMonitorManageQuery.trim().toLowerCase();



        const shownAccounts = q



            ? accounts.filter(a => [a.username, a.display_name, (a.tags || []).join(' '), a.notes, a.collection_status, a.collection_error].join(' ').toLowerCase().includes(q))



            : accounts;



        const renderAccountRow = (a) => {



            const username = String(a.username || '').replace(/^@+/, '');



            return `<div class="xmon-account-row">



                <div>



                    <strong><a class="xmon-account-link" href="https://x.com/${encodeURIComponent(username)}" target="_blank" rel="noopener noreferrer" title="Open @${escapeHtml(username)} on X">@${escapeHtml(username)}</a></strong>



                    <span>${escapeHtml(a.display_name || username)} - ${(a.tags || []).map(escapeHtml).join(', ') || 'no tags'}</span>



                    <small>${escapeHtml(a.collection_status || 'pending')}${a.collection_error ? ` - ${escapeHtml(a.collection_error)}` : ''}</small>



                </div>



                <b class="${a.enabled ? 'active' : 'paused'}">${a.enabled ? 'Active' : 'Paused'}</b>



                <button type="button" class="btn-secondary" data-xmon-edit-account="${escapeHtml(a.id)}">Edit</button>



                <button type="button" class="btn-secondary" data-xmon-toggle-account="${escapeHtml(a.id)}">${a.enabled ? 'Pause' : 'Resume'}</button>



                <button type="button" class="btn-secondary danger" data-xmon-delete-account="${escapeHtml(a.id)}">Delete</button>



            </div>`;



        };



        const groupedAccounts = shownAccounts.reduce((groups, account) => {



            const username = String(account.username || '').replace(/^@+/, '');



            const letter = /^[a-z]/i.test(username) ? username[0].toUpperCase() : '#';



            if (!groups[letter]) groups[letter] = [];



            groups[letter].push(account);



            return groups;



        }, {});



        const accountsHtml = Object.keys(groupedAccounts).sort((a, b) => {



            if (a === '#') return -1;



            if (b === '#') return 1;



            return a.localeCompare(b);



        }).map(letter => `<div class="xmon-alpha-section">



            <div class="xmon-alpha-heading"><span>${escapeHtml(letter)}</span><b>${groupedAccounts[letter].length}</b></div>



            ${groupedAccounts[letter].map(renderAccountRow).join('')}



        </div>`).join('');



        return `<div class="xmon-modal-backdrop" id="xmon-modal">



            <div class="xmon-modal">



                <header>



                    <div><h2>Manage X Accounts</h2><p>${escapeHtml(String(accounts.length))} monitored accounts. Delete preserves stored posts unless explicitly selected.</p></div>



                    <button type="button" class="xmon-icon-btn" data-xmon-close><i class="fa-solid fa-xmark"></i></button>



                </header>



                <section class="xmon-modal-tools">



                    <div class="xmon-account-search">



                        <i class="fa-solid fa-magnifying-glass"></i>



                        <input id="xmon-account-search" type="text" value="${escapeHtml(xMonitorManageQuery)}" placeholder="Search accounts, tags, status, notes">



                    </div>



                    <button type="button" class="btn-primary xmon-add-user" data-xmon-add-user><i class="fa-solid fa-user-plus"></i> Add User</button>



                </section>



                <section class="xmon-account-form ${xMonitorAccountFormOpen ? '' : 'is-hidden'}">



                    <input id="xmon-form-id" type="hidden">



                    <input id="xmon-form-username" type="text" placeholder="@username">



                    <input id="xmon-form-display" type="text" placeholder="Display name">



                    <input id="xmon-form-tags" type="text" placeholder="Tags: malware, vuln, cert">



                    <input id="xmon-form-interval" type="number" min="15" max="1440" value="60" title="Collection interval minutes">



                    <label><input id="xmon-form-enabled" type="checkbox" checked> Enabled</label>



                    <textarea id="xmon-form-notes" placeholder="Notes"></textarea>



                    <button type="button" class="btn-primary xmon-save-account" data-xmon-save-account><i class="fa-solid fa-floppy-disk"></i> Save Account</button>



                    <button type="button" class="btn-secondary" data-xmon-reset-form>Clear</button>



                </section>



                <section class="xmon-account-table">



                    ${shownAccounts.length ? accountsHtml : `<div class="xmon-empty compact"><p>No accounts configured yet.</p></div>`}



                    ${false ? shownAccounts.map(a => `



                        <div class="xmon-account-row">



                            <div>



                                <strong><a class="xmon-account-link" href="https://x.com/${encodeURIComponent(String(a.username || '').replace(/^@+/, ''))}" target="_blank" rel="noopener noreferrer" title="Open @${escapeHtml(String(a.username || '').replace(/^@+/, ''))} on X">@${escapeHtml(String(a.username || '').replace(/^@+/, ''))}</a></strong>



                                <span>${escapeHtml(a.display_name || a.username)} · ${(a.tags || []).map(escapeHtml).join(', ') || 'no tags'}</span>



                                <small>${escapeHtml(a.collection_status || 'pending')}${a.collection_error ? ` · ${escapeHtml(a.collection_error)}` : ''}</small>



                            </div>



                            <b class="${a.enabled ? 'active' : 'paused'}">${a.enabled ? 'Active' : 'Paused'}</b>



                            <button type="button" class="btn-secondary" data-xmon-edit-account="${escapeHtml(a.id)}">Edit</button>



                            <button type="button" class="btn-secondary" data-xmon-toggle-account="${escapeHtml(a.id)}">${a.enabled ? 'Pause' : 'Resume'}</button>



                            <button type="button" class="btn-secondary danger" data-xmon-delete-account="${escapeHtml(a.id)}">Delete</button>



                        </div>`).join('') : ''}



                </section>



            </div>



        </div>`;



    }







    async function openXMonitorManage() {



        await loadXMonitor(true);



        document.getElementById('xmon-modal')?.remove();



        document.body.insertAdjacentHTML('beforeend', xMonitorModalHtml());



        hydrateXMonitorManageModal();



    }







    function hydrateXMonitorManageModal() {



        document.querySelectorAll('.xmon-account-row').forEach(row => {



            const status = row.querySelector('small');



            if (status && status.textContent.trim().toLowerCase() === 'pending') {



                status.textContent = 'Not checked yet';



                status.classList.add('not-checked');



            }



            const meta = row.querySelector('span');



            if (meta) meta.textContent = meta.textContent.replace(String.fromCharCode(194, 183), '-');



        });



    }







    function closeXMonitorManage() {



        xMonitorAccountFormOpen = false;



        document.getElementById('xmon-modal')?.remove();



    }







    function resetXMonitorForm() {



        xMonitorAccountFormOpen = true;



        document.querySelector('.xmon-account-form')?.classList.remove('is-hidden');



        ['xmon-form-id', 'xmon-form-username', 'xmon-form-display', 'xmon-form-tags', 'xmon-form-notes'].forEach(id => {



            const el = document.getElementById(id);



            if (el) el.value = '';



        });



        const interval = document.getElementById('xmon-form-interval');



        if (interval) interval.value = '60';



        const enabled = document.getElementById('xmon-form-enabled');



        if (enabled) enabled.checked = true;



    }







    function editXMonitorAccount(id) {



        const account = (xMonitorSnapshot?.accounts || []).find(a => a.id === id);



        if (!account) return;



        xMonitorAccountFormOpen = true;



        document.querySelector('.xmon-account-form')?.classList.remove('is-hidden');



        document.getElementById('xmon-form-id').value = account.id;



        document.getElementById('xmon-form-username').value = `@${account.username}`;



        document.getElementById('xmon-form-display').value = account.display_name || '';



        document.getElementById('xmon-form-tags').value = (account.tags || []).join(', ');



        document.getElementById('xmon-form-notes').value = account.notes || '';



        document.getElementById('xmon-form-interval').value = account.interval_minutes || 60;



        document.getElementById('xmon-form-enabled').checked = Boolean(account.enabled);



    }







    async function saveXMonitorAccount() {



        const id = document.getElementById('xmon-form-id')?.value || '';



        const payload = {



            id,



            username: document.getElementById('xmon-form-username')?.value || '',



            display_name: document.getElementById('xmon-form-display')?.value || '',



            tags: document.getElementById('xmon-form-tags')?.value || '',



            notes: document.getElementById('xmon-form-notes')?.value || '',



            interval_minutes: Number(document.getElementById('xmon-form-interval')?.value || 60),



            enabled: Boolean(document.getElementById('xmon-form-enabled')?.checked),



        };



        const url = id ? '/api/x-monitor/accounts/update' : '/api/x-monitor/accounts';



        try {



            const res = await fetch(`${API_BASE}${url}`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify(payload)



            });



            const data = await res.json();



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            showNotification(id ? 'X account updated.' : 'X account added.');



            xMonitorCache.clear();



            await loadXMonitor(true);



            xMonitorAccountFormOpen = false;



            openXMonitorManage();



        } catch (e) {



            showNotification(e.message || 'Could not save account.');



        }



    }







    async function toggleXMonitorAccount(id) {



        const account = (xMonitorSnapshot?.accounts || []).find(a => a.id === id);



        if (!account) return;



        try {



            const res = await fetch(`${API_BASE}/api/x-monitor/accounts/update`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ ...account, id, enabled: !account.enabled })



            });



            const data = await res.json();



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            showNotification(account.enabled ? 'X account paused.' : 'X account resumed.');



            xMonitorCache.clear();



            await loadXMonitor(true);



            openXMonitorManage();



        } catch (e) {



            showNotification(e.message || 'Could not update account.');



        }



    }







    async function deleteXMonitorAccount(id) {



        const account = (xMonitorSnapshot?.accounts || []).find(a => a.id === id);



        if (!account) return;



        const confirmed = confirm(`Delete @${account.username} monitor?\n\nStored historical posts will be preserved.`);



        if (!confirmed) return;



        const deletePosts = confirm(`Also delete locally stored posts for @${account.username}?\n\nChoose Cancel to preserve historical posts.`);



        try {



            const res = await fetch(`${API_BASE}/api/x-monitor/accounts/delete`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ id, delete_posts: deletePosts })



            });



            const data = await res.json();



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            if (xMonitorSnapshot?.accounts) {



                xMonitorSnapshot.accounts = xMonitorSnapshot.accounts.filter(a => a.id !== id);



            }



            showNotification(deletePosts ? 'X monitor and stored posts removed.' : 'X monitor removed. Stored posts preserved.');



            xMonitorCache.clear();



            await loadXMonitor(true);



            openXMonitorManage();



        } catch (e) {



            showNotification(e.message || 'Could not delete account.');



        }



    }







    function bindXMonitor() {



        if (xMonitorBound) return;



        xMonitorBound = true;



        document.getElementById('xmon-refresh')?.addEventListener('click', refreshXMonitor);



        document.getElementById('xmon-manage')?.addEventListener('click', openXMonitorManage);



        document.getElementById('xmon-apply')?.addEventListener('click', () => { xMonitorState.page = 1; loadXMonitor(true); });



        document.getElementById('xmon-search')?.addEventListener('keydown', e => {



            if (e.key === 'Enter') {



                xMonitorState.page = 1;



                loadXMonitor(true);



            }



        });



        document.getElementById('xmon-range')?.addEventListener('change', () => {



            const custom = document.getElementById('xmon-range')?.value === 'custom';



            ['xmon-start', 'xmon-end'].forEach(id => {



                const el = document.getElementById(id);



                if (el) el.style.display = custom ? 'block' : 'none';



            });



            xMonitorState.page = 1;



            loadXMonitor(true);



        });



        ['xmon-account', 'xmon-entity', 'xmon-sort'].forEach(id => {



            document.getElementById(id)?.addEventListener('change', () => {



                xMonitorState.page = 1;



                loadXMonitor(true);



            });



        });



        document.addEventListener('click', async (e) => {



            const cat = e.target.closest('[data-xmon-category]');



            if (cat) {



                xMonitorState.category = cat.dataset.xmonCategory || 'all';



                xMonitorState.page = 1;



                await loadXMonitor(false);



                return;



            }



            const pageBtn = e.target.closest('[data-xmon-page]');



            if (pageBtn) {



                xMonitorState.page = Number(pageBtn.dataset.xmonPage || 1);



                await loadXMonitor(false);



                return;



            }



            if (e.target.closest('[data-xmon-open-manage]')) openXMonitorManage();



            if (e.target.closest('[data-xmon-close]') || e.target.id === 'xmon-modal') closeXMonitorManage();



            if (e.target.closest('[data-xmon-add-user]')) {



                xMonitorAccountFormOpen = true;



                openXMonitorManage();



                resetXMonitorForm();



            }



            if (e.target.closest('[data-xmon-reset-form]')) resetXMonitorForm();



            if (e.target.closest('[data-xmon-save-account]')) saveXMonitorAccount();



            const edit = e.target.closest('[data-xmon-edit-account]');



            if (edit) editXMonitorAccount(edit.dataset.xmonEditAccount);



            const toggle = e.target.closest('[data-xmon-toggle-account]');



            if (toggle) toggleXMonitorAccount(toggle.dataset.xmonToggleAccount);



            const del = e.target.closest('[data-xmon-delete-account]');



            if (del) deleteXMonitorAccount(del.dataset.xmonDeleteAccount);



        });



        document.addEventListener('input', (e) => {



            if (e.target?.id === 'xmon-account-search') {



                xMonitorManageQuery = e.target.value || '';



                openXMonitorManage();



                const input = document.getElementById('xmon-account-search');



                input?.focus();



                input?.setSelectionRange(input.value.length, input.value.length);



            }



        });



    }







    function openXMonitor() {



        bindXMonitor();



        loadXMonitor(false);



    }







