        if (titleText.startsWith('AlienVault OTX') || lower.includes('alienvault') || (lower.includes('otx') && !lower.includes('kaspersky'))) return 'AlienVault OTX';



        if (titleText.startsWith('RansomLook.io') || lower.includes('ransomlook')) return 'RansomLook.io';



        if (titleText.startsWith('Ransomware.live') || lower.includes('rwlive')) return 'Ransomware.live';



