        if (titleText.startsWith('Local Yara') || lower.includes('yara_forge') || lower.includes('local yara')) return 'Local Yara Rules';



        if (titleText.startsWith('URLScan Download Sources') || lower.includes('urlscan download')) return 'URLScan Download Sources';



