        if (titleText.startsWith('Triage') || lower.includes('triage')) return 'Triage Sandbox';



        if (titleText.startsWith('Silent Push') || lower.includes('silentpush') || lower.includes('silent push')) return 'Silent Push';



        if (titleText.startsWith('Pulsedive') || lower.includes('pulsedive')) return 'Pulsedive';



        if (titleText.startsWith('Driftnet') || lower.includes('driftnet')) return 'Driftnet';



        if (titleText.startsWith('Kaspersky') || titleText.startsWith('Kaspersky TIP') || lower.includes('kaspersky')) return 'Kaspersky TIP';



        if (titleText.startsWith('ThreatBook') || lower.includes('threatbook')) return 'ThreatBook';



        if (titleText.startsWith('CIRCL Hashlookup') || lower.includes('circl hashlookup')) return 'CIRCL Hashlookup';



        if (titleText.startsWith('AbuseIPDB') || lower.includes('abuseipdb')) return 'AbuseIPDB';



