        if (titleText.startsWith('Censys') || lower.includes('censys')) return 'Censys';



        if (titleText.startsWith('Etugen') || lower.includes('etugen')) return 'Etugen';



        if (titleText.startsWith('Validin') || lower.includes('validin')) return 'Validin';



        if (titleText.startsWith('FOFA') || lower.includes('fofa')) return 'FOFA';



        if (titleText.startsWith('DNSDumpster') || lower.includes('dnsdumpster')) return 'DNSDumpster';



        if (titleText.startsWith('MalShare') || lower.includes('malshare')) return 'MalShare';



        if (titleText.startsWith('Malware.News') || lower.includes('malware.news') || lower.includes('malware_news')) return 'Malware.News';



        if (titleText.startsWith('Twitter') || lower.includes('twitter')) return 'Twitter';



        if (titleText.startsWith('Internet Archive') || lower.includes('internet archive')) return 'Internet Archive';



        if (titleText.startsWith('CyberBriefing') || lower.includes('cyberbriefing') || lower.includes('cb -') || lower.includes('loading cb')) return 'CyberBriefing';



        if (titleText.startsWith('Hybrid Analysis') || lower.includes('hybrid analysis') || lower.includes('ha -') || lower.includes('loading ha') || lower.includes('hybrid-analysis')) return 'Hybrid Analysis';



        if (titleText.startsWith('ThreatMiner') || lower.includes('threatminer')) return 'ThreatMiner';



        if (titleText.startsWith('URLhaus') || titleText.startsWith('Urlhaus') || lower.includes('urlhaus')) return 'URLhaus';



        if (titleText.startsWith('Network Intelligence') || titleText.startsWith('RIPEstat') || lower.includes('ripestat') || (lower.includes('network intelligence') && lower.includes('ripe'))) return 'RIPEstat';



