    const AI_META_KEYS = new Set(['indicator', 'type', 'query_type', 'hash_algorithm', 'duration_ms', 'sources_queried', 'error', 'ai_notes']);







    const aiCompactValue = (value, depth = 0) => {



        if (value === null || value === undefined) return value;



        if (depth > 7) return '[truncated-depth]';



        if (typeof value === 'string') {



            const text = value.trim();



            return text.length > 900 ? `${text.slice(0, 900)}...[truncated]` : text;



        }



        if (typeof value !== 'object') return value;



        if (Array.isArray(value)) {



            const limit = depth < 3 ? 25 : 12;



            const out = value.slice(0, limit).map(item => aiCompactValue(item, depth + 1));



            if (value.length > limit) out.push(`[${value.length - limit} more item(s) omitted]`);



            return out;



        }



        const entries = Object.entries(value).filter(([, item]) => item !== null && item !== undefined && item !== '');



        const limit = depth < 3 ? 50 : 25;



        const out = {};



        entries.slice(0, limit).forEach(([key, item]) => { out[String(key).slice(0, 80)] = aiCompactValue(item, depth + 1); });



        if (entries.length > limit) out.__omitted_keys = entries.length - limit;



        return out;



    };







    const aiCountFindings = (value) => {



        if (!value || typeof value !== 'object') return 0;



        if (Array.isArray(value)) return value.length;



        for (const key of ['results', 'data', 'records', 'matches', 'articles', 'tweets', 'posts', 'victims', 'pulses', 'detections', 'relationships']) {



            if (Array.isArray(value[key])) return value[key].length;



        }



        return Object.keys(value).filter(key => !['raw', 'normalized', 'meta'].includes(key)).length;



    };







    const aiAddArtifact = (map, type, value, source) => {



        const clean = String(value || '').trim();



        if (!clean) return;



        const key = `${type}:${clean.toLowerCase()}`;



        if (!map.has(key)) map.set(key, { type, value: clean.slice(0, 500), sources: new Set() });



        if (source) map.get(key).sources.add(source);



    };







    const aiExtractArtifacts = (value, source, map, budget = { nodes: 0 }) => {



        if (!value || budget.nodes > 3500 || map.size > 250) return;



        budget.nodes += 1;



        if (typeof value === 'string') {



            const text = value.slice(0, 8000);



            (text.match(/\b[a-fA-F0-9]{32}\b|\b[a-fA-F0-9]{40}\b|\b[a-fA-F0-9]{64}\b/g) || []).forEach(v => aiAddArtifact(map, 'hash', v.toLowerCase(), source));



            (text.match(/\bCVE-\d{4}-\d{4,7}\b/gi) || []).forEach(v => aiAddArtifact(map, 'cve', v.toUpperCase(), source));



            (text.match(/\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g) || []).forEach(v => aiAddArtifact(map, 'ip', v, source));



            (text.match(/https?:\/\/[^\s"'<>]+/gi) || []).forEach(v => aiAddArtifact(map, 'url', v.replace(/[),.;]+$/, ''), source));



            (text.match(/\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}\b/gi) || [])



                .filter(v => !/^(www\.w3\.org|schema\.org)$/i.test(v))



                .forEach(v => aiAddArtifact(map, 'domain', v.toLowerCase(), source));



            return;



        }



        if (Array.isArray(value)) {



            value.slice(0, 120).forEach(item => aiExtractArtifacts(item, source, map, budget));



            return;



        }



        if (typeof value === 'object') {



            Object.entries(value).slice(0, 160).forEach(([key, item]) => {



                const nextSource = source || String(key || 'result');



                aiExtractArtifacts(item, nextSource, map, budget);



            });



        }



    };







    const buildMantisAiFindingsSnapshot = (results) => {



        if (!results) {



            return { findings: null, providers: [], artifacts: [], meta: { has_raw_findings: false } };



        }



        const providerEntries = [];



        const findings = {};



        const artifactMap = new Map();



        const root = Array.isArray(results) ? { results_array: results } : results;



        const topEntries = Object.entries(root || {});



        topEntries.forEach(([key, value]) => {



            if (AI_META_KEYS.has(key)) return;



            if (!value || typeof value !== 'object') return;



            const status = value.error ? 'error' : aiCountFindings(value) > 0 ? 'findings_or_context' : 'no_obvious_findings';



            const count = aiCountFindings(value);



            providerEntries.push({ provider: key, status, count, error: value.error ? String(value.error).slice(0, 240) : '' });



            findings[key] = aiCompactValue(value);



            aiExtractArtifacts(value, key, artifactMap);



        });



        const artifacts = [...artifactMap.values()].slice(0, 180).map(item => ({



            type: item.type,



            value: item.value,



            sources: [...item.sources].slice(0, 8)



        }));



        return {



            findings,



            providers: providerEntries,



            artifacts,



            meta: {



                has_raw_findings: true,



                raw_result_shape: Array.isArray(results) ? 'results_array' : 'single_object',



                raw_top_level_keys: topEntries.length,



                providers_in_snapshot: providerEntries.length,



                artifact_count: artifacts.length,



                omitted_raw_result: true,



                note: 'AI receives this compact evidence snapshot, not the full downloadable JSON.'



            }



        };



    };







    window.mantisGetState = () => {



        let visibleText = '';



        const paneIds = ['results-container', ...AUXILIARY_PANE_IDS];



        for (const id of paneIds) {



            const el = document.getElementById(id);



            if (el && el.offsetParent !== null) {



                visibleText = (el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 6000);



                break;



            }



        }



        const aiSnapshot = buildMantisAiFindingsSnapshot(currentResults);



        return {



            page: currentTab,



            title: tabTitle ? tabTitle.textContent : '',



            query: {



                value: inputField ? inputField.value.trim() : '',



                keyword_type: activeKeywordType || 'all'



            },



            context_meta: aiSnapshot.meta,



            providers: aiSnapshot.providers,



            artifacts: aiSnapshot.artifacts,



            findings: aiSnapshot.findings,



            visible_text: visibleText



        };



    };







    window.mantisRunApprovedAction = async (frontendAction) => {



        const action = frontendAction || {};



        const tab = action.tab || 'keyword';



        const value = action.value || '';



        const nav = document.querySelector(`.nav-item[data-tab="${tab}"]`);



        if (nav) nav.click();



        await new Promise(resolve => setTimeout(resolve, 80));







        if (['hash', 'domain', 'ip', 'url', 'keyword', 'infra'].includes(tab)) {



            if (tab === 'keyword' && keywordTypeSelect) {



                activeKeywordType = action.keyword_type || 'all';



                keywordTypeSelect.value = activeKeywordType;



            }



            const _IOC_ACTION_TYPES = ['hash', 'domain', 'ip', 'url', 'keyword'];



            if (_IOC_ACTION_TYPES.includes(tab) && typeof switchToIocSearch === 'function') switchToIocSearch(tab);



            if (inputField) inputField.value = value;



            await performSearch();



            return;



        }







        if (tab === 'cti') {



            const input = document.getElementById('cti-search-input');



            if (input) input.value = value;



            if (typeof ctiLoadFeed === 'function') ctiLoadFeed(true);



            return;



        }







        if (tab === 'ta' || tab === 'mwtools') {



            const input = document.getElementById('galaxy-search');



            if (input) input.value = value;



            if (typeof runGalaxySearch === 'function') runGalaxySearch(true);



            return;



        }







        if (tab === 'yara-explorer') {



            const input = document.getElementById('yara-exp-search');



            if (input) input.value = value;



            if (typeof yaraExplorerSearch === 'function') yaraExplorerSearch();



        }



    };







    searchBtn.addEventListener('click', performSearch);



    window.performSearch = performSearch;







    const aiSearchBtn = document.getElementById('btn-ai-search');



    if (aiSearchBtn) {



        aiSearchBtn.addEventListener('click', async () => {



            if (typeof window.mantisAI?.runAeadWorkflow === 'function') {



                await window.mantisAI.runAeadWorkflow();



            } else if (typeof showNotification === 'function') {



                showNotification('MANTIS AI module initializing. Please wait...');



            }



        });



    }



    inputField.addEventListener('keypress', (e) => {



        if (e.key === 'Enter') performSearch();



    });







    if (inputField) inputField.addEventListener('input', handleRealtimeAutoDetect);







    window.addEventListener('message', (e) => {



        if (e.data && e.data.action === 'mantis_pivot' && e.data.indicator) {



            const val = e.data.indicator;



            const typ = e.data.type || 'auto';



            if (typeof switchToIocSearch === 'function') {



                switchToIocSearch(typ);



            }



            if (inputField) {



                inputField.value = val;



                inputField.focus();



            }



            const viewer = document.getElementById('report-viewer-modal');



            if (viewer) viewer.style.display = 'none';



            performSearch();



        }



    });







    saveBtn.addEventListener('click', () => {



        if (!currentResults) return;







        let dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(currentResults, null, 2));



        const date = new Date().toISOString().replace(/[:.]/g, '-');



        const resultLabel = Array.isArray(currentResults)



            ? 'imported_results'



            : String(currentResults.indicator || inputField?.value || 'result').replace(/[^a-z0-9]/gi, '_');



        const fname = `intel_${currentTab}_${resultLabel}_${date}.json`;







        const downloadAnchorNode = document.createElement('a');



        downloadAnchorNode.setAttribute("href", dataStr);



        downloadAnchorNode.setAttribute("download", fname);



        document.body.appendChild(downloadAnchorNode);



        downloadAnchorNode.click();



        downloadAnchorNode.remove();



    });







    const renderVtRelationData = (relation, items) => {



        let rendered = false;



        const relationTitle = relation.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());



        let html = `<h4 style="margin-bottom:8px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:4px; color:var(--accent); font-size:0.9rem;">${relationTitle}</h4>`;







        html += `<div style="max-height: 400px; overflow-y:auto; padding-right:8px; display:flex; flex-direction:column; gap:8px;" class="dark-scroll">`;







        if (relation === 'resolutions') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                const dateStr = attr.date ? new Date(attr.date * 1000).toLocaleString() : 'Unknown';



                const val = attr.ip_address || attr.host_name || '';



                const type = attr.ip_address ? 'ip' : 'domain';



                return `<div style="background:rgba(0,0,0,0.2); padding:8px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                    <div style="color:var(--text-muted); font-size:0.75rem;"><i class="fa-solid fa-clock"></i> ${dateStr}</div>



                    <div style="font-family:var(--font-mono); margin-top:4px;">



                        <a href="#" class="pivot-link" data-type="${type}" data-indicator="${esc(val)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); padding-bottom:1px;">${esc(val)}</a>



                    </div>



                </div>`;



            }).join('');



        } else if (relation === 'subdomains') {



            rendered = true;



            html += items.map(item => `<div style="background:rgba(0,0,0,0.2); padding:8px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-family:var(--font-mono); font-size:0.8rem;">



                <a href="#" class="pivot-link" data-type="domain" data-indicator="${esc(item.id)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); padding-bottom:1px;">${esc(item.id)}</a>



            </div>`).join('');



        } else if (relation === 'compressed_parents') {



            rendered = true;



            html += renderVtCompressedParents(items);



        } else if (relation.endsWith('files') || relation === 'execution_parents' || relation === 'pe_resource_parents') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                const size = attr.size ? Math.round(attr.size / 1024) + ' KB' : 'Unknown';



                const name = attr.meaningful_name || (attr.names && attr.names[0]) || 'Unknown';



                const displayId = attr.md5 ? attr.md5 : item.id;



                return `<div style="background:rgba(0,0,0,0.2); padding:10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                    <div style="font-family:var(--font-mono); margin-bottom:4px; word-break:break-all;">



                        <a href="#" class="pivot-link" data-type="hash" data-indicator="${esc(displayId)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); padding-bottom:1px;">${esc(displayId)}</a>



                    </div>



                    <div><strong style="color:var(--text-muted);">Name:</strong> ${esc(name)}</div>



                    <div><strong style="color:var(--text-muted);">Size:</strong> ${size}</div>



                    ${attr.type_description ? `<div><strong style="color:var(--text-muted);">Type:</strong> ${esc(attr.type_description)}</div>` : ''}



                </div>`;



            }).join('');



        } else if (relation.endsWith('domains') || relation.endsWith('ips') || relation.endsWith('urls') || relation === 'redirects_to') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                let val = '';



                let type = 'domain';



                if (relation.endsWith('domains')) { val = item.id; type = 'domain'; }



                else if (relation.endsWith('ips')) { val = item.id; type = 'ip'; }



                else if (relation.endsWith('urls') || relation === 'redirects_to') { val = attr.url || item.id; type = 'url'; }



                return `<div style="background:rgba(0,0,0,0.2); padding:8px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-family:var(--font-mono); font-size:0.8rem; word-break:break-all;">



                    <a href="#" class="pivot-link" data-type="${type}" data-indicator="${esc(val)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); padding-bottom:1px;">${esc(val)}</a>



                </div>`;



            }).join('');



        } else if (relation === 'behaviour_summary') {



            rendered = true;



            const attr = items || {};







            if (attr.attack_techniques && Object.keys(attr.attack_techniques).length > 0) {



                html += `<div><h5 style="color:var(--text-main); font-size:0.85rem; margin-bottom:6px;">MITRE ATT&CK</h5><div style="display:flex; flex-direction:column; gap:4px;">`;



                for (const [tCode, tData] of Object.entries(attr.attack_techniques)) {



                    html += `<div style="background:rgba(0,0,0,0.2); padding:6px 10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                        <strong style="color:var(--highlight);">${esc(tCode)}</strong> 



                        <span style="color:var(--text-muted); margin-left:6px;">${esc(tData.length > 0 ? tData[0].name : '')}</span>



                    </div>`;



                }



                html += `</div></div>`;



            }







            if (attr.http_conversations && attr.http_conversations.length > 0) {



                html += `<div style="margin-top:10px;"><h5 style="color:var(--text-main); font-size:0.85rem; margin-bottom:6px;">HTTP Conversations</h5><div style="display:flex; flex-direction:column; gap:4px;">`;



                html += attr.http_conversations.map(http => `



                    <div style="background:rgba(0,0,0,0.2); padding:6px 10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                        <span style="color:var(--accent); font-weight:600; margin-right:8px;">${esc(http.request_method || 'GET')}</span>



                        <a href="#" class="pivot-link" data-type="url" data-indicator="${esc(http.url)}" style="color:var(--text-main); font-family:var(--font-mono); text-decoration:none; border-bottom:1px dashed var(--text-main);">${esc(http.url)}</a>



                    </div>



                `).join('');



                html += `</div></div>`;



            }







            if (attr.dns_lookups && attr.dns_lookups.length > 0) {



                html += `<div style="margin-top:10px;"><h5 style="color:var(--text-main); font-size:0.85rem; margin-bottom:6px;">DNS Lookups</h5><div style="display:flex; flex-wrap:wrap; gap:4px;">`;



                html += attr.dns_lookups.map(dns => `



                    <div style="background:rgba(0,0,0,0.2); padding:4px 8px; border-radius:4px; border:1px solid rgba(255,255,255,0.05); font-size:0.75rem; font-family:var(--font-mono);">



                        <a href="#" class="pivot-link" data-type="domain" data-indicator="${esc(dns.hostname)}" style="color:var(--accent); text-decoration:none;">${esc(dns.hostname)}</a>



                    </div>



                `).join('');



                html += `</div></div>`;



            }







            if (attr.processes_tree && attr.processes_tree.length > 0) {



                html += `<div style="margin-top:10px;"><h5 style="color:var(--text-main); font-size:0.85rem; margin-bottom:6px;">Processes Created</h5><div style="display:flex; flex-direction:column; gap:4px;">`;



                html += attr.processes_tree.map(proc => `



                    <div style="background:rgba(0,0,0,0.2); padding:6px 10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.75rem; font-family:var(--font-mono); color:var(--text-muted); word-break:break-all;">



                        ${esc(proc.name)}



                    </div>



                `).join('');



                html += `</div></div>`;



            }



        } else if (relation === 'historical_whois') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                const dateStr = attr.whois_date ? new Date(attr.whois_date * 1000).toLocaleString() : 'Unknown';



                return `<div style="background:rgba(0,0,0,0.2); padding:10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                    <div style="color:var(--text-muted); font-size:0.75rem; margin-bottom:8px;"><i class="fa-solid fa-clock"></i> ${dateStr}</div>



                    <pre style="white-space:pre-wrap; font-family:var(--font-mono); font-size:0.75rem; color:var(--text-main); margin:0;">${esc(attr.whois_map ? JSON.stringify(attr.whois_map, null, 2) : (attr.whois_record || ''))}</pre>



                </div>`;



            }).join('');



        } else if (relation === 'historical_ssl_certificates') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                const issuer = attr.issuer ? Object.entries(attr.issuer).map(([k, v]) => `${k}=${v}`).join(', ') : 'Unknown';



                const subject = attr.subject ? Object.entries(attr.subject).map(([k, v]) => `${k}=${v}`).join(', ') : 'Unknown';



                return `<div style="background:rgba(0,0,0,0.2); padding:10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                    <div><strong style="color:var(--text-muted);">Issuer:</strong> ${esc(issuer)}</div>



                    <div style="margin-top:4px;"><strong style="color:var(--text-muted);">Subject:</strong> ${esc(subject)}</div>



                    ${attr.validity ? `<div style="margin-top:4px; font-size:0.75rem; color:var(--text-muted);"><i class="fa-solid fa-calendar"></i> ${esc(attr.validity.not_before)} to ${esc(attr.validity.not_after)}</div>` : ''}



                </div>`;



            }).join('');



        } else if (relation === 'collections' || relation === 'graphs') {



            rendered = true;



            html += items.map(item => {



                const attr = item.attributes || {};



                return `<div style="background:rgba(0,0,0,0.2); padding:10px; border-radius:6px; border:1px solid rgba(255,255,255,0.05); font-size:0.8rem;">



                    <div style="font-weight:600; color:var(--highlight); margin-bottom:4px;">${esc(attr.name || item.id)}</div>



                    ${attr.description ? `<div style="color:var(--text-main); font-size:0.75rem; margin-bottom:6px;">${esc(attr.description)}</div>` : ''}



                    <div style="color:var(--text-muted); font-size:0.75rem;"><i class="fa-solid fa-link"></i> <a href="https://www.virustotal.com/gui/${relation === 'collections' ? 'collection' : 'graph'}/${esc(item.id)}" target="_blank" style="color:var(--accent); text-decoration:none;">View on VirusTotal</a></div>



                </div>`;



            }).join('');



        }







        if (!rendered) {



            html += renderGenericRecordCards(items);



        }







        html += `</div>`;



        return html;



    };







