    function getCountryMeta(country) {



        if (countryMeta[country]) return countryMeta[country];



        if (country && country.length === 2) {



            return { color: '#e3b341', flag: `<img src="https://flagcdn.com/24x18/${country.toLowerCase()}.png" alt="${esc(country)}" style="width:16px;vertical-align:middle;border-radius:2px;">` };



        }



        return { color: '#e3b341', flag: '<i class="fa-solid fa-globe" style="font-size:14px;vertical-align:middle;"></i>' };



    }







    // ---------------------------------------------------------------



    // MISP Galaxy browser (Threat Actor subtabs + Malware & Tools tab).



    // Reuses the Threat Actor UX patterns: search box, card grid, count,



    // detail modal. Searching/ranking runs server-side via



    // GET /api/misp-galaxy/search.



    // ---------------------------------------------------------------



    // No "All" pill: the parent nav item itself means "all sources in this



    // group". When an all-scope is active, no pill is highlighted.



    const GALAXY_SECTION_ORDER = {

        'threat-actor': ['all-threat-actors', 'threat-actor', 'microsoft-activity-group', 'tidal-groups', 'surveillance-vendor'],

        'malware-tools': [

            'all-malware-tools',

            'tool', 'rat', 'ransomware', 'botnet', 'android', 'rmm-tool', 'stalkerware', 'exploit-kit', 'cryptominers', 'tds',

            'malpedia-win', 'malpedia-elf', 'malpedia-osx', 'malpedia-apk', 'malpedia-scripts', 'malpedia-other'

        ]

    };



    // Top-border line color per Malware & Tools category. Threat Actor cards



    // instead use the country color from getCountryMeta().



    const GALAXY_CAT_COLORS = {

        'all-malware-tools': '#00d2d3',

        'tool': '#4a9eff',

        'rat': '#b388ff',

        'ransomware': '#ff5d5d',

        'botnet': '#ff9f43',

        'android': '#3ddc84',

        'rmm-tool': '#4dd0e1',

        'stalkerware': '#f06292',

        'exploit-kit': '#ffd54f',

        'cryptominers': '#26a69a',

        'tds': '#90a4b8',

        'malpedia-win': '#00d2d3',

        'malpedia-elf': '#ff9f43',

        'malpedia-osx': '#ee5253',

        'malpedia-apk': '#10ac84',

        'malpedia-scripts': '#54a0ff',

        'malpedia-other': '#a29bfe'

    };



    const GALAXY_PAGE_SIZE = 50;



    const GALAXY_ALL_LABEL = { 'all-threat-actors': 'All', 'all-malware-tools': 'All' };



    let galaxyCatMeta = null; // category key -> {label, short, group, ...}



    let galaxyMetaFailed = false;



    const galaxyState = { section: 'threat-actor', cat: 'all-threat-actors', results: [], total: 0, query: '', page: 1 };



    let galaxySearchTimer = null;



    let galaxySearchSeq = 0;







    async function ensureGalaxyMeta() {



        if (galaxyCatMeta || galaxyMetaFailed) return galaxyCatMeta;



        try {



            const res = await fetch('/api/misp-galaxy/categories');



            if (!res.ok) throw new Error('categories fetch failed');



            const data = await res.json();



            galaxyCatMeta = data.categories || {};



        } catch (e) {



            galaxyMetaFailed = true;



            galaxyCatMeta = null;



        }



        return galaxyCatMeta;



    }







    function galaxyShortLabel(cat) {

        if (GALAXY_ALL_LABEL[cat]) return GALAXY_ALL_LABEL[cat];

        if (cat && cat.startsWith('malpedia-')) {

            const sub = cat.replace('malpedia-', '');

            const map = { win: 'Malpedia Win', elf: 'Malpedia Linux', osx: 'Malpedia Mac', apk: 'Malpedia APK', scripts: 'Malpedia Scripts', other: 'Malpedia Other' };

            return map[sub] || (galaxyCatMeta && galaxyCatMeta[cat]?.short) || cat;

        }

        if (galaxyCatMeta && galaxyCatMeta[cat]) return galaxyCatMeta[cat].short || galaxyCatMeta[cat].label || cat;

        return cat;

    }







    async function openGalaxyPane(section, cat) {



        const grid = document.getElementById('galaxy-grid');



        if (grid && !galaxyCatMeta && !galaxyMetaFailed) {



            grid.innerHTML = '<div style="color:var(--text-muted); padding:24px; text-align:center;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Initializing MISP Galaxy metadata...</div>';



        }



        galaxyState.section = section;



        galaxyState.cat = cat;



        await ensureGalaxyMeta();



        renderGalaxySubtabs();



        const input = document.getElementById('galaxy-search');



        if (input && document.activeElement !== input) {



            // Keep the current query when switching subtabs so analysts can



            // pivot the same term across Galaxies; start empty on first open.



        }



        bindGalaxySearch();



        runGalaxySearch(true);



    }







    function renderGalaxySubtabs() {



        const bar = document.getElementById('galaxy-subtabs');



        if (!bar) return;



        bar.innerHTML = '';



        (GALAXY_SECTION_ORDER[galaxyState.section] || []).forEach(cat => {



            const btn = document.createElement('button');



            btn.type = 'button';



            btn.className = 'galaxy-subtab' + (cat === galaxyState.cat ? ' active' : '');



            btn.textContent = galaxyShortLabel(cat);



            btn.title = (galaxyCatMeta && galaxyCatMeta[cat] && galaxyCatMeta[cat].label) || cat;



            btn.addEventListener('click', () => {



                if (galaxyState.cat === cat) return;



                galaxyState.cat = cat;



                renderGalaxySubtabs();



                syncGalaxyNavToPane();



                runGalaxySearch(true);



            });



            bar.appendChild(btn);



        });



    }







    let galaxySearchBound = false;



    function bindGalaxySearch() {



        if (galaxySearchBound) return;



        galaxySearchBound = true;



        const input = document.getElementById('galaxy-search');



        if (!input) return;



        input.addEventListener('input', () => {



            if (galaxySearchTimer) clearTimeout(galaxySearchTimer);



            galaxySearchTimer = setTimeout(() => runGalaxySearch(false), 300);



        });



        input.addEventListener('keydown', (e) => {



            if (e.key === 'Enter') {



                if (galaxySearchTimer) clearTimeout(galaxySearchTimer);



                runGalaxySearch(false);



            }



        });



    }







    async function runGalaxySearch() {



        const input = document.getElementById('galaxy-search');



        const grid = document.getElementById('galaxy-grid');



        const query = input ? input.value.trim() : '';



        // New scope or new query always restarts from page 1.



        const scopeKey = `${galaxyState.cat}\n${query}`;



        if (scopeKey !== galaxyState._scopeKey) {



            galaxyState._scopeKey = scopeKey;



            galaxyState.page = 1;



        }



        galaxyState.query = query;



        const mySeq = ++galaxySearchSeq;



        const gCount = document.getElementById('galaxy-count');



        if (gCount) gCount.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i>';



        if (grid) grid.innerHTML = '<div style="color:var(--text-muted); padding:20px;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Searching MISP Galaxy...</div>';



        renderGalaxyPagers();



        try {



            const offset = (galaxyState.page - 1) * GALAXY_PAGE_SIZE;



            const res = await fetch(`/api/misp-galaxy/search?category=${encodeURIComponent(galaxyState.cat)}&q=${encodeURIComponent(query)}&limit=${GALAXY_PAGE_SIZE}&offset=${offset}`);



            if (!res.ok) {



                const err = await res.json().catch(() => ({}));



                throw new Error(err.detail || `Search failed (HTTP ${res.status})`);



            }



            const data = await res.json();



            if (mySeq !== galaxySearchSeq) return; // stale response



            galaxyState.results = Array.isArray(data.results) ? data.results : [];



            galaxyState.total = data.total || 0;



            renderGalaxyCards();



        } catch (e) {



            if (mySeq !== galaxySearchSeq) return;



            galaxyState.results = [];



            galaxyState.total = 0;



            if (grid) grid.innerHTML = `<div style="color:#ff6b6b; padding:20px;">Galaxy search failed: ${esc(e.message)}. Ensure the backend is running.</div>`;



            const count = document.getElementById('galaxy-count');



            if (count) count.textContent = '0';



            renderGalaxyPagers();



        }



    }







    function galaxyTotalPages() {



        return Math.max(1, Math.ceil((galaxyState.total || 0) / GALAXY_PAGE_SIZE));



    }







    function clearGalaxyPagers() {



        ['galaxy-pager-top', 'galaxy-pager-bottom'].forEach(id => {



            const bar = document.getElementById(id);



            if (bar) bar.innerHTML = '';



        });



    }







    function renderGalaxyPagers() {



        const pages = galaxyTotalPages();



        ['galaxy-pager-top', 'galaxy-pager-bottom'].forEach(id => {



            const bar = document.getElementById(id);



            if (!bar) return;



            bar.innerHTML = '';



            if (!galaxyState.total) return;



            const page = Math.min(galaxyState.page, pages);



            const start = (page - 1) * GALAXY_PAGE_SIZE + 1;



            const end = Math.min(page * GALAXY_PAGE_SIZE, galaxyState.total);



            const info = document.createElement('span');



            info.className = 'galaxy-page-info';



            info.textContent = `Showing ${start}–${end} of ${galaxyState.total}`;



            if (pages <= 1) {



                bar.appendChild(info);



                return;



            }



            const go = (target) => {



                const clamped = Math.max(1, Math.min(pages, target));



                if (clamped === galaxyState.page) return;



                galaxyState.page = clamped;



                runGalaxySearch();



                const grid = document.getElementById('galaxy-grid');



                if (grid) grid.scrollTop = 0;



            };



            const mkBtn = (label, target, disabled, active, title) => {



                const b = document.createElement('button');



                b.type = 'button';



                b.className = 'galaxy-page-btn' + (active ? ' active' : '');



                b.textContent = label;



                if (title) b.title = title;



                if (disabled) b.disabled = true;



                else b.addEventListener('click', () => go(target));



                return b;



            };



            bar.appendChild(mkBtn('‹ Prev', page - 1, page <= 1, false, 'Previous page'));



            // Windowed page numbers: 1 … p-1 p p+1 … N



            const nums = new Set([1, pages, page - 1, page, page + 1]);



            let last = 0;



            [...nums].filter(n => n >= 1 && n <= pages).sort((a, b) => a - b).forEach(n => {



                if (n - last > 1) {



                    const dots = document.createElement('span');



                    dots.className = 'galaxy-page-info';



                    dots.textContent = '…';



                    bar.appendChild(dots);



                }



                bar.appendChild(mkBtn(String(n), n, false, n === page, `Page ${n}`));



                last = n;



            });



            bar.appendChild(mkBtn('Next ›', page + 1, page >= pages, false, 'Next page'));



            bar.appendChild(info);



        });



    }







    // Country flag + top-line color for Threat Actor cards. Galaxy country



    // values are full names ("China", "Lebanon") while the legacy map is



    // ISO-2 keyed, so resolve names first; unmapped countries still get a



    // deterministic distinct color each.



    const GALAXY_COUNTRY_ISO = {



        'china': 'CN', 'russia': 'RU', 'russian federation': 'RU', 'iran': 'IR',



        'north korea': 'KP', 'dprk': 'KP', 'korea, north': 'KP',



        'usa': 'US', 'united states': 'US', 'united states of america': 'US',



        'united kingdom': 'GB', 'uk': 'GB', 'england': 'GB',



        'india': 'IN', 'pakistan': 'PK', 'ukraine': 'UA', 'vietnam': 'VN',



        'brazil': 'BR', 'israel': 'IL', 'lebanon': 'LB', 'turkey': 'TR',



        'turkiye': 'TR', 'palestine': 'PS', 'belarus': 'BY', 'syria': 'SY',



        'south korea': 'KR', 'japan': 'JP', 'germany': 'DE', 'france': 'FR',



        'netherlands': 'NL', 'romania': 'RO', 'nigeria': 'NG', 'moldova': 'MD'



    };



    function galaxyCountryMeta(country) {



        const key = (country || '').trim() || 'Unknown';



        if (typeof countryMeta !== 'undefined' && countryMeta[key]) return countryMeta[key];



        const iso = GALAXY_COUNTRY_ISO[key.toLowerCase()];



        if (iso && typeof countryMeta !== 'undefined' && countryMeta[iso]) return countryMeta[iso];



        let h = 0;



        for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) % 360;



        return { color: `hsl(${h}, 65%, 55%)`, flag: '<i class="fa-solid fa-globe" style="font-size:14px;vertical-align:middle;"></i>' };



    }







    function galaxyCardSource(rec) {



        const label = rec.galaxy_label || rec.category || 'MISP Galaxy';



        return `Source: ${label}`;



    }







    function renderGalaxyCards() {



        const grid = document.getElementById('galaxy-grid');



        if (!grid) return;



        grid.innerHTML = '';



        const count = document.getElementById('galaxy-count');



        if (count) count.textContent = String(galaxyState.total);



        if (!galaxyState.results.length) {



            grid.innerHTML = `<div style="color:var(--text-muted); padding:24px; text-align:center;">No results${galaxyState.query ? ` for &ldquo;${esc(galaxyState.query)}&rdquo;` : ''} in this Galaxy scope.</div>`;



            renderGalaxyPagers();



            return;



        }



        galaxyState.results.forEach(rec => {



            // Top line color: per-country for Threat Actor, per-category



            // for Malware & Tools.



            const primaryCountry = (rec.country && rec.country.length) ? rec.country[0] : '';



            let topColor = 'var(--accent)';



            if (galaxyState.section === 'threat-actor') {



                topColor = galaxyCountryMeta(primaryCountry).color || topColor;



            } else if (GALAXY_CAT_COLORS[rec.category]) {



                topColor = GALAXY_CAT_COLORS[rec.category];



            }



            const card = document.createElement('div');



            card.style.cssText = `background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-top: 3px solid ${topColor}; border-radius: 6px; padding: 15px; cursor: pointer; transition: background 0.2s; display: flex; flex-direction: column;`;



            card.onmouseover = () => card.style.background = 'rgba(255,255,255,0.07)';



            card.onmouseout = () => card.style.background = 'rgba(255,255,255,0.03)';







            let html = `<div style="margin-bottom:8px;">



                <h3 style="margin:0; font-size:1.05rem; color:white; overflow-wrap:anywhere;">${esc(rec.name || 'Unnamed')}</h3>



            </div>



            <div style="font-size:0.75rem; color:var(--text-muted); margin-bottom:4px;"><i class="fa-solid fa-database" style="margin-right:5px; opacity:0.7;"></i>${esc(galaxyCardSource(rec))}</div>`;



            if (rec.possible_related && rec.related_galaxies && rec.related_galaxies.length) {



                html += `<div style="font-size:0.72rem; color:#e3b341; margin-bottom:4px;"><i class="fa-solid fa-triangle-exclamation" style="margin-right:5px;"></i>Possible related entr${rec.related_galaxies.length > 1 ? 'ies' : 'y'} in: ${esc(rec.related_galaxies.map(g => galaxyShortLabel(g)).join(', '))}</div>`;



            }



            if (rec.matched_on && rec.matched_on !== 'Browse') {



                html += `<div style="font-size:0.72rem; color:var(--accent); margin-bottom:6px;"><i class="fa-solid fa-crosshairs" style="margin-right:5px;"></i>${esc(rec.matched_on)}${rec.matched_value ? `: &ldquo;${esc(rec.matched_value)}&rdquo;` : ''}</div>`;



            }



            if (rec.aliases && rec.aliases.length) {



                const shown = rec.aliases.slice(0, 3).map(esc).join(', ');



                const more = rec.aliases.length > 3 ? ` <span style="opacity:0.7;">(+${rec.aliases.length - 3} more)</span>` : '';



                html += `<div style="font-size:0.8rem; color:var(--text-muted); margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">AKA: ${shown}${more}</div>`;



            }



            if (rec.country && rec.country.length) {



                const cMeta = galaxyCountryMeta(rec.country[0]);



                const names = rec.country.slice(0, 3).map(esc).join(', ');



                const more = rec.country.length > 3 ? ` (+${rec.country.length - 3})` : '';



                html += `<div style="font-size:0.78rem; color:var(--text-muted); margin-top:6px; display:flex; align-items:center;">${cMeta.flag}<span style="margin-left:6px;">${names}${more}</span></div>`;



            }



            if (rec.description) {



                html += `<div style="margin-top:10px; font-size:0.85rem; color:var(--text-color); flex:1; display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; text-overflow:ellipsis;">${esc(rec.description)}</div>`;



            }



            card.innerHTML = html;



            card.addEventListener('click', () => openGalaxyModal(rec));



            grid.appendChild(card);



        });



        renderGalaxyPagers();



    }







    function galaxyRefLink(url) {



        const a = document.createElement('a');



        a.href = url;



        a.target = '_blank';



        a.rel = 'noopener';



        a.style.cssText = 'color:#58a6ff; text-decoration:none; font-size:0.85rem; display:flex; align-items:center; gap:5px; word-break:break-all;';



        a.innerHTML = `<i class="fa-solid fa-arrow-up-right-from-square" style="font-size:0.75rem;"></i> ${esc(url)}`;



        a.addEventListener('click', (e) => e.stopPropagation());



        a.onmouseover = () => a.style.textDecoration = 'underline';



        a.onmouseout = () => a.style.textDecoration = 'none';



        return a;



    }







    function galaxyCopyChip(text, title) {



        const chip = document.createElement('button');



        chip.type = 'button';



        chip.className = 'galaxy-chip';



        chip.title = title || 'Click to copy';



        chip.innerHTML = `<i class="fa-solid fa-copy" style="font-size:0.7rem; opacity:0.7;"></i> ${esc(text)}`;



        chip.addEventListener('click', (e) => {



            e.stopPropagation();



            const done = () => showNotification('Copied: ' + text);



            if (navigator.clipboard && navigator.clipboard.writeText) {



                navigator.clipboard.writeText(text).then(done).catch(() => showNotification(text));



            } else showNotification(text);



        });



        return chip;



    }







    // Clean a Galaxy description: strip raw HTML tags, convert Markdown



    // links [text](url) and bare URLs into clickable anchors. Everything



    // else is escaped, so no markup ever renders as raw syntax.



    const trimLinkUrl = (url) => {



        let u = url;



        while (/[.,;:!?]$/.test(u)) u = u.slice(0, -1);



        for (; ;) {



            let depth = 0;



            for (const ch of u) {



                if (ch === '(') depth++;



                else if (ch === ')') depth--;



            }



            if (depth < 0 && u.endsWith(')')) u = u.slice(0, -1);



            else break;



        }



        return [u, url.slice(u.length)];



    };



    const linkAnchor = (label, url) =>



        `<a href="${url}" target="_blank" rel="noopener" style="color:#58a6ff;">${label}</a>`;



    const linkMarkdown = (h) => {



        let out = '', i = 0;



        for (; ;) {



            const m = /\[([^\]]+)\]\(/.exec(h.slice(i));



            if (!m) { out += h.slice(i); break; }



            const start = i + m.index;



            const urlStart = start + m[0].length;



            if (!/^https?:/.test(h.slice(urlStart, urlStart + 8))) {



                out += h.slice(i, urlStart);



                i = urlStart;



                continue;



            }



            let j = urlStart, depth = 1, url = '', ok = false;



            while (j < h.length) {



                const ch = h[j];



                if (ch === '(') { depth++; url += ch; j++; }



                else if (ch === ')') {



                    depth--;



                    if (depth === 0) { j++; ok = true; break; }



                    url += ch; j++;



                }



                else if (/\s/.test(ch) || ch === '<') break;



                else { url += ch; j++; }



            }



            if (ok && url) {



                const [u, trail] = trimLinkUrl(url);



                out += linkAnchor(m[1], u) + trail;



                i = j;



            } else {



                out += m[0];



                i = urlStart;



            }



        }



        return out;



    };



    function galaxyCleanDescription(text) {



        let t = String(text || '');



        if (!t) return '';



        t = t.replace(/<(br|p|li|tr|div|h[1-6]|ul|ol)[^>]*>/gi, '\n');



        t = t.replace(/<[^>]*>/g, '');



        t = t.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')



            .replace(/&#0*39;/g, "'").replace(/&#(\d+);/g, (_, n) => {



                try { return String.fromCharCode(parseInt(n, 10)); } catch (e) { return ''; }



            }).replace(/&amp;/g, '&');



        let h = esc(t);



        h = linkMarkdown(h);



        h = h.replace(/(^|[\s(])(https?:\/\/[^\s<]+)/g, (mm, pre, url) => {



            const [u, trail] = trimLinkUrl(url);



            return `${pre}${linkAnchor(u, u)}${trail}`;



        });



        return h;



    }







    // Collect string values for a set of meta keys (case-insensitive),



    // preserving provider meaning while allowing friendly section labels.



    function galaxyMetaValues(meta, keys) {



        const want = new Set(keys.map(k => String(k).toLowerCase()));



        const out = [];



        Object.entries(meta || {}).forEach(([k, v]) => {



            if (!want.has(String(k).toLowerCase())) return;



            const list = Array.isArray(v) ? v : [v];



            list.forEach(item => {



                const s = String(item == null ? '' : item).trim();



                if (s && !out.includes(s)) out.push(s);



            });



        });



        return out;



    }







    function galaxyChip(text, accent) {



        return `<span style="display:inline-flex; align-items:center; gap:6px; background:${accent ? 'rgba(0,168,142,0.12)' : 'rgba(255,255,255,0.05)'}; border:1px solid ${accent ? 'rgba(0,168,142,0.4)' : 'rgba(255,255,255,0.12)'}; border-radius:999px; padding:3px 11px; font-size:0.75rem; font-weight:700; color:${accent ? 'var(--accent)' : 'var(--text-main)'};">${text}</span>`;



    }







    function openGalaxyModal(rec) {



        const meta = (rec.meta && typeof rec.meta === 'object') ? rec.meta : {};



        document.getElementById('galaxy-modal-title').textContent = rec.name || 'Unnamed';



        document.getElementById('galaxy-modal-entity').textContent = (rec.entity || 'GALAXY').toUpperCase();



        document.getElementById('galaxy-modal-source').textContent = galaxyCardSource(rec);



        document.getElementById('galaxy-modal-galaxy').textContent = rec.galaxy || rec.category || '';



        document.getElementById('galaxy-modal-uuid').textContent = rec.uuid || 'N/A';







        const matchEl = document.getElementById('galaxy-modal-match');



        if (rec.matched_on && rec.matched_on !== 'Browse') {



            matchEl.style.display = 'block';



            matchEl.innerHTML = `<i class="fa-solid fa-crosshairs" style="margin-right:6px; color:var(--accent);"></i>${esc(rec.matched_on)}${rec.matched_value ? `: &ldquo;${esc(rec.matched_value)}&rdquo;` : ''}`;



        } else matchEl.style.display = 'none';







        // Header chips: [Country] [MITRE ATT&CK] [Source] — only what exists.



        const chipsBox = document.getElementById('galaxy-modal-chips');



        chipsBox.innerHTML = '';



        const countries = Array.isArray(rec.country) ? rec.country.filter(Boolean) : [];



        if (countries.length) {



            let flag = '';



            try { flag = (galaxyCountryMeta(countries[0]).flag || ''); } catch (e) { /* globe fallback below */ }



            chipsBox.innerHTML += galaxyChip(`${flag}<span>${esc(countries.join(', '))}</span>`, false);



        }



        const mitreIds = [];



        Object.entries(rec.external_ids || {}).forEach(([k, vals]) => {



            (Array.isArray(vals) ? vals : [vals]).forEach(v => {



                const s = String(v == null ? '' : v).trim();



                if (s && !mitreIds.includes(s)) mitreIds.push({ key: k, value: s });



            });



        });



        mitreIds.slice(0, 3).forEach(({ key, value }) => {



            const label = /attack/i.test(key) ? 'MITRE ATT&CK' : esc(key);



            chipsBox.innerHTML += galaxyChip(`${label}: <span style="font-family:var(--font-mono);">${esc(value)}</span>`, true);



        });



        if (rec.galaxy_label || rec.category) {



            chipsBox.innerHTML += galaxyChip(`Source: ${esc(rec.galaxy_label || rec.category)}`, false);



        }



        chipsBox.style.display = chipsBox.innerHTML ? 'flex' : 'none';







        // Target Categories (dynamic across provider schemas).



        const catWrap = document.getElementById('galaxy-modal-cat-wrap');



        const catBox = document.getElementById('galaxy-modal-cats');



        catBox.innerHTML = '';



        const categories = galaxyMetaValues(meta, ['target_categories', 'target-category', 'cfr-target-category', 'targeted-sector', 'target_sector']);



        if (categories.length) {



            catWrap.style.display = 'block';



            categories.forEach(c => { catBox.innerHTML += galaxyChip(esc(c), false); });



        } else catWrap.style.display = 'none';







        // Observed Countries / Suspected Victims (dynamic across schemas).



        const obsWrap = document.getElementById('galaxy-modal-obs-wrap');



        const obsBox = document.getElementById('galaxy-modal-obs');



        obsBox.innerHTML = '';



        let obs = galaxyMetaValues(meta, ['observed_countries', 'observed-countries']);



        let obsLabel = 'OBSERVED COUNTRIES';



        if (!obs.length) {



            obs = galaxyMetaValues(meta, ['suspected-victims', 'cfr-suspected-victims', 'suspected_victims']);



            obsLabel = 'SUSPECTED VICTIMS';



        }



        if (obs.length) {



            obsWrap.style.display = 'block';



            document.getElementById('galaxy-modal-obs-label').textContent = obsLabel;



            obs.forEach(o => { obsBox.innerHTML += galaxyChip(esc(o), false); });



        } else obsWrap.style.display = 'none';







        // Aliases (click = pivot search in the same section scope).



        const aliasWrap = document.getElementById('galaxy-modal-alias-wrap');



        const aliasBox = document.getElementById('galaxy-modal-aliases');



        aliasBox.innerHTML = '';



        if (rec.aliases && rec.aliases.length) {



            aliasWrap.style.display = 'block';



            rec.aliases.forEach(a => {



                const chip = document.createElement('button');



                chip.type = 'button';



                chip.className = 'galaxy-chip';



                chip.title = 'Search for this alias';



                chip.textContent = a;



                chip.addEventListener('click', () => {



                    document.getElementById('galaxy-modal-overlay').style.display = 'none';



                    pivotGalaxySearch(rec.group, a);



                });



                aliasBox.appendChild(chip);



            });



        } else aliasWrap.style.display = 'none';







        // Description: cleaned markup, hidden when absent.



        const descWrap = document.getElementById('galaxy-modal-desc-wrap');



        if (rec.description && String(rec.description).trim()) {



            descWrap.style.display = 'block';



            document.getElementById('galaxy-modal-desc').innerHTML = galaxyCleanDescription(rec.description);



        } else descWrap.style.display = 'none';







        // References: deduplicated clickable links, hidden when absent.



        const refsWrap = document.getElementById('galaxy-modal-refs-wrap');



        const refsBox = document.getElementById('galaxy-modal-refs');



        refsBox.innerHTML = '';



        const refs = [...new Set((rec.refs || []).map(r => String(r).trim()).filter(Boolean))];



        if (refs.length) {



            refsWrap.style.display = 'block';



            refs.forEach(r => refsBox.appendChild(galaxyRefLink(r)));



        } else refsWrap.style.display = 'none';







        // External IDs (e.g. MITRE ATT&CK group IDs from group_attack_id).



        const extWrap = document.getElementById('galaxy-modal-ext-wrap');



        const extBox = document.getElementById('galaxy-modal-extids');



        extBox.innerHTML = '';



        const extIds = rec.external_ids || {};



        const extKeys = Object.keys(extIds);



        if (extKeys.length) {



            extWrap.style.display = 'block';



            const allMitre = extKeys.every(k => /attack/i.test(k));



            document.getElementById('galaxy-modal-ext-label').textContent = allMitre ? 'MITRE ATT&CK' : 'EXTERNAL IDS';



            extKeys.forEach(k => {



                (extIds[k] || []).forEach(v => {



                    const label = /attack/i.test(k) ? String(v) : `${k}: ${v}`;



                    const chip = galaxyCopyChip(label, 'Click to copy identifier');



                    extBox.appendChild(chip);



                });



            });



        } else extWrap.style.display = 'none';







        // Related Galaxy entries (dest UUIDs from the Galaxy data).



        const relWrap = document.getElementById('galaxy-modal-rel-wrap');



        const relBox = document.getElementById('galaxy-modal-related');



        relBox.innerHTML = '';



        if (rec.related && rec.related.length) {



            relWrap.style.display = 'block';



            rec.related.forEach(r => {



                const chip = document.createElement('button');



                chip.type = 'button';



                chip.className = 'galaxy-chip';



                chip.title = `Related entry (${r.type || 'related'}). Click to look up by UUID.`;



                chip.innerHTML = `<i class="fa-solid fa-diagram-project" style="font-size:0.7rem; opacity:0.7;"></i> ${esc(r['dest-uuid'])}${r.type ? ` (${esc(r.type)})` : ''}`;



                chip.addEventListener('click', () => {



                    document.getElementById('galaxy-modal-overlay').style.display = 'none';



                    pivotGalaxySearch('threat-actor', r['dest-uuid'], 'all');



                });



                relBox.appendChild(chip);



            });



        } else relWrap.style.display = 'none';







        // Manual analyst pivots (only between datasets that exist).



        const pivBox = document.getElementById('galaxy-modal-pivots');



        pivBox.innerHTML = '';



        const mkPivot = (label, icon, fn) => {



            const b = document.createElement('button');



            b.type = 'button';



            b.className = 'galaxy-chip';



            b.innerHTML = `<i class="${icon}" style="font-size:0.7rem; opacity:0.7;"></i> ${esc(label)}`;



            b.addEventListener('click', () => {



                document.getElementById('galaxy-modal-overlay').style.display = 'none';



                fn();



            });



            pivBox.appendChild(b);



        };



        mkPivot('Search Threat Actor', 'fa-solid fa-user-secret', () => pivotGalaxySearch('threat-actor', rec.name));



        mkPivot('Search Malware & Tools', 'fa-solid fa-bug', () => pivotGalaxySearch('malware-tools', rec.name));



        if ((rec.group || '') === 'malware-tools') {



            mkPivot('Keyword lookup', 'fa-solid fa-magnifying-glass', () => {



                if (typeof switchToIocSearch === 'function') switchToIocSearch('keyword');



                setTimeout(() => {



                    const f = document.getElementById('ioc-input');



                    if (f) { f.value = rec.name; }



                    const btn = document.getElementById('btn-search');



                    if (btn) btn.click();



                }, 60);



            });



        }







        document.getElementById('galaxy-modal-overlay').style.display = 'flex';



    }







    // Keep sidebar selection in sync when the scope changes from inside the



    // pane (subtab pills, modal pivots): highlight the matching child, or



    // just the parent when an all-sources scope is active.



    function syncGalaxyNavToPane() {



        const tab = galaxyState.section === 'malware-tools' ? 'mwtools' : 'ta';



        currentTab = tab;



        const child = document.querySelector(`.nav-subitem[data-tab='${tab}'][data-galaxy-cat='${galaxyState.cat}']`);



        const parent = document.querySelector(`.nav-parent[data-tab='${tab}']`);



        setActiveNavigation(tab, child || parent);



        saveNavState(tab, child || parent);



        const base = galaxyState.section === 'malware-tools' ? 'Malware & Tools' : 'Threat Actor';



        const label = child ? (child.querySelector('span')?.textContent || '').trim() : '';



        const titleEl = document.getElementById('current-tab-title');



        if (titleEl) titleEl.textContent = label ? `${base} · ${label}` : base;



    }







    function pivotGalaxySearch(section, term, catOverride) {



        // section: 'threat-actor' | 'malware-tools'. catOverride (e.g. 'all')



        // searches a wider scope than the section default.



        const nav = document.querySelector(section === 'malware-tools'



            ? '.nav-item[data-tab="mwtools"]'



            : '.nav-item[data-tab="ta"]');



        if (nav) nav.click();



        setTimeout(() => {



            if (catOverride) {



                galaxyState.cat = catOverride;



                renderGalaxySubtabs();



            }



            syncGalaxyNavToPane();



            const input = document.getElementById('galaxy-search');



            if (input) {



                input.value = term || '';



                runGalaxySearch(false);



            }



        }, 80);



    }







    function bindGalaxyModal() {



        const overlay = document.getElementById('galaxy-modal-overlay');



        const close = document.getElementById('galaxy-modal-close');



        if (close) close.addEventListener('click', () => overlay.style.display = 'none');



        if (overlay) overlay.addEventListener('click', (e) => {



            if (e.target.id === 'galaxy-modal-overlay') overlay.style.display = 'none';



        });



    }



    bindGalaxyModal();







    // NOTE: the legacy threat-actor pane (initThreatActors/renderTACards/...)



    // was removed; the Galaxy pane serves the same datasets. countryMeta +



    // getCountryMeta above are still used by Galaxy cards.







    // ---------------------------------------------------------------



    // YARA section: Rule Explorer / Sample Scanner / Rule Workbench.



    // All three share the local YARA backend (/api/yara/*); every scan



    // stays on this machine and nothing is submitted externally.



    // ---------------------------------------------------------------



    let yaraReposCache = {};



    let yaraStatusCache = null;







    async function yaraFetchRepos(scope = '') {



        const key = scope || 'all';



        if (yaraReposCache[key]) return yaraReposCache[key];



        const suffix = scope ? `?scope=${encodeURIComponent(scope)}` : '';



        const res = await fetch('/api/yara/repos' + suffix);



        if (!res.ok) throw new Error('Failed to load YARA repositories');



        const data = await res.json();



        yaraReposCache[key] = data.repos || [];



        return yaraReposCache[key];



    }







    async function yaraFetchStatus(force, scope = '') {



        const key = scope || 'all';



        if (!yaraStatusCache) yaraStatusCache = {};



        if (yaraStatusCache[key] && !force) return yaraStatusCache[key];



        const suffix = scope ? `?scope=${encodeURIComponent(scope)}` : '';



        const res = await fetch('/api/yara/status' + suffix);



        if (!res.ok) throw new Error('Failed to load YARA engine status');



        yaraStatusCache[key] = await res.json();



        return yaraStatusCache[key];



    }







    // Fixed pill/dot colors per YARA repository (stable across renames);



    // anything else falls back to a hash-derived hue.



    const YARA_REPO_COLORS = {



        'custom': '#b388ff',



        'kaspersky': '#4a9eff',



        'yaraify': '#ff9f43'



    };



    function yaraRepoColor(id, label) {



        if (id && YARA_REPO_COLORS[id]) return YARA_REPO_COLORS[id];



        let h = 0;



        const s = String(label || id || '?');



        for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;



        return `hsl(${h}, 55%, 55%)`;



    }







    function yaraSwitchTab(tab) {



        const nav = document.querySelector(`.nav-item[data-tab="${tab}"]`);



        if (nav) nav.click();



    }







    // ---------------- Rule Explorer ----------------



    let yaraExpTimer = null;



    let yaraExpSeq = 0;



    let yaraExpBound = false;



    let yaraExpStatus = 'all';



    let yaraExpPage = 1;



    const YARA_EXP_PAGE_SIZE = 50;







    function yaraExpSelectedRepos() {



        return [...document.querySelectorAll('#yara-exp-repos input[type=checkbox]:checked')].map(cb => cb.value);



    }







    const yaraExpRegex = () => document.getElementById('yara-exp-regex')?.classList.contains('active');







    // Persist the explorer scope (unchecked pills, query, status tab, regex)



    // so a refresh or tab revisit restores the analyst's last view. Only



    // explicit unchecks are stored, so newly appearing collections still



    // default on.



    const saveYaraScope = () => {



        try {



            sessionStorage.setItem('mantis_yara_scope', JSON.stringify({



                unchecked: [...document.querySelectorAll('#yara-exp-repos input[type=checkbox]:not(:checked)')].map(cb => cb.value),



                q: (document.getElementById('yara-exp-search')?.value || ''),



                st: yaraExpStatus,



                rx: yaraExpRegex()



            }));



        } catch (e) { /* storage unavailable - pane simply resets */ }



    };







    function restoreYaraScope() {



        let saved = null;



        try { saved = JSON.parse(sessionStorage.getItem('mantis_yara_scope') || 'null'); } catch (e) { return; }



        if (!saved || typeof saved !== 'object') return;



        const input = document.getElementById('yara-exp-search');



        if (input && typeof saved.q === 'string') input.value = saved.q;



        document.getElementById('yara-exp-regex')?.classList.toggle('active', saved.rx === true);



        if (saved.st === 'valid' || saved.st === 'invalid' || saved.st === 'all') {



            yaraExpStatus = saved.st;



            document.querySelectorAll('#yara-exp-status-tabs .galaxy-subtab').forEach(b => b.classList.toggle('active', b.dataset.st === saved.st));



        }



        if (Array.isArray(saved.unchecked) && saved.unchecked.length) {



            const skip = new Set(saved.unchecked);



            document.querySelectorAll('#yara-exp-repos input[type=checkbox]').forEach(cb => {



                if (skip.has(cb.value)) {



                    cb.checked = false;



                    cb.closest('label')?.classList.remove('is-checked');



                }



            });



        }



    }







    async function openYaraExplorer() {



        document.getElementById('yara-explorer-pane').style.display = 'flex';



        const grid = document.getElementById('yara-exp-grid');



        const needsInitialLoad = grid && !grid.dataset.loaded && grid.innerHTML.trim() === '';



        if (needsInitialLoad) {



            grid.innerHTML = '<div style="color:var(--text-muted); padding:24px; text-align:center; grid-column: 1 / -1;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Initializing YARA Explorer metadata...</div>';



        }



        const initialSearch = needsInitialLoad ? yaraExplorerSearch({ skipScopeSave: true }) : Promise.resolve();



        try {



            const st = await yaraFetchStatus(false, 'explorer');



            const el = document.getElementById('yara-engine-status');



            el.innerHTML = `<span><i class="fa-solid fa-microchip" style="margin-right:5px;"></i>Engine: <b style="color:var(--text-main);">${esc(st.engine || '?')}</b></span>`



                + `<span>Repositories: <b style="color:var(--text-main);">${st.repositories || 0}</b></span>`



                + `<span>Rule files: <b style="color:var(--text-main);">${st.rule_files || 0}</b></span>`



                + `<span>Rules: <b style="color:var(--text-main);">${st.rules || 0}</b></span>`



                + `<span>Valid: <b style="color:var(--success);">${st.valid || 0}</b></span>`



                + `<span>Invalid: <b style="color:${(st.invalid || 0) ? 'var(--danger)' : 'var(--text-main)'};">${st.invalid || 0}</b></span>`



                + (st.last_compiled ? `<span>Last compiled: ${esc(st.last_compiled)}</span>` : '');



        } catch (e) {



            document.getElementById('yara-engine-status').textContent = 'Engine status unavailable: ' + e.message;



        }



        let reposReady = false;



        try {



            const repos = await yaraFetchRepos('explorer');



            const box = document.getElementById('yara-exp-repos');



            // Previously unchecked pills stay unchecked; anything new



            // defaults to checked so fresh collections are never silently



            // excluded from searches.



            const prevUnchecked = new Set(



                [...box.querySelectorAll('input[type=checkbox]:not(:checked)')].map(cb => cb.value));



            box.innerHTML = '';



            repos.forEach(r => {



                const lbl = document.createElement('label');



                lbl.className = 'source-pill is-checked';



                lbl.title = r.label;



                lbl.innerHTML = `<input type="checkbox" value="${esc(r.id)}" checked> <span style="display:inline-block; width:9px; height:9px; border-radius:999px; background:${yaraRepoColor(r.id, r.label)};"></span> <span>${esc(r.label)}</span>`;



                const cb = lbl.querySelector('input');



                if (prevUnchecked.has(r.id)) { cb.checked = false; lbl.classList.remove('is-checked'); }



                cb.addEventListener('change', () => {



                    lbl.classList.toggle('is-checked', cb.checked);



                    yaraExpPage = 1;



                    yaraExplorerSearch();



                });



                box.appendChild(lbl);



            });



            box.dataset.built = '1';



            restoreYaraScope();



            reposReady = true;



        } catch (e) { /* search-all still works without the pill list */ }



        if (!yaraExpBound) {



            yaraExpBound = true;



            const input = document.getElementById('yara-exp-search');



            input.addEventListener('input', () => {



                if (yaraExpTimer) clearTimeout(yaraExpTimer);



                yaraExpTimer = setTimeout(() => { yaraExpPage = 1; yaraExplorerSearch(); }, 300);



            });



            input.addEventListener('keydown', (e) => {



                if (e.key === 'Enter') {



                    if (yaraExpTimer) clearTimeout(yaraExpTimer);



                    yaraExpPage = 1;



                    yaraExplorerSearch();



                }



            });



            document.querySelectorAll('#yara-exp-status-tabs .galaxy-subtab').forEach(btn => btn.addEventListener('click', () => {



                if (yaraExpStatus === btn.dataset.st) return;



                yaraExpStatus = btn.dataset.st;



                document.querySelectorAll('#yara-exp-status-tabs .galaxy-subtab').forEach(b => b.classList.toggle('active', b === btn));



                yaraExpPage = 1;



                yaraExplorerSearch();



            }));



            document.getElementById('yara-exp-regex')?.addEventListener('click', (e) => {



                e.currentTarget.classList.toggle('active');



                yaraExpPage = 1;



                yaraExplorerSearch();



            });



            document.getElementById('yara-rule-modal-close').addEventListener('click', () => {



                document.getElementById('yara-rule-modal-overlay').style.display = 'none';



            });



            document.getElementById('yara-rule-modal-overlay').addEventListener('click', (e) => {



                if (e.target.id === 'yara-rule-modal-overlay') document.getElementById('yara-rule-modal-overlay').style.display = 'none';



            });



            document.getElementById('yara-rule-modal-copy').addEventListener('click', () => {



                const src = document.getElementById('yara-rule-modal-source').textContent || '';



                if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(src).then(() => showNotification('Rule copied'));



                else showNotification('Copy unavailable');



            });



            document.getElementById('yara-rule-modal-workbench').addEventListener('click', () => {



                const src = document.getElementById('yara-rule-modal-source').textContent || '';



                const repo = document.getElementById('yara-rule-modal-workbench').dataset.repo || '';



                const file = document.getElementById('yara-rule-modal-workbench').dataset.file || '';



                document.getElementById('yara-rule-modal-overlay').style.display = 'none';



                yaraSwitchTab('yara-workbench');



                setTimeout(() => yaraWorkbenchLoad(src, repo, file), 80);



            });



        }



        if (reposReady) {



            yaraExplorerSearch();



        } else {



            await initialSearch;



        }



    }







    function yaraExpTotalPages(total) {



        return Math.max(1, Math.ceil((total || 0) / YARA_EXP_PAGE_SIZE));



    }







    function yaraRenderExpPagers(total) {



        const pages = yaraExpTotalPages(total);



        ['yara-exp-pager-top', 'yara-exp-pager-bottom'].forEach(id => {



            const bar = document.getElementById(id);



            if (!bar) return;



            bar.innerHTML = '';



            if (!total) return;



            const page = Math.min(yaraExpPage, pages);



            const start = (page - 1) * YARA_EXP_PAGE_SIZE + 1;



            const end = Math.min(page * YARA_EXP_PAGE_SIZE, total);



            const info = document.createElement('span');



            info.className = 'galaxy-page-info';



            info.textContent = `Showing ${start}–${end} of ${total}`;



            if (pages <= 1) {



                bar.appendChild(info);



                return;



            }



            const go = (target) => {



                const clamped = Math.max(1, Math.min(pages, target));



                if (clamped === yaraExpPage) return;



                yaraExpPage = clamped;



                yaraExplorerSearch();



                const grid = document.getElementById('yara-exp-grid');



                if (grid) grid.scrollTop = 0;



            };



            const mkBtn = (label, target, disabled, active, title) => {



                const b = document.createElement('button');



                b.type = 'button';



                b.className = 'galaxy-page-btn' + (active ? ' active' : '');



                b.textContent = label;



                if (title) b.title = title;



                if (disabled) b.disabled = true;



                else b.addEventListener('click', () => go(target));



                return b;



            };



            bar.appendChild(mkBtn('‹ Prev', page - 1, page <= 1, false, 'Previous page'));



            const nums = new Set([1, pages, page - 1, page, page + 1]);



            let last = 0;



            [...nums].filter(n => n >= 1 && n <= pages).sort((a, b) => a - b).forEach(n => {



                if (n - last > 1) {



                    const dots = document.createElement('span');



                    dots.className = 'galaxy-page-info';



                    dots.textContent = '…';



                    bar.appendChild(dots);



                }



                bar.appendChild(mkBtn(String(n), n, false, n === page, `Page ${n}`));



                last = n;



            });



            bar.appendChild(mkBtn('Next ›', page + 1, page >= pages, false, 'Next page'));



            bar.appendChild(info);



        });



    }







    function yaraExpEmptyState(q) {



        if (yaraExpStatus === 'invalid' && !q) {



            return `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-circle-check" style="color: var(--success);"></i><p>All rule collections compile cleanly — no invalid rules to fix.</p></div>`;



        }



        if (yaraExpStatus === 'invalid') {



            return `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-magnifying-glass-chart"></i><p>No invalid rules match &ldquo;${esc(q)}&rdquo;. Try the All tab or clear the search.</p></div>`;



        }



        if (q) {



            return `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-magnifying-glass-chart"></i><p>No rules match &ldquo;${esc(q)}&rdquo; in the selected collections.</p></div>`;



        }



        return `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-magnifying-glass-chart"></i><p>No rules in the selected collections yet. Type to search, or add .yar files to a rule directory.</p></div>`;



    }







    async function yaraExplorerSearch(options = {}) {



        const grid = document.getElementById('yara-exp-grid');



        if (!grid) return;



        const q = (document.getElementById('yara-exp-search')?.value || '').trim();



        const repos = yaraExpSelectedRepos();



        if (!options.skipScopeSave) saveYaraScope();



        const mySeq = ++yaraExpSeq;



        const pillsBuilt = !!document.getElementById('yara-exp-repos')?.dataset.built;



        if (pillsBuilt && !repos.length) {



            document.getElementById('yara-exp-count').textContent = '0';



            grid.innerHTML = `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-layer-group"></i><p>No collections selected. Tick at least one repository pill above to search.</p></div>`;



            grid.dataset.loaded = '1';



            yaraRenderExpPagers(0);



            return;



        }



        document.getElementById('yara-exp-count').innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i>';



        grid.innerHTML = '<div style="color:var(--text-muted); padding:20px;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Searching local YARA rules...</div>';



        yaraRenderExpPagers(0);



        try {



            const offset = (yaraExpPage - 1) * YARA_EXP_PAGE_SIZE;



            const res = await fetch(`/api/yara/rules/search?q=${encodeURIComponent(q)}&repos=${encodeURIComponent(repos.join(','))}&limit=${YARA_EXP_PAGE_SIZE}&offset=${offset}&status=${encodeURIComponent(yaraExpStatus)}&regex=${yaraExpRegex() ? 1 : 0}`);



            if (!res.ok) throw new Error(`Search failed (HTTP ${res.status})`);



            const data = await res.json();



            if (mySeq !== yaraExpSeq) return;



            if (data.error) {



                document.getElementById('yara-exp-count').textContent = '0';



                grid.innerHTML = `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-triangle-exclamation" style="color: var(--danger);"></i><p>${esc(data.error)}</p></div>`;



                yaraRenderExpPagers(0);



                return;



            }



            document.getElementById('yara-exp-count').textContent = String(data.total || 0);



            grid.innerHTML = '';



            if (!data.results || !data.results.length) {



                grid.innerHTML = yaraExpEmptyState(q);



                grid.dataset.loaded = '1';



                yaraRenderExpPagers(0);



                return;



            }



            data.results.forEach(r => {



                const card = document.createElement('div');



                const ok = r.compile_status === 'valid';



                const color = ok ? 'var(--accent)' : 'var(--danger)';



                card.style.cssText = `background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-top: 3px solid ${color}; border-radius: 6px; padding: 15px; cursor: pointer; transition: background 0.2s; display: flex; flex-direction: column;`;



                card.onmouseover = () => card.style.background = 'rgba(255,255,255,0.07)';



                card.onmouseout = () => card.style.background = 'rgba(255,255,255,0.03)';



                const tags = (r.tags || []).slice(0, 4).map(t => `<span style="background:rgba(255,255,255,0.06); border-radius:4px; padding:1px 7px; font-size:0.7rem;">${esc(t)}</span>`).join(' ');



                card.innerHTML = `<div style="margin-bottom:6px;"><h3 style="margin:0; font-size:1rem; color:white; overflow-wrap:anywhere; font-family:var(--font-mono);">${esc(r.rule)}</h3></div>



                    <div style="font-size:0.75rem; color:var(--text-muted); margin-bottom:4px;"><span style="display:inline-block; width:9px; height:9px; border-radius:999px; background:${yaraRepoColor(r.repository, r.repository_label)}; margin-right:6px;"></span>${esc(r.repository_label || r.repository)} ${(r.namespace && r.namespace.toLowerCase() !== (r.repository || '').toLowerCase() && r.namespace.toLowerCase() !== (r.repository_label || '').toLowerCase()) ? `<span style="opacity:0.6;">· ${esc(r.namespace)}</span>` : ''}</div>



                    ${r.collection && r.collection.toLowerCase().replace(/[_\-]/g, ' ') !== (r.rule || '').toLowerCase().replace(/[_\-]/g, ' ') ? `<div style="font-size:0.72rem; color:var(--text-muted); margin-bottom:4px;">Collection: <span style="color:var(--text-main);">${esc(r.collection)}</span></div>` : ''}



                    <div style="font-size:0.72rem; color:var(--text-muted); margin-bottom:4px; font-family:var(--font-mono); overflow-wrap:anywhere;">${esc(r.file || '')}</div>



                    ${tags ? `<div style="display:flex; flex-wrap:wrap; gap:5px; margin:4px 0;">${tags}</div>` : ''}



                    <div style="font-size:0.72rem; margin-top:6px; color:${ok ? 'var(--success)' : 'var(--danger)'};"><i class="fa-solid ${ok ? 'fa-circle-check' : 'fa-circle-exclamation'}"></i> ${ok ? 'Compiles' : 'Invalid — click for errors'}</div>



                    ${r.matched_on && r.matched_on !== 'Browse' ? `<div style="font-size:0.72rem; color:var(--accent); margin-top:4px;">${esc(r.matched_on)}${r.matched_value ? `: &ldquo;${esc(r.matched_value)}&rdquo;` : ''}</div>` : ''}`;



                card.addEventListener('click', () => yaraOpenRuleModal(r.repository, r.rule, r.namespace || ''));



                grid.appendChild(card);



            });



            grid.dataset.loaded = '1';



            yaraRenderExpPagers(data.total || 0);



        } catch (e) {



            if (mySeq !== yaraExpSeq) return;



            grid.innerHTML = `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-solid fa-triangle-exclamation" style="color: var(--danger);"></i><p>Rule search failed: ${esc(e.message)}</p></div>`;



            grid.dataset.loaded = '1';



            yaraRenderExpPagers(0);



        }



    }







    async function yaraOpenRuleModal(repo, rule, namespace) {



        const overlay = document.getElementById('yara-rule-modal-overlay');



        document.getElementById('yara-rule-modal-title').textContent = rule;



        document.getElementById('yara-rule-modal-source').textContent = 'Loading…';



        document.getElementById('yara-rule-modal-errors').innerHTML = '';



        overlay.style.display = 'flex';



        try {



            const res = await fetch(`/api/yara/rule?repo=${encodeURIComponent(repo)}&name=${encodeURIComponent(rule)}&namespace=${encodeURIComponent(namespace || '')}`);



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            const d = await res.json();



            document.getElementById('yara-rule-modal-sub').textContent = `${d.repository_label || d.repository} · ${d.namespace || ''} · ${d.file || ''}${d.collection ? ` · ${d.collection}` : ''}`;



            document.getElementById('yara-rule-modal-source').innerHTML = yaraHighlightSrc(d.source || '(no source captured)');



            document.getElementById('yara-rule-modal-tags').innerHTML = (d.tags || []).map(t => `<span class="galaxy-chip" style="cursor:default;">${esc(t)}</span>`).join('') || '<span style="color:var(--text-muted); font-size:0.8rem;">No tags</span>';



            const errBox = document.getElementById('yara-rule-modal-errors');



            if ((d.compile_status || '') !== 'valid') {



                errBox.innerHTML = `<div class="error-card"><i class="fa-solid fa-circle-exclamation"></i><div>${(d.compile_errors || []).map(e => `<div>${esc(e.message || 'compile error')}</div>`).join('') || 'Does not compile.'}</div></div>`;



            } else errBox.innerHTML = '';



            const wb = document.getElementById('yara-rule-modal-workbench');



            wb.dataset.repo = d.repository || '';



            wb.dataset.file = d.file ? d.file.split(/[\\/]/).pop() : '';



        } catch (e) {



            document.getElementById('yara-rule-modal-source').textContent = 'Failed to load rule: ' + e.message;



        }



    }







    // ---------------- Sample Scanner ----------------



    let yaraScanReposLoaded = false;







    async function openYaraScanner() {



        document.getElementById('yara-scanner-pane').style.display = 'flex';



        const box = document.getElementById('yara-scan-repos');



        if (box && box.innerHTML === '') {



            box.innerHTML = '<div style="color:var(--text-muted); padding:24px; text-align:center;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Initializing YARA Scanner metadata...</div>';



        }



        try {



            const repos = await yaraFetchRepos();



            const box = document.getElementById('yara-scan-repos');



            // Preserve explicit unchecks; new collections default to checked.



            const prevUnchecked = new Set(



                [...box.querySelectorAll('input[type=checkbox]:not(:checked)')].map(cb => cb.value));



            box.innerHTML = '';



            repos.forEach(r => {



                const lbl = document.createElement('label');



                lbl.className = 'source-pill is-checked';



                lbl.innerHTML = `<input type="checkbox" value="${esc(r.id)}" checked> <i class="fa-solid fa-database"></i> <span>${esc(r.label)}</span>`;



                const cb = lbl.querySelector('input');



                if (prevUnchecked.has(r.id)) { cb.checked = false; lbl.classList.remove('is-checked'); }



                cb.addEventListener('change', () => lbl.classList.toggle('is-checked', cb.checked));



                box.appendChild(lbl);



            });



        } catch (e) {



            document.getElementById('yara-scan-repos').innerHTML = '<span style="color:#ff6b6b; font-size:0.85rem;">Repositories unavailable.</span>';



        }



        if (!yaraScanReposLoaded) {



            yaraScanReposLoaded = true;



            const dropzone = document.getElementById('yara-scan-dropzone');



            const fileInput = document.getElementById('yara-scan-file');



            const fileLabel = document.getElementById('yara-scan-filename');







            const handleFile = (f) => {



                if (f) {



                    fileLabel.textContent = `${f.name} (${yaraHumanSize(f.size)})`;



                    fileLabel.style.display = 'block';



                    const dt = new DataTransfer();



                    dt.items.add(f);



                    fileInput.files = dt.files;



                } else {



                    fileLabel.style.display = 'none';



                    fileInput.value = '';



                }



            };







            fileInput.addEventListener('change', (e) => handleFile(e.target.files[0]));



            if (dropzone) {



                dropzone.addEventListener('dragover', (e) => { e.preventDefault(); dropzone.classList.add('dragover'); });



                dropzone.addEventListener('dragleave', (e) => { e.preventDefault(); dropzone.classList.remove('dragover'); });



                dropzone.addEventListener('drop', (e) => {



                    e.preventDefault();



                    dropzone.classList.remove('dragover');



                    handleFile(e.dataTransfer.files[0]);



                });



            }



            document.getElementById('yara-scan-btn').addEventListener('click', yaraRunScan);



        }



    }







    async function yaraRunScan() {



        const input = document.getElementById('yara-scan-file');



        const out = document.getElementById('yara-scan-results');



        const btn = document.getElementById('yara-scan-btn');



        const f = input.files[0];



        if (!f) {



            showNotification('Select a sample file first');



            return;



        }



        const repos = [...document.querySelectorAll('#yara-scan-repos input[type=checkbox]:checked')].map(cb => cb.value);



        if (!repos.length) {



            showNotification('Select at least one collection to scan against');



            return;



        }







        const originalBtnHtml = btn ? btn.innerHTML : 'Scan Sample';



        if (btn) {



            btn.disabled = true;



            btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i> Scanning...';



        }







        out.innerHTML = `



            <div style="padding:36px 20px; text-align:center; background:rgba(0,0,0,0.25); border-radius:8px; border:1px solid rgba(255,204,0,0.2); margin-top:15px;">



                <div style="font-size:2.4rem; color:var(--accent); margin-bottom:12px; display:inline-block;">



                    <i class="fa-solid fa-circle-notch fa-spin"></i>



                </div>



                <div style="color:var(--text-main); font-weight:700; font-size:1.05rem; letter-spacing:0.5px;">Scanning sample against YARA collections...</div>



                <div style="color:var(--text-muted); font-size:0.85rem; margin-top:6px;">Matching binary patterns & strings across selected repositories</div>



            </div>



        `;



        try {



            const fd = new FormData();



            fd.append('file', f, f.name);



            fd.append('repos', repos.join(','));



            const res = await fetch('/api/yara/scan', { method: 'POST', body: fd });



            if (!res.ok) {



                const err = await res.json().catch(() => ({}));



                throw new Error(err.detail || `Scan failed (HTTP ${res.status})`);



            }



            yaraRenderScan(await res.json());



        } catch (e) {



            out.innerHTML = `<div class="error-card"><i class="fa-solid fa-circle-exclamation"></i><div>Scan failed: ${esc(e.message)}</div></div>`;



        } finally {



            if (btn) {



                btn.disabled = false;



                btn.innerHTML = originalBtnHtml;



            }



        }



    }







    function yaraHumanSize(bytes) {



        const n = Number(bytes || 0);



        if (n < 1024) return `${n} bytes`;



        if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;



        if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;



        return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`;



    }







    function yaraMatchCard(m) {



        const card = document.createElement('div');



        card.className = 'intel-card';



        const counts = m.string_counts || {};



        const sids = Object.keys(m.string_views || {});



        const nStrings = sids.length;



        const nOcc = sids.reduce((a, sid) => a + (counts[sid] || ((m.string_views[sid] || []).length)), 0);



        const meta = m.meta || {};



        const description = meta.description || meta.desc || '';



        const source = m.collection && m.collection.toLowerCase() !== (m.rule || '').toLowerCase()



            ? m.collection : (m.repository_label || m.repository || '');



        // Secondary metadata collapsible; description stays in the summary.



        // Distribution/restriction notices are highlighted, not buried.



        const metaRows = Object.entries(meta).filter(([k]) => k !== 'description' && k !== 'desc').map(([k, v]) => {



            const hot = /distribution|do not (upload|share)|forbidden|restricted|confidential/i.test(`${k} ${v}`);



            return `<div class="vt-engine-row"${hot ? ' style="border:1px solid rgba(229,179,65,0.5); border-radius:4px;"' : ''}><span>${esc(k)}</span><span style="color:${hot ? '#e3b341' : 'var(--text-main)'};${hot ? ' font-weight:700;' : ''}">${esc(String(v))}</span></div>`;



        }).join('');



        const chips = sids.map(sid => {



            const total = counts[sid] || ((m.string_views[sid] || []).length);



            return `<span class="galaxy-chip" style="cursor:default; font-family:var(--font-mono);">${esc(sid)} × ${total}</span>`;



        }).join('');



        let matchesHtml = '<div style="color:var(--text-muted); font-size:0.82rem;">No string matches recorded.</div>';



        if (sids.length) {



            matchesHtml = sids.map(sid => {



                const views = m.string_views[sid] || [];



                const total = counts[sid] || views.length;



                const occ = views.map((v, i) => {



                    if (v.error) return `<div style="color:#ff6b6b; font-size:0.78rem;">${esc(v.error)}</div>`;



                    return `<div style="margin:8px 0; padding:10px; background:rgba(0,0,0,0.3); border-radius:6px; font-family:var(--font-mono); font-size:0.78rem;">



                        <div style="color:var(--text-muted); font-size:0.72rem; font-family:Inter,sans-serif; margin-bottom:6px;">Occurrence ${i + 1}${total > views.length ? ` of ${total}` : ''}</div>



                        <div style="display:grid; grid-template-columns:86px 1fr; gap:3px 10px; align-items:baseline;">



                            <span style="color:var(--text-muted);">Offset</span><b style="color:var(--accent);">${esc(v.offset_hex || '')}</b>



                            <span style="color:var(--text-muted);">Length</span><span>${v.length} bytes</span>



                            <span style="color:var(--text-muted);">ASCII</span><span style="color:var(--text-main); font-weight:700; overflow-wrap:anywhere;">${esc(v.ascii || '')}</span>



                            <span style="color:var(--text-muted);">Hex</span><span style="overflow-wrap:anywhere;">${esc(v.hex || '')}</span>



                        </div>



                        ${((v.context_before && v.context_before.hex) || (v.context_after && v.context_after.hex)) ? `<details style="margin-top:8px;"><summary style="cursor:pointer; font-family:Inter,sans-serif; font-size:0.76rem; color:var(--text-muted);">Show surrounding bytes</summary>



                            ${(v.context_before && v.context_before.hex) ? `<div style="margin-top:6px; color:var(--text-muted); overflow-wrap:anywhere;">−${esc(v.context_before.offset_hex || '')}: ${esc(v.context_before.hex)}<br><span style="opacity:0.7;">${esc(v.context_before.ascii || '')}</span></div>` : ''}



                            ${(v.context_after && v.context_after.hex) ? `<div style="color:var(--text-muted); overflow-wrap:anywhere;">+${esc(v.context_after.offset_hex || '')}: ${esc(v.context_after.hex)}<br><span style="opacity:0.7;">${esc(v.context_after.ascii || '')}</span></div>` : ''}



                        </details>` : ''}



                    </div>`;



                }).join('');



                return `<div style="margin-bottom:10px; padding:10px; border:1px solid rgba(255,255,255,0.07); border-radius:6px;">



                    <div style="font-family:var(--font-mono); font-size:0.85rem; color:var(--text-main); margin-bottom:2px;">▼ ${esc(sid)} <span style="color:var(--text-muted);">· ${total} occurrence${total === 1 ? '' : 's'}</span></div>



                    ${occ}



                </div>`;



            }).join('');



        }



        card.innerHTML = `<div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">



                <span style="background:rgba(239,68,68,0.14); border:1px solid rgba(239,68,68,0.5); color:#ff6b6b; padding:3px 10px; border-radius:999px; font-size:0.7rem; font-weight:800; white-space:nowrap;">✓ MATCHED</span>



                <h3 style="margin:0; font-size:1.05rem; color:white; overflow-wrap:anywhere;">${esc(m.rule || 'Unnamed')}</h3>



            </div>



            <div style="font-size:0.8rem; color:var(--text-muted); margin-bottom:4px;">Source: <span style="color:var(--text-main);">${esc(source)}</span></div>



            ${description ? `<div style="font-size:0.85rem; color:var(--text-main); margin:6px 0; line-height:1.45;">${esc(String(description))}</div>` : ''}



            <div style="display:flex; flex-wrap:wrap; gap:16px; margin:8px 0; font-size:0.82rem; color:var(--text-muted);">



                <span>Matched Strings: <b style="color:var(--text-main);">${nStrings}</b></span>



                <span>Occurrences: <b style="color:var(--text-main);">${nOcc}</b></span>



            </div>



            ${chips ? `<div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:10px;">${chips}</div>` : ''}



            ${metaRows ? `<details style="margin-bottom:10px;"><summary style="cursor:pointer; font-size:0.8rem; color:var(--text-muted); font-weight:700;">Rule Metadata</summary><div style="margin-top:8px;">${metaRows}</div></details>` : ''}



            <div class="yara-matches" style="display:none; margin-bottom:10px;">${matchesHtml}</div>



            <div style="display:flex; gap:8px; flex-wrap:wrap;">



                <button class="btn-secondary yara-view-matches" style="padding:6px 12px; font-size:0.8rem;">View Matches</button>



                <button class="btn-secondary yara-view-rule" style="padding:6px 12px; font-size:0.8rem;">View Rule</button>



                <button class="btn-secondary yara-open-wb" style="padding:6px 12px; font-size:0.8rem;">Open in Workbench</button>



            </div>`;



        const matchesBox = card.querySelector('.yara-matches');



        const viewBtn = card.querySelector('.yara-view-matches');



        viewBtn.addEventListener('click', () => {



            const open = matchesBox.style.display === 'none';



            matchesBox.style.display = open ? 'block' : 'none';



            viewBtn.textContent = open ? 'Hide Matches' : 'View Matches';



        });



        card.querySelector('.yara-view-rule').addEventListener('click', () => yaraOpenRuleModal(m.repository, m.rule, m.namespace || ''));



        card.querySelector('.yara-open-wb').addEventListener('click', async () => {



            try {



                const res = await fetch(`/api/yara/rule?repo=${encodeURIComponent(m.repository)}&name=${encodeURIComponent(m.rule)}&namespace=${encodeURIComponent(m.namespace || '')}`);



                const d = await res.json();



                yaraSwitchTab('yara-workbench');



                setTimeout(() => yaraWorkbenchLoad(d.source || '', d.repository || '', (d.file || '').split(/[\\/]/).pop()), 80);



            } catch (e) {



                showNotification('Could not load rule source: ' + e.message);



            }



        });



        return card;



    }







    function yaraRenderScan(d) {



        const out = document.getElementById('yara-scan-results');



        out.innerHTML = '';



        const info = document.createElement('div');



        info.className = 'intel-card';







        const copyBtn = (txt) => `<button class="hash-copy-btn" onclick="navigator.clipboard.writeText('${esc(txt)}')"><i class="fa-regular fa-copy"></i></button>`;







        let reposHtml = '';



        if (d.repository_stats && d.repository_stats.length > 0) {



            reposHtml = `<div style="margin-top: 15px; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 15px;">



                <div style="font-size: 0.85rem; font-weight: 600; color: var(--text-muted); margin-bottom: 8px;">REPOSITORY BREAKDOWN</div>



                <div style="display: flex; flex-wrap: wrap; gap: 8px;">



                ${d.repository_stats.map(r => `



                    <div style="background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; padding: 8px 12px; font-size: 0.85rem;">



                        <span style="color: var(--text-main); font-weight: 600;">${esc(r.label)}</span>



                        <span style="color: ${r.matches ? 'var(--danger)' : 'var(--success)'}; margin-left: 8px; font-weight: 700;">${r.matches} matches</span>



                        ${r.errors && r.errors.length ? `<i class="fa-solid fa-triangle-exclamation" style="color: #e3b341; margin-left:6px;" title="${esc(r.errors.join(', '))}"></i>` : ''}



                    </div>



                `).join('')}



                </div>



            </div>`;



        }







        info.innerHTML = `<h3 style="margin-bottom:10px;">Scan Results</h3>



            <div style="font-size:1.15rem; font-weight:700; color:white; overflow-wrap:anywhere; margin-bottom: 8px;">${esc(d.filename || 'sample')}</div>



            <div style="font-family:var(--font-mono); font-size:0.8rem; color:var(--text-muted); margin:4px 0; display: flex; align-items: center; overflow-wrap:anywhere;">MD5: <span style="color:var(--text-main); margin-left:6px;">${esc(d.md5 || '')}</span> ${copyBtn(d.md5 || '')}</div>



            <div style="font-family:var(--font-mono); font-size:0.8rem; color:var(--text-muted); margin:4px 0; display: flex; align-items: center; overflow-wrap:anywhere;">SHA1: <span style="color:var(--text-main); margin-left:6px;">${esc(d.sha1 || '')}</span> ${copyBtn(d.sha1 || '')}</div>



            <div style="font-family:var(--font-mono); font-size:0.8rem; color:var(--text-muted); margin:4px 0 12px; display: flex; align-items: center; overflow-wrap:anywhere;">SHA256: <span style="color:var(--text-main); margin-left:6px;">${esc(d.sha256 || '')}</span> ${copyBtn(d.sha256 || '')}</div>



            <div style="display:flex; flex-wrap:wrap; gap:18px; margin-bottom:16px; font-size:0.85rem; color:var(--text-muted);">



                <span>Size: <b style="color:var(--text-main);">${yaraHumanSize(d.size)}</b></span>



                <span>Engine: <b style="color:var(--text-main);">${esc(d.engine || 'YARA-X')}</b></span>



            </div>



            <div class="dash-stat-row" style="margin-bottom:0;">



                <div class="dash-stat-card"><div class="dash-stat-label">Rules Scanned</div><div class="dash-stat-value" style="font-size:1.8rem;">${Number(d.rules_scanned || 0).toLocaleString('en-US')}</div></div>



                <div class="dash-stat-card"><div class="dash-stat-label">Rules Matched</div><div class="dash-stat-value" style="font-size:1.8rem; color:${d.matched_rules ? 'var(--danger)' : 'var(--success)'};">${d.matched_rules || 0}</div></div>



                <div class="dash-stat-card"><div class="dash-stat-label">Scan Time</div><div class="dash-stat-value" style="font-size:1.8rem;">${d.scan_duration_s || 0}s</div></div>



            </div>



            ${reposHtml}



            ${(d.errors && d.errors.length && (!d.repository_stats || !d.repository_stats.length)) ? `<div style="margin-top:12px; font-size:0.85rem; color:#e3b341;">${d.errors.map(esc).join('<br>')}</div>` : ''}



            ${!d.matched_rules ? '<div style="margin-top:12px; font-size:0.9rem; color:var(--text-muted);">No local rules matched. Nothing was submitted anywhere.</div>' : ''}`;



        out.appendChild(info);



        if ((d.matches || []).length) {



            const h = document.createElement('h3');



            h.style.cssText = 'margin:12px 0; font-size:1.1rem; color:var(--text-main);';



            h.textContent = `${d.matches.length} YARA rule${d.matches.length === 1 ? '' : 's'} matched`;



            out.appendChild(h);



        }



        (d.matches || []).forEach(m => out.appendChild(yaraMatchCard(m)));



    }







    // ---------------- Rule Workbench ----------------



    let yaraWbBound = false;



    const YARA_KW = /\b(rule|private|global|meta|strings|condition|import|include|true|false|and|or|not|defined|for|any|all|of|them|in|at|contains|icontains|startswith|iendswith|endswith|matches|nocase|ascii|wide|fullword|base64|base64wide|xor|filesize|entrypoint|uint8|uint16|uint32|int8|int16|int32)\b/;







    function yaraHighlightSrc(src) {



        const escHtml = src.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');



        const hl = escHtml.replace(/(\/\/[^\n]*|\/\*[\s\S]*?\*\/)|("(?:[^"\\\n]|\\.)*")|(\$[A-Za-z_]\w*)|((?:^|\s)rule\s+)([A-Za-z_]\w*)|\b(rule|private|global|meta|strings|condition|import|include|true|false|and|or|not|defined|for|any|all|of|them|in|at|contains|icontains|startswith|iendswith|endswith|matches|nocase|ascii|wide|fullword|base64|base64wide|xor|filesize|entrypoint|uint8|uint16|uint32|int8|int16|int32)\b/gm,



            (m, com, str, vr, rulePre, ruleName, kw) => {



                if (com) return `<span class="yara-tok-com">${com}</span>`;



                if (str) return `<span class="yara-tok-str">${str}</span>`;



                if (vr) return `<span class="yara-tok-var">${vr}</span>`;



                if (ruleName) return `${rulePre.replace(/\brule\b/, '<span class="yara-tok-kw">rule</span>')}<span class="yara-tok-rule">${ruleName}</span>`;



                if (kw) return `<span class="yara-tok-kw">${kw}</span>`;



                return m;



            });



        return src.endsWith('\n') ? hl + ' ' : hl;



    }







    function yaraEditorSync() {



        const ta = document.getElementById('yara-wb-editor');



        const code = document.getElementById('yara-wb-highlight-code');



        const gutter = document.getElementById('yara-wb-gutter');



        const hl = document.getElementById('yara-wb-highlight');



        if (!ta) return;



        if (code) code.innerHTML = yaraHighlightSrc(ta.value);



        const n = ta.value.split('\n').length;



        if (gutter) {



            const g = new Array(n);



            for (let i = 0; i < n; i++) g[i] = String(i + 1);



            gutter.textContent = g.join('\n');



            gutter.scrollTop = ta.scrollTop;



        }



        if (hl) {



            hl.scrollTop = ta.scrollTop;



            hl.scrollLeft = ta.scrollLeft;



        }



    }







    // Coalesce rapid keystrokes into one highlight pass per frame so typing



    // stays responsive on large rules.



    let yaraEditorSyncQueued = false;



    function yaraEditorSyncSoon() {



        if (yaraEditorSyncQueued) return;



        yaraEditorSyncQueued = true;



        requestAnimationFrame(() => { yaraEditorSyncQueued = false; yaraEditorSync(); });



    }







    function yaraEditorGoto(line) {



        const ta = document.getElementById('yara-wb-editor');



        const n = Math.max(1, parseInt(line, 10) || 1);



        const lines = ta.value.split('\n');



        let pos = 0;



        for (let i = 0; i < Math.min(n - 1, lines.length); i++) pos += lines[i].length + 1;



        ta.focus();



        try { ta.setSelectionRange(pos, pos + (lines[n - 1] || '').length); } catch (e) { }



    }







    function yaraWorkbenchLoad(source, repo, file) {



        const ta = document.getElementById('yara-wb-editor');



        ta.value = source || '';



        yaraEditorSync();



        if (file) document.getElementById('yara-wb-filename').value = file;



        document.getElementById('yara-wb-errors').innerHTML = '';



    }







    async function openYaraWorkbench() {



        document.getElementById('yara-workbench-pane').style.display = 'flex';



        yaraWbRefreshCopyBtn();



        if (!yaraWbBound) {



            yaraWbBound = true;



            const ta = document.getElementById('yara-wb-editor');



            const hl = document.getElementById('yara-wb-highlight');



            const gutter = document.getElementById('yara-wb-gutter');



            ta.addEventListener('input', yaraEditorSyncSoon);



            ta.addEventListener('scroll', () => {



                hl.scrollTop = ta.scrollTop;



                hl.scrollLeft = ta.scrollLeft;



                gutter.scrollTop = ta.scrollTop;



            });



            ta.addEventListener('keydown', (e) => {



                if (e.key === 'Tab') {



                    e.preventDefault();



                    const s = ta.selectionStart, en = ta.selectionEnd;



                    ta.value = ta.value.slice(0, s) + '  ' + ta.value.slice(en);



                    ta.selectionStart = ta.selectionEnd = s + 2;



                    yaraEditorSync();



                } else if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {



                    e.preventDefault();



                    yaraWorkbenchValidate();



                }



            });



            document.getElementById('yara-wb-save').addEventListener('click', yaraWbDownloadRule);



            document.getElementById('yara-wb-browse').addEventListener('click', () => document.getElementById('yara-wb-file').click());



            document.getElementById('yara-wb-file').addEventListener('change', (e) => {



                const f = e.target.files[0];



                if (!f) return;



                const reader = new FileReader();



                reader.onload = (evt) => {



                    document.getElementById('yara-wb-editor').value = String(evt.target.result || '');



                    yaraEditorSync();



                    const nameInput = document.getElementById('yara-wb-filename');



                    if (nameInput && !nameInput.value.trim()) nameInput.value = f.name || 'untitled.yar';



                    document.getElementById('yara-wb-errors').innerHTML = '';



                    yaraWbSetStatus(`Loaded ${f.name}`);



                    showNotification(`Rule loaded: ${f.name}`);



                };



                reader.onerror = () => showNotification('Could not read rule file');



                reader.readAsText(f);



                e.target.value = '';



            });



            document.getElementById('yara-wb-browse-file').addEventListener('click', () => document.getElementById('yara-wb-target-file').click());



            document.getElementById('yara-wb-browse-folder').addEventListener('click', () => document.getElementById('yara-wb-target-folder').click());



            document.getElementById('yara-wb-target-file').addEventListener('change', (e) => {



                yaraWbAddTargetFiles(e.target.files);



                e.target.value = '';



            });



            document.getElementById('yara-wb-target-folder').addEventListener('change', (e) => {



                yaraWbAddTargetFiles(e.target.files);



                e.target.value = '';



            });



            document.getElementById('yara-wb-beautify').addEventListener('click', yaraBeautifyRule);



            document.getElementById('yara-wb-check').addEventListener('click', yaraWorkbenchValidate);



            document.getElementById('yara-wb-execute').addEventListener('click', yaraWbExecute);



            document.getElementById('yara-ai-explain')?.addEventListener('click', yaraAiExplain);



            document.getElementById('yara-ai-error')?.addEventListener('click', yaraAiAnalyzeError);



            document.getElementById('yara-ai-fix')?.addEventListener('click', yaraAiSuggestFix);



            document.getElementById('yara-ai-autofix')?.addEventListener('click', yaraAiAutoFix);



            document.getElementById('yara-ai-test')?.addEventListener('click', yaraAiAnalyzeTest);



            document.getElementById('yara-wb-path')?.addEventListener('input', () => {



                // Typing a path switches to server-path mode (clears staged uploads).



                if ((document.getElementById('yara-wb-path')?.value || '').trim() && yaraWbTargets.length) {



                    yaraWbTargets = [];



                    yaraWbRenderTargets();



                }



            });



            document.getElementById('yara-wb-path')?.addEventListener('keydown', (e) => {



                if (e.key === 'Enter') yaraWbTestPath(e.target.value || '');



            });



            document.getElementById('yara-wb-stop').addEventListener('click', yaraWbStop);



            document.getElementById('yara-wb-copy-md5').addEventListener('click', yaraWbCopyMd5s);



            document.getElementById('yara-wb-clear').addEventListener('click', yaraWbClear);



            yaraWbSetRunning(false);



            document.querySelectorAll('#yara-wb-det-tabs .galaxy-subtab').forEach(b => b.addEventListener('click', () => {



                if (yaraWbDetTab === b.dataset.dtab) return;



                yaraWbDetTab = b.dataset.dtab;



                yaraWbRenderDetPanel();



            }));



            yaraWbSetRunning(false);



            yaraWbSetStatus('Ready');



            yaraWbRenderTargets();



            yaraEditorSync();



        }



    }







    async function yaraWorkbenchValidate() {



        const box = document.getElementById('yara-wb-errors');



        box.innerHTML = '<div style="color:var(--text-muted); font-size:0.85rem;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Compiling temporarily…</div>';



        try {



            const res = await fetch('/api/yara/validate', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ source: document.getElementById('yara-wb-editor').value })



            });



            const d = await res.json();



            if (d.valid) {



                box.innerHTML = `<div style="color:var(--success); font-size:0.85rem;"><i class="fa-solid fa-circle-check"></i> Compiles cleanly (${esc(d.engine || '')}). No repository or cache was modified.</div>`;



            } else {



                box.innerHTML = (d.errors || []).map(e => `<div class="yara-err-line" data-line="${e.line || 1}"><i class="fa-solid fa-circle-exclamation"></i> ${e.line ? `Line ${e.line}: ` : ''}${esc(e.message || 'error')}</div>`).join('')



                    + (d.engine === 'YARA-X' && d.classic_valid ? '<div style="font-size:0.8rem; color:var(--text-muted);">Note: the classic engine accepts this rule (fallback would cover it).</div>' : '');



                box.querySelectorAll('.yara-err-line').forEach(el => el.addEventListener('click', () => yaraEditorGoto(el.dataset.line)));



            }



        } catch (e) {



            box.innerHTML = `<div style="color:#ff6b6b; font-size:0.85rem;">Validation failed: ${esc(e.message)}</div>`;



        }



    }







    function yaraAiSource() {



        return document.getElementById('yara-wb-editor')?.value || '';



    }







    function yaraAiSetState(text) {



        const el = document.getElementById('yara-ai-state');



        if (el) el.textContent = text || 'Local analysis only';



    }







    function yaraAiRender(html) {



        const box = document.getElementById('yara-ai-output');



        if (box) box.innerHTML = html;



    }







    async function yaraAiPost(path, payload) {



        const requestId = ++yaraAiRequestSeq;



        const sourceAtStart = yaraAiSource();



        yaraAiSetState('Running...');



        try {



            const res = await fetch(path, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify(payload || {})



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            if (requestId !== yaraAiRequestSeq || sourceAtStart !== yaraAiSource()) {



                yaraAiSetState('Stale result ignored');



                return null;



            }



            yaraAiSetState('Local analysis complete');



            return d;



        } catch (e) {



            if (requestId !== yaraAiRequestSeq) return null;



            yaraAiSetState('Failed');



            yaraAiRender(`<div style="color:var(--danger);">Assistant failed: ${esc(e.message)}</div>`);



            throw e;



        }



    }







    function yaraAiSuggestionList(items) {



        return (items || []).map(x => `<li><b>${esc(x.severity || 'note')}</b>: ${esc(x.message || '')}</li>`).join('');



    }







    async function yaraAiExplain() {



        const d = await yaraAiPost('/api/ai/yara/explain', { source: yaraAiSource(), test_result: yaraWbLastResults || {} });



        if (!d) return;



        yaraAiRender(`



            <div style="color:var(--text-main); white-space:pre-wrap;">${esc(d.summary || '')}</div>



            ${(d.quality_suggestions || []).length ? `<ul>${yaraAiSuggestionList(d.quality_suggestions)}</ul>` : ''}



            <div class="ai-evidence-meta">Rule version: ${esc((d.rule_hash || '').slice(0, 16))} - ${esc(d.local_only ? 'local only' : '')}</div>



        `);



    }







    async function yaraAiAnalyzeError() {



        const d = await yaraAiPost('/api/ai/yara/analyze-error', { source: yaraAiSource() });



        if (!d) return;



        const rows = (d.findings || []).map(f => `



            <div style="margin-bottom:8px;">



                <div style="color:var(--text-main); font-weight:700;">${f.line ? `Line ${esc(String(f.line))}: ` : ''}${esc(f.message || '')}</div>



                <div>${esc(f.meaning || '')}</div>



                ${(f.nearby_lines || []).length ? `<pre>${esc((f.nearby_lines || []).map(l => `${l.line}: ${l.text}`).join('\n'))}</pre>` : ''}



            </div>



        `).join('');



        yaraAiRender(rows || '<div>No compiler errors detected. Run Check Syntax if needed.</div>');



    }







    function yaraAiRenderFix(d, title) {



        yaraAiWorkingSource = d.working_source || d.fixed_source || '';



        const diff = d.diff || '';



        const canApply = !!(yaraAiWorkingSource && yaraAiWorkingSource !== yaraAiSource());



        yaraAiRender(`



            <div style="color:var(--text-main); font-weight:800; margin-bottom:4px;">${esc(title)}</div>



            <div>${esc(d.stopped_reason || d.reason || '')}</div>



            ${d.compile_status ? `<div class="ai-evidence-meta">${esc(d.compile_status)} - iterations ${esc(String(d.iterations || 0))}/${esc(String(d.max_iterations || 0))}</div>` : ''}



            ${d.confidence ? `<div class="ai-evidence-meta">${esc(d.confidence)}${d.review_required ? ' - Review required' : ''}</div>` : ''}



            ${diff ? `<pre>${esc(diff)}</pre>` : '<div class="ai-agent-empty">No rule diff was produced.</div>'}



            ${canApply ? `<button type="button" id="yara-ai-apply" class="btn-primary"><i class="fa-solid fa-check"></i> Apply to Editor</button>` : ''}



            ${yaraAiUndoSource ? `<button type="button" id="yara-ai-undo" class="btn-secondary"><i class="fa-solid fa-rotate-left"></i> Undo AI Changes</button>` : ''}



        `);



        document.getElementById('yara-ai-apply')?.addEventListener('click', yaraAiApplyWorkingCopy);



        document.getElementById('yara-ai-undo')?.addEventListener('click', yaraAiUndo);



    }







    async function yaraAiSuggestFix() {



        const d = await yaraAiPost('/api/ai/yara/suggest-fix', { source: yaraAiSource() });



        if (!d) return;



        yaraAiRenderFix(d, 'Suggested temporary fix');



    }







    async function yaraAiAutoFix() {



        const d = await yaraAiPost('/api/ai/yara/auto-fix', { source: yaraAiSource(), max_iterations: 5 });



        if (!d) return;



        yaraAiRenderFix(d, 'Validate & Auto-Fix result');



    }







    async function yaraAiAnalyzeTest() {



        if (!yaraWbLastResults) {



            yaraAiRender('<div>Run a local Workbench test first. Compile success alone is not match validation.</div>');



            return;



        }



        const d = await yaraAiPost('/api/ai/yara/analyze-test', { source: yaraAiSource(), test_result: yaraWbLastResults });



        if (!d) return;



        yaraAiRender(`



            <div style="color:var(--text-main); font-weight:800;">${esc(d.status || '')}</div>



            <div>${esc(String(d.matched_files || 0))}/${esc(String(d.tested_files || 0))} tested files matched.</div>



            ${(d.notes || []).map(n => `<div class="ai-evidence-meta">${esc(n)}</div>`).join('')}



            ${(d.quality_suggestions || []).length ? `<ul>${yaraAiSuggestionList(d.quality_suggestions)}</ul>` : ''}



        `);



    }







    function yaraAiApplyWorkingCopy() {



        if (!yaraAiWorkingSource) return;



        const ta = document.getElementById('yara-wb-editor');



        if (!ta) return;



        yaraAiUndoSource = ta.value || '';



        ta.value = yaraAiWorkingSource;



        yaraEditorSync();



        document.getElementById('yara-wb-errors').innerHTML = '';



        yaraWbLastResults = null;



        yaraWbRenderDetPanel();



        yaraAiSetState('Applied to editor, not saved');



        yaraAiRender(`<div style="color:var(--success);">AI working copy applied to the editor. Save is still manual.</div>



            <button type="button" id="yara-ai-undo" class="btn-secondary"><i class="fa-solid fa-rotate-left"></i> Undo AI Changes</button>`);



        document.getElementById('yara-ai-undo')?.addEventListener('click', yaraAiUndo);



    }







    function yaraAiUndo() {



        if (!yaraAiUndoSource) return;



        const ta = document.getElementById('yara-wb-editor');



        if (!ta) return;



        ta.value = yaraAiUndoSource;



        yaraAiUndoSource = '';



        yaraAiWorkingSource = '';



        yaraEditorSync();



        yaraWbLastResults = null;



        yaraWbRenderDetPanel();



        yaraAiSetState('Undo complete');



        yaraAiRender('<div>AI-applied editor changes were reverted. Saved files were not modified.</div>');



    }







    // Save Rule: open the native Save-As picker so the user chooses where



    // the .yar file goes (File System Access API, Chromium + localhost).



    // Falls back to a classic download elsewhere. Never auto-saves silently.



    async function yaraWbDownloadRule() {



        const editor = document.getElementById('yara-wb-editor');



        const src = editor.value || '';



        if (!src.trim()) {



            showNotification('Editor is empty — nothing to save');



            return;



        }



        const nameInput = document.getElementById('yara-wb-filename');



        let filename = ((nameInput && nameInput.value) || '').trim() || 'untitled.yar';



        if (!/\.(yar|yara)$/i.test(filename)) filename += '.yar';



        if (nameInput) nameInput.value = filename;



        try {



            if (window.showSaveFilePicker) {



                const handle = await window.showSaveFilePicker({



                    suggestedName: filename,



                    types: [{ description: 'YARA rule files', accept: { 'text/plain': ['.yar', '.yara'] } }]



                });



                const writable = await handle.createWritable();



                await writable.write(src);



                await writable.close();



                showNotification(`Saved ${filename}`);



                return;



            }



        } catch (e) {



            if (e && e.name === 'AbortError') return; // user cancelled the picker



            // fall through to the download fallback below



        }



        const blob = new Blob([src], { type: 'text/plain;charset=utf-8' });



        const a = document.createElement('a');



        a.href = URL.createObjectURL(blob);



        a.download = filename;



        document.body.appendChild(a);



        a.click();



        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);



        showNotification(`Saving ${filename} — choose a location`);



    }







    function yaraStatCard(label, value, color) {



        return `<div class="dash-stat-card"><div class="dash-stat-label">${esc(label)}</div><div class="dash-stat-value" style="${color ? `color:${color};` : ''}">${esc(String(value))}</div></div>`;



    }







    // ---------------- Workbench: targets, action bar, detection panel ----



    let yaraWbTargets = []; // [{name, file}] ad-hoc upload targets (memory only)



    let yaraWbLastResults = null; // {files, coverage, stats} for the panel



    let yaraWbDetTab = 'det';



    let yaraWbAbort = null;



    let yaraAiWorkingSource = '';



    let yaraAiUndoSource = '';



    let yaraAiRequestSeq = 0;







    function yaraWbSetStatus(text) {



        const el = document.getElementById('yara-wb-status');



        if (el) el.textContent = text || 'Ready';



    }







    function yaraWbSetRunning(running) {



        const ex = document.getElementById('yara-wb-execute');



        const stop = document.getElementById('yara-wb-stop');



        if (ex) ex.disabled = !!running;



        if (stop) stop.disabled = !running;



    }







    function yaraWbRenderTargets() {



        const box = document.getElementById('yara-wb-targets');



        if (!box) return;



        const pathInput = document.getElementById('yara-wb-path');



        const path = (pathInput?.value || '').trim();



        if (yaraWbTargets.length) {



            const bytes = yaraWbTargets.reduce((a, t) => a + (t.file.size || 0), 0);



            const mb = bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB`;



            const names = yaraWbTargets.slice(0, 3).map(t => t.name).join(', ');



            box.textContent = `${yaraWbTargets.length} file${yaraWbTargets.length === 1 ? '' : 's'} staged for upload (${mb}): ${names}${yaraWbTargets.length > 3 ? ', …' : ''}`;



            return;



        }



        if (path) {



            box.textContent = `Server path: ${path} (scanned directly, nothing uploaded)`;



            return;



        }



        box.textContent = 'No test targets — browse files or folder containing samples from your machine.';



    }







    function yaraWbAddTargetFiles(fileList) {



        const seen = new Set(yaraWbTargets.map(t => `${t.name}|${t.file.size || 0}`));



        [...(fileList || [])].forEach(f => {



            const name = f.webkitRelativePath || f.name || 'upload';



            const key = `${name}|${f.size || 0}`;



            if (!seen.has(key)) {



                seen.add(key);



                yaraWbTargets.push({ name, file: f });



            }



        });



        // Browser picks take precedence: clear any server path (single active source).



        const pathInput = document.getElementById('yara-wb-path');



        if (pathInput && yaraWbTargets.length) pathInput.value = '';



        yaraWbRenderTargets();



    }







    function yaraBeautifyRule() {



        const ta = document.getElementById('yara-wb-editor');



        if (!ta) return;



        const stash = [];



        const hold = (s) => { stash.push(s); return `\x00${stash.length - 1}\x00`; };



        let depth = 0, changed = false;



        const out = ta.value.split('\n').map(raw => {



            let line = raw.replace(/[ \t]+$/g, '');



            if (!line.trim()) return '';



            line = line.replace(/"(?:[^"\\\n]|\\.)*"/g, hold);



            ['==', '!=', '<=', '>=', '=~', '!~'].forEach(op => {



                line = line.split(op).join(hold(op));



            });



            line = line.replace(/\s*=\s*/g, ' = ');



            line = line.replace(/^(meta|strings|condition)\s*:/, '$1:');



            line = line.replace(/^(\s*rule\s+[A-Za-z_]\w*)\s*:\s*/, '$1 : ');



            line = line.replace(/\x00(\d+)\x00/g, (_, i) => stash[Number(i)]);



            const t = line.trim();



            if (/^\}/.test(t)) depth = Math.max(0, depth - 1);



            const indented = '  '.repeat(depth) + t;



            if (/\{\s*$/.test(t)) depth++;



            if (indented !== raw) changed = true;



            return indented;



        });



        ta.value = out.join('\n');



        yaraEditorSync();



        yaraWbSetStatus(changed ? 'Beautified' : 'Already tidy');



        showNotification(changed ? 'Rule beautified' : 'Rule already tidy');



    }







    function yaraWbNormalizeUpload(d) {



        return {



            files: d.files || [],



            coverage: d.string_coverage || [],



            stats: {



                total: d.total_files || 0, detected: d.detected || 0,



                undetected: d.undetected || 0, rate: d.detection_rate || 0,



                duration: d.scan_duration_s || 0, truncated: !!d.truncated,



            },



        };



    }







    function yaraWbRefreshCopyBtn() {



        const files = (yaraWbLastResults && yaraWbLastResults.files) || [];



        const hasMd5 = files.some(f => f.md5);



        const btn = document.getElementById('yara-wb-copy-md5');



        if (btn) btn.disabled = !hasMd5;



    }







    function yaraWbSetResults(model) {



        yaraWbLastResults = model;



        document.getElementById('yara-wb-det-tabs').style.display = model ? 'flex' : 'none';



        yaraWbRenderDetPanel();



        yaraWbRefreshCopyBtn();



    }







    function yaraWbDetTable(files, showRules) {



        if (!files.length) return '<div class="empty-state" style="min-height:80px;"><i class="fa-solid fa-magnifying-glass-chart"></i><p>Nothing in this view.</p></div>';



        const rows = files.slice(0, 500).map((f, i) => {



            const state = f.error ? `<span style="color:var(--danger); font-weight:700;" title="${esc(f.error)}">ERROR</span>`



                : f.timeout ? '<span style="color:#e3b341; font-weight:700;">TIMEOUT</span>'



                    : f.match ? '<span style="color:var(--success); font-weight:700;">MATCH</span>'



                        : '<span style="color:var(--text-muted);">NO MATCH</span>';



            return `<tr><td style="color:var(--text-muted);">${i + 1}</td>`



                + `<td style="font-family:var(--font-mono);">${esc(f.file || '')}</td>`



                + (showRules ? `<td style="font-family:var(--font-mono); font-size:0.72rem;">${esc((f.rules || []).join(', '))}</td>` : '')



                + `<td style="font-family:var(--font-mono); font-size:0.72rem;">${esc(f.md5 || '—')}</td>`



                + `<td>${state}</td></tr>`;



        }).join('');



        return `<table class="yara-det-table"><thead><tr><th>#</th><th>FILENAME</th>${showRules ? '<th>RULES</th>' : ''}<th>MD5</th><th>STATE</th></tr></thead><tbody>${rows}</tbody></table>`



            + (files.length > 500 ? `<div style="color:var(--text-muted); font-size:0.78rem; padding:6px;">…showing first 500 of ${files.length}</div>` : '');



    }







    function yaraWbRenderDetPanel() {



        const body = document.getElementById('yara-wb-det-body');



        if (!body) return;



        const m = yaraWbLastResults;



        if (!m) {



            body.innerHTML = '<div class="empty-state" style="min-height: 120px;"><i class="fa-solid fa-flask"></i><p>Run a test to see detections here.</p></div>';



            return;



        }



        document.querySelectorAll('#yara-wb-det-tabs .galaxy-subtab').forEach(b => b.classList.toggle('active', b.dataset.dtab === yaraWbDetTab));



        const files = m.files || [];



        if (yaraWbDetTab === 'det') {



            body.innerHTML = yaraWbDetTable(files.filter(f => f.match), true);



        } else if (yaraWbDetTab === 'miss') {



            body.innerHTML = yaraWbDetTable(files.filter(f => !f.match), false);



        } else if (yaraWbDetTab === 'strings') {



            const cov = m.coverage || [];



            body.innerHTML = cov.length ? cov.map((c, i) => `<div class="vt-engine-row yara-cov-row" data-i="${i}" style="cursor:pointer;" title="Show samples and offsets">



                    <span style="font-family:var(--font-mono);">${esc(c.string)}</span>



                    <span>${c.files_matched}/${c.total_files} · ${c.coverage}%</span>



                </div><div class="yara-cov-detail" data-i="${i}" style="display:none; font-size:0.78rem; padding:6px 10px; background:rgba(0,0,0,0.25); border-radius:4px;">${(c.samples || []).map(s => `<div style="font-family:var(--font-mono); overflow-wrap:anywhere;">${esc(s.file)}: ${(s.offsets || []).map(o => '0x' + o.toString(16).toUpperCase()).join(', ')}</div>`).join('') || '<span style="color:var(--text-muted);">No matches</span>'}</div>`).join('')



                : '<div class="empty-state" style="min-height:80px;"><i class="fa-solid fa-magnifying-glass-chart"></i><p>No string matches recorded.</p></div>';



            body.querySelectorAll('.yara-cov-row').forEach(row => row.addEventListener('click', () => {



                const det = body.querySelector(`.yara-cov-detail[data-i="${row.dataset.i}"]`);



                if (det) det.style.display = det.style.display === 'none' ? 'block' : 'none';



            }));



        } else {



            const s = m.stats || {};



            let html = `<div class="dash-stat-row">`



                + yaraStatCard('Total files', s.total || 0)



                + yaraStatCard('Detected', s.detected || 0, 'var(--success)')



                + yaraStatCard('Undetected', s.undetected || 0, (s.undetected ? 'var(--danger)' : ''))



                + yaraStatCard('Detection rate', (s.rate || 0) + '%')



                + `</div>`;



            if (s.fp) {



                html += `<div class="dash-stat-row">`



                    + yaraStatCard('Negative files', s.fp.files || 0)



                    + yaraStatCard('False positives', s.fp.fps || 0, (s.fp.fps ? 'var(--danger)' : 'var(--success)'))



                    + yaraStatCard('FP rate', (s.fp.rate || 0) + '%')



                    + `</div>`;



            }



            html += `<div style="color:var(--text-muted); font-size:0.8rem;">Duration: ${s.duration || 0}s${s.truncated ? ' · truncated (limits reached)' : ''}</div>`;



            body.innerHTML = html;



        }



    }







    async function yaraWbTestUploads(targets) {



        const controller = new AbortController();



        yaraWbAbort = controller;



        yaraWbSetRunning(true);



        yaraWbSetStatus(`Testing 0/${targets.length}…`);



        try {



            const fd = new FormData();



            fd.append('source', document.getElementById('yara-wb-editor').value);



            targets.forEach(t => fd.append('files', t.file, t.name.split('/').pop()));



            const res = await fetch('/api/yara/workbench/test-upload', { method: 'POST', body: fd, signal: controller.signal });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) {



                const det = d.detail || `Upload test failed (HTTP ${res.status})`;



                const errs = (d.compile_errors || []).map(e => esc(e.message || '')).join('<br>');



                throw new Error(det + (errs ? ' — ' + errs : ''));



            }



            yaraWbSetResults(yaraWbNormalizeUpload(d));



            yaraWbSetStatus(`Done: ${d.detected || 0}/${d.total_files || 0} detected in ${d.scan_duration_s || 0}s`);



        } catch (e) {



            if (e && e.name === 'AbortError') {



                yaraWbSetStatus('Cancelled');



            } else {



                document.getElementById('yara-wb-det-body').innerHTML = `<div class="error-card"><i class="fa-solid fa-circle-exclamation"></i><div>${esc(e.message)}</div></div>`;



                document.getElementById('yara-wb-det-tabs').style.display = 'none';



                yaraWbSetStatus('Failed');



            }



        } finally {



            yaraWbAbort = null;



            yaraWbSetRunning(false);



        }



    }







    async function yaraWbTestPath(path) {



        path = (path || '').trim();



        if (!path) {



            showNotification('Enter a server file or folder path first');



            return;



        }



        if (yaraWbAbort) return;



        const controller = new AbortController();



        yaraWbAbort = controller;



        yaraWbSetRunning(true);



        yaraWbSetStatus(`Testing ${path}…`);



        try {



            const res = await fetch('/api/yara/workbench/test-path', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ source: document.getElementById('yara-wb-editor').value, path }),



                signal: controller.signal



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) {



                const det = d.detail || `Path test failed (HTTP ${res.status})`;



                const errs = (d.compile_errors || []).map(e => esc(e.message || '')).join('<br>');



                throw new Error(det + (errs ? ' — ' + errs : ''));



            }



            yaraWbSetResults(yaraWbNormalizeUpload(d));



            yaraWbSetStatus(`Done: ${d.detected || 0}/${d.total_files || 0} detected in ${d.scan_duration_s || 0}s`);



        } catch (e) {



            if (e && e.name === 'AbortError') {



                yaraWbSetStatus('Cancelled');



            } else {



                document.getElementById('yara-wb-det-body').innerHTML = `<div class="error-card"><i class="fa-solid fa-circle-exclamation"></i><div>${esc(e.message)}</div></div>`;



                document.getElementById('yara-wb-det-tabs').style.display = 'none';



                yaraWbSetStatus('Failed');



            }



        } finally {



            yaraWbAbort = null;



            yaraWbSetRunning(false);



        }



    }







    async function yaraWbExecute() {



        if (yaraWbAbort) return;



        if (yaraWbTargets.length) {



            await yaraWbTestUploads(yaraWbTargets);



            return;



        }



        const path = document.getElementById('yara-wb-path')?.value || '';



        if (path.trim()) {



            await yaraWbTestPath(path);



            return;



        }



        showNotification('Select test targets first: browse a sample file/folder or enter a server path');



    }







    function yaraWbStop() {



        if (yaraWbAbort) {



            yaraWbAbort.abort();



            yaraWbSetStatus('Cancelling…');



        }



    }







    function yaraWbCopyMd5s() {



        const files = (yaraWbLastResults && yaraWbLastResults.files) || [];



        const md5s = [...new Set(files.map(f => f.md5).filter(Boolean))];



        if (!md5s.length) {



            showNotification('No MD5s in the current results');



            return;



        }



        const done = () => showNotification(`Copied ${md5s.length} MD5${md5s.length === 1 ? '' : 's'}`);



        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(md5s.join('\n')).then(done).catch(() => showNotification(md5s.join('\n')));



        else showNotification(md5s.join('\n'));



    }







    function yaraWbClear() {



        yaraWbLastResults = null;



        yaraWbDetTab = 'det';



        document.getElementById('yara-wb-det-tabs').style.display = 'none';



        yaraWbRenderDetPanel();



        yaraWbRefreshCopyBtn();



        yaraWbSetStatus('Ready');



    }







    // ---------------- CTI Articles (local collection) ----------------



    let ctiBound = false;



    let ctiArticleModalBound = false;



    let ctiView = 'recent';



    let ctiSource = '';



    let ctiHours = 0;



    let ctiOffset = 0;



    let ctiTotal = 0;



    const CTI_PAGE = 60;







    const CTI_IND_LABEL = { ipv4: 'IP', ipv6: 'IP', domain: 'Domain', url: 'URL', cve: 'CVE', attack: 'ATT&CK', asn: 'ASN', md5: 'MD5', sha1: 'SHA1', sha256: 'SHA256', sha3_384: 'SHA3', sha512: 'SHA512' };







    function ctiRow(r) {



        const tr = document.createElement('tr');



        const tops = (r.top_indicators || []).map(t => {



            const v = String(t.value || '');



            const short = v.length > 34 ? v.slice(0, 32) + '…' : v;



            return `<span class="cti-ind" title="${esc(v)}"><span style="color:var(--text-muted);">${esc(CTI_IND_LABEL[t.type] || t.type)} </span>${esc(short)}</span>`;



        }).join('');



        const extra = Math.max(0, (r.indicator_total || 0) - (r.top_indicators || []).length);



        const counts = ctiCountsLine(r.indicator_counts);



        tr.innerHTML = `<td style="min-width: 280px; max-width: 560px;">



                <button class="cti-open-article cti-row-title" data-article-id="${esc(String(r.id))}">${esc(r.title || 'Untitled')}</button>



                ${r.excerpt ? `<div class="cti-row-excerpt">${esc(r.excerpt)}</div>` : ''}



                <div class="cti-row-meta">${r.author ? `by ${esc(r.author)} · ` : ''}${r.matched_on && r.matched_on !== 'Browse' ? `Matched: ${esc(r.matched_on)} · ` : ''}${counts ? esc(counts) : 'No IOCs extracted'}</div>



            </td>



            <td style="white-space: nowrap; color: var(--text-main); font-size: 0.8rem;">${esc(r.source || '')}</td>



            <td style="min-width: 200px; max-width: 340px;">${tops || '<span class="cti-ind-more">—</span>'}${extra ? `<span class="cti-ind-more">+${extra} more</span>` : ''}</td>



            <td style="white-space: nowrap; font-size: 0.78rem; color: var(--text-muted);">${esc(ctiDateStr(r.published))}</td>`;



        return tr;



    }







    function ctiEnsureTable(feed) {



        let tbody = feed.querySelector('tbody');



        if (tbody) return tbody;



        feed.innerHTML = `<table class="cti-table"><thead><tr><th><i class="fa-solid fa-file-lines"></i> REPORT</th><th>SOURCE</th><th>INDICATORS</th><th>UPDATED</th></tr></thead><tbody></tbody></table>`;



        return feed.querySelector('tbody');



    }







    async function ctiLoadFeed(reset) {



        const feed = document.getElementById('cti-feed');



        if (!feed) return;



        if (reset) { ctiOffset = 0; ctiTotal = 0; feed.innerHTML = ''; }



        document.getElementById('cti-count').innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i>';



        if (reset) feed.innerHTML = '<div style="color:var(--text-muted); padding:20px;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Loading collected articles…</div>';



        try {



            const q = (document.getElementById('cti-search-input')?.value || '').trim();



            let url;



            const category = ctiCatTab === 'All' ? '' : ctiCatTab;



            if (q) {



                if (!reset && ctiOffset > 0) return; // Search pagination not supported yet



                url = `/api/cti/search?q=${encodeURIComponent(q)}&limit=${CTI_PAGE}&category=${encodeURIComponent(category)}`;



            } else {



                url = `/api/cti/articles?source=${encodeURIComponent(ctiSource)}&hours=${ctiHours}&limit=${CTI_PAGE}&offset=${ctiOffset}&category=${encodeURIComponent(category)}`;



            }



            const res = await fetch(url);



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            ctiTotal = d.total || 0;



            document.getElementById('cti-count').textContent = String(ctiTotal);



            if (!d.results || !d.results.length) {



                if (reset) feed.innerHTML = `<div class="empty-state"><i class="fa-solid fa-file-lines"></i><p>No articles collected yet. Collection runs in the background — check Sources or Sync now.</p></div>`;



                document.getElementById('cti-more').style.display = 'none';



                return;



            }



            const tbody = ctiEnsureTable(feed);



            d.results.forEach(r => tbody.appendChild(ctiRow(r)));



            ctiOffset += d.results.length;



            document.getElementById('cti-more').style.display = ctiOffset < ctiTotal ? '' : 'none';



        } catch (e) {



            if (reset) {



                const down = e instanceof TypeError || /failed to fetch|networkerror/i.test(e.message || '');



                feed.innerHTML = `<div class="empty-state"><i class="fa-solid fa-triangle-exclamation" style="color: var(--danger);"></i><p>${down ? 'Cannot reach the MANTIS server — check that it is still running, then retry.' : `Could not load articles: ${esc(e.message)}`}</p><p><button class="cti-retry btn-secondary" style="margin-top: 6px;"><i class="fa-solid fa-rotate"></i> Retry</button></p></div>`;



            }



            document.getElementById('cti-more').style.display = 'none';



        }



    }







    const getCtiStatusColor = (status) => {



        if (!status) return 'var(--text-muted)';



        if (status === 'Active') return 'var(--success)';



        if (status === 'Pending' || status.includes('Temporary error') || status.includes('Rate limited')) return 'var(--highlight)';



        if (status === 'Disabled' || status === 'Skipped') return 'var(--text-muted)';



        if (status.includes('Error') || status.includes('Feed Not Found') || status.includes('Invalid feed') || status.includes('blocked')) return 'var(--danger)';



        return 'var(--text-muted)';



    };







    let ctiSourcesData = [];



    let ctiCatTab = 'All';



    let ctiArticlesTotal = 0;



    let ctiShowAdd = false;



    let ctiEditId = null;



    let ctiEditingCat = null;



    let ctiSourceLimit = 25;



    const CTI_CATEGORY_ORDER = [



        'Analyst',



        'Community',



        'Government',



        'Media',



        'Vendor',



    ];



    const CTI_CATEGORY_ALIASES = {



        'Threat Intelligence': 'Analyst',



        'Malware & DFIR': 'Analyst',



        'Vulnerabilities & Exploits': 'Analyst',



        'Core Threat Intelligence / Threat Research': 'Analyst',



        'Security News / Campaign Discovery': 'Media',



        'Malware & Threat Research': 'Analyst',



        'Malware Analysis / DFIR / Technical Research': 'Analyst',



        'Vulnerability / Exploitation Research': 'Analyst',



        'Vulnerabilities, CVEs & Exploits': 'Analyst',



        'Vendor Research': 'Vendor',



        'Vendors & Product Blogs': 'Vendor',



        'Security Blogs': 'Community',



        'General Security & Blogs': 'Community',



        'Podcasts & Video': 'Media',



        'Podcasts & YouTube': 'Media',



        'Other': 'Community',



    };







    const ctiNormalizeCategory = (category) => {



        const label = String(category || '').trim();



        if (!label || label === 'All') return label || 'Community';



        return CTI_CATEGORY_ALIASES[label] || label;



    };







    const ctiSourceCategory = (s) => {



        const cat = s.display_category || s.category || ((s.upstream || '').split('|')[0] || '').trim();



        return ctiNormalizeCategory(cat);



    };







    function ctiCategoryCounts() {



        const counts = {};



        ctiSourcesData.forEach(s => {



            const c = ctiSourceCategory(s);



            counts[c] = (counts[c] || 0) + 1;



        });



        return counts;



    }







    function ctiRenderCategoryTabs() {



        const box = document.getElementById('cti-category-tabs');



        if (!box) return;



        const counts = ctiCategoryCounts();



        const cats = CTI_CATEGORY_ORDER.filter(c => counts[c] !== undefined);



        Object.keys(counts).sort((a, b) => a.localeCompare(b)).forEach(c => {



            if (!cats.includes(c)) cats.push(c);



        });



        if (!cats.includes(ctiCatTab)) ctiCatTab = 'All';



        const tabBtn = (label, n) => `<button class="galaxy-subtab${ctiCatTab === label ? ' active' : ''}" data-cticat="${esc(label)}" style="font-size: 0.75rem;">${esc(label)} (${n})</button>`;



        const tabsHtml = tabBtn('All', ctiSourcesData.length) + cats.map(c => tabBtn(c, counts[c] || 0)).join('');



        const manageBtn = `<button id="cti-manage-cats-btn" class="btn-secondary" style="font-size: 0.75rem; padding: 4px 12px; margin-left: auto; display: flex; align-items: center; gap: 5px;" title="Manage Categories"><i class="fa-solid fa-folder-tree"></i> Manage Categories</button>`;



        box.innerHTML = tabsHtml + manageBtn;



        box.querySelectorAll('[data-cticat]').forEach(b => b.addEventListener('click', () => {



            ctiCatTab = b.dataset.cticat;



            ctiSourceLimit = 25;



            ctiRenderCategoryTabs();



            if (ctiView === 'recent') ctiLoadFeed(true);



            else ctiRenderSources();



        }));



        document.getElementById('cti-manage-cats-btn')?.addEventListener('click', (e) => {



            e.preventDefault();



            ctiOpenCategoryModal();



        });



    }







    async function ctiOpenCategoryModal() {



        const modal = document.getElementById('cti-cat-modal-overlay');



        if (!modal) return;



        modal.style.display = 'flex';



        ctiEditingCat = null;



        await ctiLoadCategoryModalList();



    }







    async function ctiLoadCategoryModalList() {



        const list = document.getElementById('cti-cat-modal-list');



        if (!list) return;



        try {



            const res = await fetch('/api/cti/categories');



            const d = await res.json();



            const cats = d.categories || ['Analyst', 'Community', 'Government', 'Media', 'Vendor'];



            const counts = ctiCategoryCounts();







            const dl = document.getElementById('cti-cat-datalist');



            if (dl) dl.innerHTML = cats.map(c => `<option value="${esc(c)}"></option>`).join('');







            if (!cats.length) {



                list.innerHTML = '<div style="color:var(--text-muted); text-align:center; padding:12px;">No categories found.</div>';



                return;



            }







            list.innerHTML = cats.map(cat => {



                const count = counts[cat] || 0;



                const isEditing = ctiEditingCat === cat;



                return `<div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 10px 14px; display: flex; gap: 10px; align-items: center; justify-content: space-between;">



                    ${isEditing ? `



                        <input class="cti-cat-rename-input" value="${esc(cat)}" data-old-cat="${esc(cat)}" style="flex: 1; background: rgba(0,0,0,0.3); border: 1px solid var(--accent); color: white; border-radius: 4px; padding: 5px 10px; outline: none; font-size: 0.82rem;">



                        <div style="display:flex; gap:6px;">



                            <button class="cti-cat-rename-save btn-primary" data-old-cat="${esc(cat)}" style="padding: 4px 10px; font-size: 0.78rem;">Save</button>



                            <button class="cti-cat-rename-cancel btn-secondary" style="padding: 4px 10px; font-size: 0.78rem;">Cancel</button>



                        </div>



                    ` : `



                        <div>



                            <span style="font-weight: 600; color: var(--text-main); font-size: 0.88rem;">${esc(cat)}</span>



                            <span style="font-size: 0.75rem; color: var(--text-muted); margin-left: 8px;">(${count} source${count === 1 ? '' : 's'})</span>



                        </div>



                        <div style="display:flex; gap:6px;">



                            <button class="cti-cat-edit-btn btn-secondary" data-cat="${esc(cat)}" style="padding: 4px 10px; font-size: 0.78rem;"><i class="fa-solid fa-pen"></i> Edit Name</button>



                            <button class="cti-cat-delete-btn btn-secondary" data-cat="${esc(cat)}" style="padding: 4px 10px; font-size: 0.78rem; color: var(--danger);"><i class="fa-solid fa-trash"></i> Delete</button>



                        </div>



                    `}



                </div>`;



            }).join('');



        } catch (e) {



            list.innerHTML = `<div style="color:var(--danger); text-align:center; padding:12px;">Failed to load categories: ${esc(e.message)}</div>`;



        }



    }







    async function ctiAddCategory() {



        const input = document.getElementById('cti-cat-new-input');



        const name = (input?.value || '').trim();



        if (!name) return showNotification('Enter category name first');



        try {



            const res = await fetch('/api/cti/categories', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ name })



            });



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            input.value = '';



            showNotification(`Category "${name}" created`);



            await ctiLoadCategoryModalList();



            ctiLoadSources(true);



        } catch (e) {



            showNotification(`Could not create category: ${e.message}`);



        }



    }







    async function ctiRenameCategory(oldName, newName) {



        if (!newName || newName === oldName) {



            ctiEditingCat = null;



            ctiLoadCategoryModalList();



            return;



        }



        try {



            const res = await fetch('/api/cti/categories/rename', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ old_name: oldName, new_name: newName })



            });



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            ctiEditingCat = null;



            showNotification(`Renamed category "${oldName}" to "${newName}"`);



            await ctiLoadCategoryModalList();



            ctiLoadSources(true);



        } catch (e) {



            showNotification(`Could not rename category: ${e.message}`);



        }



    }







    async function ctiDeleteCategory(catName) {



        if (!confirm(`Are you sure you want to delete category "${catName}"? Sources under this category will be reset.`)) return;



        try {



            const res = await fetch('/api/cti/categories/delete', {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ name: catName })



            });



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(`Category "${catName}" deleted`);



            await ctiLoadCategoryModalList();



            ctiLoadSources(true);



        } catch (e) {



            showNotification(`Could not delete category: ${e.message}`);



        }



    }







    function ctiRenderSources() {



        const box = document.getElementById('cti-sources');



        if (!box) return;



        ctiRenderCategoryTabs();



        const filtered = ctiCatTab === 'All'



            ? ctiSourcesData



            : ctiSourcesData.filter(s => ctiSourceCategory(s) === ctiCatTab);



        const shown = filtered.slice(0, ctiSourceLimit);



        box.innerHTML = `<div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:4px; align-items:center; justify-content:space-between;">



                <div style="font-size:0.78rem; color:var(--text-muted);">${esc(String(ctiArticlesTotal))} articles stored locally across ${esc(String(ctiSourcesData.length))} sources - showing ${esc(String(shown.length))}. Feeds resolve from local registry and autodiscovery; collection is passive and local-only.</div>



                <button class="cti-add-toggle btn-secondary" style="padding: 5px 12px; font-size: 0.78rem;"><i class="fa-solid fa-plus"></i> Add feed</button>



            </div>`



            + (ctiShowAdd ? `<div style="background: rgba(0,0,0,0.25); border: 1px solid var(--border); border-radius: 6px; padding: 10px 12px; display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 4px;">



                    <input id="cti-add-name" placeholder="Name (optional)" style="flex: 1 1 160px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-size: 0.8rem;">



                    <input id="cti-add-cat" placeholder="Category (e.g. Vendor)" list="cti-cat-datalist" style="flex: 1 1 140px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-size: 0.8rem;">



                    <input id="cti-add-url" placeholder="https://example.com/feed.xml" style="flex: 2 1 220px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-family: var(--font-mono); font-size: 0.8rem;">



                    <button class="cti-add-save btn-primary" style="padding: 6px 14px; font-size: 0.8rem;">Add</button>



                    <button class="cti-add-cancel btn-secondary" style="padding: 6px 14px; font-size: 0.8rem;">Cancel</button>



                </div>` : '')



            + shown.map(s => {



                const color = getCtiStatusColor(s.status);



                return `<div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 10px 14px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap;">



                    <span style="display:inline-block; width:9px; height:9px; border-radius:999px; background:${color};"></span>



                    <span style="flex: 1; min-width: 180px;">



                        <span style="font-weight: 600; color: var(--text-main);">${esc(s.name)}</span>



                        <span style="font-size: 0.75rem; color: var(--text-muted);"> - ${esc(s.domain || '')} - <span style="color:var(--accent); font-weight:600;">${esc(ctiSourceCategory(s))}</span></span><br>



                        <span style="font-size: 0.72rem; color: var(--text-muted);">${esc(String(s.article_count || 0))} articles - Last sync: ${esc(s.last_success || 'never')}${s.last_error ? ` - <span style="color:var(--danger);">${esc(s.last_error)}</span>` : ''}</span>



                    </span>



                    <span style="font-size: 0.75rem; font-weight: 700; color:${color};">${esc(s.status)}</span>



                        ${s.feed_url ? '' : '<span style="font-size:0.72rem; color:var(--text-muted);">No feed yet</span>'}



                        <span class="cti-row-actions" style="display:flex; gap:6px;">



                            <button class="cti-edit-source btn-secondary" data-source-id="${esc(s.id)}" style="padding: 5px 12px; font-size: 0.78rem;"><i class="fa-solid fa-pen"></i> Edit</button>



                            <button class="cti-toggle-source btn-secondary" data-source-id="${esc(s.id)}" data-enabled="${s.enabled ? 0 : 1}" style="padding: 5px 12px; font-size: 0.78rem;">${s.enabled ? 'Disable' : 'Enable'}</button>



                            <button class="cti-delete-source btn-secondary" data-source-id="${esc(s.id)}" data-source-name="${esc(s.name)}" style="padding: 5px 12px; font-size: 0.78rem; color: var(--danger);"><i class="fa-solid fa-trash"></i> Delete</button>



                        </span>



                        ${ctiEditId === s.id ? `<span class="cti-row-editor" style="display:flex; gap:8px; flex: 1 1 100%; margin-top:8px; flex-wrap:wrap; background:rgba(0,0,0,0.25); padding:10px; border-radius:6px; border:1px solid var(--border);">



                            <input class="cti-edit-name" value="${esc(s.name || '')}" placeholder="Source Name" style="flex: 1 1 160px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-size: 0.78rem;">



                            <input class="cti-edit-cat" value="${esc(ctiSourceCategory(s))}" list="cti-cat-datalist" placeholder="Category" style="flex: 1 1 140px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-size: 0.78rem;">



                            <input class="cti-edit-url" value="${esc(s.feed_url || '')}" placeholder="https://example.com/feed.xml" style="flex: 2 1 220px; background: rgba(0,0,0,0.3); border: 1px solid var(--border); color: white; border-radius: 4px; padding: 6px 10px; outline: none; font-family: var(--font-mono); font-size: 0.78rem;">



                            <button class="cti-edit-save btn-primary" data-source-id="${esc(s.id)}" style="padding: 6px 14px; font-size: 0.78rem;">Save</button>



                            <button class="cti-edit-cancel btn-secondary" style="padding: 6px 14px; font-size: 0.78rem;">Cancel</button>



                        </span>` : ''}



                </div>`;



            }).join('');







        const moreBtn = document.getElementById('cti-more');



        if (moreBtn) {



            moreBtn.style.display = ctiSourceLimit < filtered.length ? '' : 'none';



        }



    }







    async function ctiLoadSources(intoSelect) {



        try {



            const res = await fetch('/api/cti/sources');



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            if (intoSelect) {



                const sel = document.getElementById('cti-source');



                const cur = sel.value;



                const mnCount = (d.sources || []).filter(s => (s.domain || '').includes('malware.news')).reduce((acc, s) => acc + (s.article_count || 0), 0);

                const mnOpt = mnCount > 0 ? `<option value="malware.news">★ Malware.news (${mnCount} articles - All Feeds)</option>` : '';

                sel.innerHTML = '<option value="">All Sources</option>' + mnOpt + (d.sources || []).map(s => `<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');



                if ([...sel.options].some(o => o.value === cur)) sel.value = cur;



            }



            ctiSourcesData = d.sources || [];



            ctiArticlesTotal = d.articles_total || 0;



            ctiRenderSources();



        } catch (e) {



            const box = document.getElementById('cti-sources');



            if (box) box.innerHTML = `<div class="empty-state"><i class="fa-solid fa-triangle-exclamation" style="color: var(--danger);"></i><p>Could not load sources: ${esc(e.message)}</p></div>`;



        }



    }







    function ctiSetView(view) {



        ctiView = view;



        document.querySelectorAll('[data-ctiview]').forEach(b => b.classList.toggle('active', b.dataset.ctiview === view));



        document.getElementById('cti-feed').style.display = view === 'recent' ? '' : 'none';



        const box = document.getElementById('cti-sources');



        box.style.display = view === 'sources' ? 'flex' : 'none';



        if (view === 'recent') {



            ctiLoadFeed(true);



        } else {



            ctiSourceLimit = 25;



            ctiLoadSources(false);



        }



    }







    function ctiCloseArticleModal() {



        const overlay = document.getElementById('cti-modal-overlay');



        if (overlay) overlay.style.display = 'none';



    }







    function ctiIndicatorLookupType(groupKey) {



        if (groupKey === 'hashes') return { tab: 'hash' };



        if (groupKey === 'domains') return { tab: 'domain' };



        if (groupKey === 'ips') return { tab: 'ip' };



        if (groupKey === 'urls') return { tab: 'url' };



        if (groupKey === 'cves') return { tab: 'keyword', keywordType: 'cve' };



        if (groupKey === 'attack') return { tab: 'keyword', keywordType: 'all' };



        if (groupKey === 'asn') return { tab: 'infra' };



        return { tab: 'keyword', keywordType: 'all' };



    }







    async function ctiValidateIoc(value, groupKey) {



        const clean = String(value || '').trim();



        if (!clean) return;



        const lookup = ctiIndicatorLookupType(groupKey);



        ctiCloseArticleModal();



        const nav = document.querySelector(`.nav-item[data-tab="${lookup.tab}"]`);



        if (nav) nav.click();



        await new Promise(resolve => setTimeout(resolve, 80));



        if (lookup.tab === 'keyword' && keywordTypeSelect) {



            activeKeywordType = lookup.keywordType || 'all';



            keywordTypeSelect.value = activeKeywordType;



        }



        if (['hash', 'domain', 'ip', 'url', 'keyword'].includes(lookup.tab) && typeof switchToIocSearch === 'function') {



            switchToIocSearch(lookup.tab);



        }



        if (inputField) inputField.value = clean;



        if (typeof performSearch === 'function') await performSearch();



        else if (searchBtn) searchBtn.click();



    }







    function ctiRenderIndicatorGroups(d, mode = 'modal') {



        const groups = [



            ['Hashes', 'hashes', d.indicators?.hashes || []],



            ['Domains', 'domains', d.indicators?.domains || []],



            ['IPs', 'ips', d.indicators?.ips || []],



            ['URLs', 'urls', d.indicators?.urls || []],



            ['CVEs', 'cves', d.indicators?.cves || []],



            ['ATT&CK', 'attack', d.indicators?.attack || []],



            ['ASN', 'asn', d.indicators?.asn || []],



            ['Actors', 'actors', d.indicators?.actors || []],



            ['Malware', 'malware', d.indicators?.malware || []],



        ];



        const pivot = (value, type, label) => value



            ? `<a href="#" class="pivot-link" data-type="${esc(type)}" data-indicator="${esc(value)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); font-family:var(--font-mono); word-break:break-all;">${esc(label || value)}</a>` : '';



        const linkType = (key) => {



            const lookup = ctiIndicatorLookupType(key);



            return lookup.tab === 'keyword' ? 'keyword' : lookup.tab;



        };



        const rendered = groups.map(([label, key, rawItems]) => {



            const rows = (rawItems || []).map(x => {



                const value = String(x.value || '').trim();



                if (!value) return '';



                const observed = String(x.observed || value);



                const display = observed !== value ? `${observed} -> ${value}` : value;



                const linkLabel = key === 'hashes' && observed !== value ? `${observed} (${value.slice(0, 16)}...)` : display;



                const validator = ['hashes', 'domains', 'ips', 'urls', 'cves', 'attack', 'asn'].includes(key)



                    ? `<button type="button" class="cti-ioc-validator btn-secondary" data-ioc-type="${esc(key)}" data-ioc-value="${esc(value)}" title="Run this IOC through the normal MANTIS lookup pipeline"><i class="fa-solid fa-shield-check"></i> IOC lookup</button>`



                    : '';



                const desc = x.description ? `<div class="cti-ioc-desc">${esc(x.description)}</div>` : '';



                return `<div class="cti-ioc-row"><div class="cti-ioc-value">${pivot(value, linkType(key), linkLabel)}</div>${validator}${desc}</div>`;



            }).filter(Boolean);



            if (!rows.length) return '';



            return `<details${mode === 'extractor' ? ' open' : ''} class="cti-ioc-group">



                <summary>${esc(label)} <span>(${rows.length})</span></summary>



                <div class="cti-ioc-list">${rows.join('')}</div>



            </details>`;



        }).join('');



        return rendered || '<div style="color:var(--text-muted); font-size:0.85rem;">No indicators extracted from this article.</div>';



    }







    function ctiRenderExtractorPanel(d) {



        const total = Number(d.indicator_total || 0);



        const counts = d.indicator_counts || {};



        const countLine = Object.entries(counts)



            .filter(([, value]) => Number(value || 0) > 0)



            .map(([key, value]) => `${key}: ${value}`)



            .join(' | ');



        return `<div class="cti-ioc-extractor-title">



                <i class="fa-solid fa-fingerprint"></i>



                <span>IOC Extraction Result</span>



                <small>${total.toLocaleString()} extracted item${total === 1 ? '' : 's'}</small>



            </div>



            ${countLine ? `<div class="cti-ioc-countline">${esc(countLine)}</div>` : ''}



            <div class="cti-ioc-extractor-note">Extracted values are context only. Use IOC lookup to run a selected value through the normal lookup workflow.</div>



            ${ctiRenderIndicatorGroups(d, 'extractor')}`;



    }







    function ctiEnsureArticleModalEvents() {



        if (ctiArticleModalBound) return;



        ctiArticleModalBound = true;



        document.getElementById('cti-modal-close')?.addEventListener('click', (e) => {



            e.preventDefault();



            ctiCloseArticleModal();



        });



        document.getElementById('cti-modal-overlay')?.addEventListener('click', (e) => {



            if (e.target?.id === 'cti-modal-overlay') ctiCloseArticleModal();



        });



        document.getElementById('cti-modal-overlay')?.addEventListener('click', (e) => {



            const validator = e.target.closest('.cti-ioc-validator');



            if (!validator) return;



            e.preventDefault();



            ctiValidateIoc(validator.dataset.iocValue, validator.dataset.iocType);



        });



        document.addEventListener('keydown', (e) => {



            if (e.key === 'Escape' && document.getElementById('cti-modal-overlay')?.style.display !== 'none') {



                ctiCloseArticleModal();



            }



        });



    }







    async function ctiOpenArticle(id) {



        ctiEnsureArticleModalEvents();



        const overlay = document.getElementById('cti-modal-overlay');



        const summaryBtn = document.getElementById('cti-ai-summary');



        const summaryPanel = document.getElementById('cti-ai-summary-panel');



        const extractorBtn = document.getElementById('cti-ioc-extractor');



        const extractorPanel = document.getElementById('cti-ioc-extractor-panel');



        document.getElementById('cti-modal-title').textContent = 'Loading…';



        document.getElementById('cti-modal-sub').textContent = '';



        document.getElementById('cti-modal-excerpt').textContent = '';



        document.getElementById('cti-modal-excerpt').style.display = 'none';



        document.getElementById('cti-modal-content').innerHTML = '';



        document.getElementById('cti-modal-indicators').innerHTML = '';



        if (summaryBtn) {



            summaryBtn.dataset.articleId = String(id);



            summaryBtn.disabled = false;



            summaryBtn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> Summarizer';



            summaryBtn.onclick = (e) => {



                e.preventDefault();



                ctiSummarizeArticle(id);



            };



        }



        if (extractorBtn) {



            extractorBtn.dataset.articleId = String(id);



            extractorBtn.disabled = true;



            extractorBtn.innerHTML = '<i class="fa-solid fa-fingerprint"></i> IOC Extractor';



            extractorBtn.onclick = null;



        }



        if (summaryPanel) {



            summaryPanel.style.display = 'none';



            summaryPanel.innerHTML = '';



        }



        if (extractorPanel) {



            extractorPanel.style.display = 'none';



            extractorPanel.innerHTML = '';



        }



        overlay.style.display = 'flex';



        try {



            const res = await fetch(`/api/cti/article/${encodeURIComponent(id)}`);



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            document.getElementById('cti-modal-title').textContent = d.title || 'Untitled';



            document.getElementById('cti-modal-sub').textContent =



                `${d.source || ''}${d.author ? ` · by ${d.author}` : ''} · ${ctiDateStr(d.published)}`;



            document.getElementById('cti-modal-content').innerHTML = d.content_html || '';



            const link = document.getElementById('cti-modal-link');



            link.href = d.url || '#';



            const pivot = (value, type, label) => value



                ? `<a href="#" class="pivot-link" data-type="${esc(type)}" data-indicator="${esc(value)}" style="color:var(--accent); text-decoration:none; border-bottom:1px dashed var(--accent); font-family:var(--font-mono); word-break:break-all;">${esc(label || value)}</a>` : '';



            const groups = [



                ['Hashes', (d.indicators.hashes || []).map(h => pivot(h.value, 'hash', h.observed !== h.value ? `${h.observed} (${h.value.slice(0, 16)}…)` : h.value))],



                ['Domains', (d.indicators.domains || []).map(x => pivot(x.value, 'domain', x.observed !== x.value ? `${x.observed} → ${x.value}` : x.value))],



                ['IPs', (d.indicators.ips || []).map(x => pivot(x.value, 'ip', x.observed !== x.value ? `${x.observed} → ${x.value}` : x.value))],



                ['URLs', (d.indicators.urls || []).map(x => pivot(x.value, 'url'))],



                ['CVEs', (d.indicators.cves || []).map(x => pivot(x.value, 'keyword'))],



                ['ATT&CK', (d.indicators.attack || []).map(x => pivot(x.value, 'keyword'))],



                ['ASN', (d.indicators.asn || []).map(x => pivot(x.value, 'keyword'))],



            ];



            const counts = d.indicator_counts || {};



            document.getElementById('cti-modal-indicators').innerHTML = groups.map(([label, items]) => {



                if (!items.length) return '';



                return `<details style="margin-bottom:8px; background:rgba(0,0,0,0.2); border:1px solid rgba(255,255,255,0.08); border-radius:6px; padding:8px 12px;">



                    <summary style="cursor:pointer; color:var(--text-main); font-size:0.85rem; font-weight:600;">${esc(label)} <span style="color:var(--text-muted);">(${items.length})</span></summary>



                    <div style="display:flex; flex-direction:column; gap:5px; margin-top:8px; font-size:0.82rem;">${items.map(i => `<div>${i}</div>`).join('')}</div>



                </details>`;



            }).join('') || '<div style="color:var(--text-muted); font-size:0.85rem;">No indicators extracted from this article.</div>';



            document.getElementById('cti-modal-indicators').innerHTML = ctiRenderIndicatorGroups(d);



            if (extractorBtn) {



                extractorBtn.disabled = false;



                extractorBtn.onclick = (e) => {



                    e.preventDefault();



                    if (!extractorPanel) return;



                    extractorPanel.style.display = 'block';



                    extractorPanel.innerHTML = ctiRenderExtractorPanel(d);



                };



            }



        } catch (e) {



            document.getElementById('cti-modal-title').textContent = 'Failed to load article';



            document.getElementById('cti-modal-sub').textContent = e.message;



            if (extractorBtn) extractorBtn.disabled = true;



        }



    }







    function ctiRenderAiSummary(d) {



        const list = (title, items, icon) => {



            const clean = (items || []).filter(Boolean);



            if (!clean.length) return '';



            return `<div class="cti-ai-summary-section">



                <div class="cti-ai-summary-heading"><i class="${esc(icon)}"></i> ${esc(title)}</div>



                <ul>${clean.map(item => `<li>${esc(item)}</li>`).join('')}</ul>



            </div>`;



        };



        const full = (title, items, icon) => {



            const clean = (items || []).filter(Boolean);



            if (!clean.length) return '';



            return `<div class="cti-ai-summary-section cti-ai-summary-section-wide">



                <div class="cti-ai-summary-heading"><i class="${esc(icon)}"></i> ${esc(title)}</div>



                <ul>${clean.map(item => `<li>${esc(item)}</li>`).join('')}</ul>



            </div>`;



        };



        return `<div class="cti-ai-summary-title">



                <i class="fa-solid fa-wand-magic-sparkles"></i>



                <span>AI Analyst Brief</span>



                ${d.model ? `<small>${esc(d.model)}</small>` : ''}



            </div>



            ${d.summary ? `<p class="cti-ai-summary-text">${esc(d.summary)}</p>` : ''}



            <div class="cti-ai-summary-grid">



                ${full('Key Judgments', d.key_judgments || d.key_points, 'fa-solid fa-scale-balanced')}



                ${list('Timeline', d.timeline, 'fa-solid fa-timeline')}



                ${list('Attack Flow', d.attack_flow, 'fa-solid fa-diagram-project')}



                ${list('Threat Entities', d.threat_entities, 'fa-solid fa-user-secret')}



                ${list('Infrastructure', d.infrastructure, 'fa-solid fa-network-wired')}



                ${list('Context Artifacts', d.context_artifacts, 'fa-solid fa-puzzle-piece')}



                ${list('Victimology', d.victimology, 'fa-solid fa-building-shield')}



                ${list('MITRE ATT&CK', d.mitre_attack, 'fa-solid fa-crosshairs')}



                ${full('Recommended Pivots', d.recommended_pivots || d.analyst_actions, 'fa-solid fa-route')}



                ${list('Caveats', d.caveats, 'fa-solid fa-triangle-exclamation')}



            </div>`;



    }







    async function ctiSummarizeArticle(id) {



        const btn = document.getElementById('cti-ai-summary');



        const panel = document.getElementById('cti-ai-summary-panel');



        if (!id || !panel) return;



        panel.style.display = 'block';



        panel.innerHTML = '<div class="cti-ai-summary-loading"><i class="fa-solid fa-circle-notch mantis-spin"></i> Summarizing article...</div>';



        if (btn) {



            btn.disabled = true;



            btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Summarizing';



        }



        try {



            const res = await fetch(`/api/cti/article/${encodeURIComponent(id)}/ai-summary`, { method: 'POST' });



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            panel.innerHTML = ctiRenderAiSummary(d);



        } catch (e) {



            panel.innerHTML = `<div class="cti-ai-summary-error"><i class="fa-solid fa-triangle-exclamation"></i> ${esc(e.message || 'AI summary failed')}</div>`;



        } finally {



            if (btn) {



                btn.disabled = false;



                btn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> Summarizer';



            }



        }



    }







    async function ctiToggleSource(id, enabled) {



        try {



            const res = await fetch(`/api/cti/sources/${encodeURIComponent(id)}/toggle`, {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ enabled: !!enabled })



            });



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            showNotification(enabled ? 'Source enabled' : 'Source disabled');



            ctiLoadSources(false);



        } catch (e) {



            showNotification(`Could not update source: ${e.message}`);



        }



    }







    async function ctiAddFeed() {



        const name = (document.getElementById('cti-add-name')?.value || '').trim();



        const category = (document.getElementById('cti-add-cat')?.value || '').trim();



        const url = (document.getElementById('cti-add-url')?.value || '').trim();



        if (!url) {



            showNotification('Enter a feed URL first');



            return;



        }



        try {



            const res = await fetch('/api/cti/sources', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ name, category, feed_url: url })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            ctiShowAdd = false;



            showNotification(d.created ? 'Feed added — it will sync in the background' : 'Feed already registered');



            ctiLoadSources(true);



        } catch (e) {



            showNotification(`Could not add feed: ${e.message}`);



        }



    }







    async function ctiSaveSource(id) {



        const editor = document.querySelector(`.cti-edit-save[data-source-id="${CSS.escape(id)}"]`)?.closest('.cti-row-editor');



        if (!editor) return;



        const name = (editor.querySelector('.cti-edit-name')?.value || '').trim();



        const category = (editor.querySelector('.cti-edit-cat')?.value || '').trim();



        const feed_url = (editor.querySelector('.cti-edit-url')?.value || '').trim();



        try {



            const res = await fetch(`/api/cti/sources/${encodeURIComponent(id)}/edit`, {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ name, category, feed_url })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            ctiEditId = null;



            showNotification('Source updated successfully');



            ctiLoadSources(false);



        } catch (e) {



            showNotification(`Could not update source: ${e.message}`);



        }



    }







    async function ctiDeleteSource(id, name) {



        if (!confirm(`Are you sure you want to delete source "${name}" and all its stored articles?`)) return;



        try {



            const res = await fetch(`/api/cti/sources/${encodeURIComponent(id)}`, {



                method: 'DELETE'



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(`Source "${name}" deleted`);



            ctiLoadSources(false);



        } catch (e) {



            showNotification(`Could not delete source: ${e.message}`);



        }



    }







    async function ctiSyncNow() {



        const btn = document.getElementById('cti-sync');



        if (btn && btn.disabled) return;







        try {



            const originalHtml = btn ? btn.innerHTML : '';



            if (btn) {



                btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Syncing...';



                btn.disabled = true;



            }







            const res = await fetch('/api/cti/sync', { method: 'POST' });



            const d = await res.json();







            if (!d.started) {



                showNotification('CTI sync already running');



                if (btn) {



                    btn.innerHTML = originalHtml;



                    btn.disabled = false;



                }



                return;



            }







            showNotification('CTI sync started... fetching feeds');







            await new Promise(resolve => setTimeout(resolve, 15000));







            if (currentTab === 'cti') {



                if (ctiView === 'recent') await ctiLoadFeed(true);



                else await ctiLoadSources(false);



            }







            showNotification('CTI sync check finished');



            if (btn) {



                btn.innerHTML = originalHtml || '<i class="fa-solid fa-rotate"></i> Sync';



                btn.disabled = false;



            }



        } catch (e) {



            showNotification(`Could not start sync: ${e.message}`);



            if (btn) {



                btn.innerHTML = '<i class="fa-solid fa-rotate"></i> Sync';



                btn.disabled = false;



            }



        }



    }







    async function openCtiArticles() {



        document.getElementById('cti-pane').style.display = 'flex';



        const feed = document.getElementById('cti-feed');



        if (feed && ctiSourcesData.length === 0) {



            feed.innerHTML = '<div style="color:var(--text-muted); padding:24px; text-align:center;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Initializing CTI Articles metadata...</div>';



        }



        if (!ctiBound) {



            ctiBound = true;



            document.querySelectorAll('[data-ctiview]').forEach(b => b.addEventListener('click', () => ctiSetView(b.dataset.ctiview)));



            document.querySelectorAll('#cti-time-tabs .galaxy-subtab').forEach(b => b.addEventListener('click', () => {



                document.querySelectorAll('#cti-time-tabs .galaxy-subtab').forEach(x => x.classList.toggle('active', x === b));



                ctiHours = parseInt(b.dataset.hours || '0', 10) || 0;



                ctiLoadFeed(true);



            }));



            document.getElementById('cti-source').addEventListener('change', (e) => {



                ctiSource = e.target.value || '';



                ctiLoadFeed(true);



            });



            document.getElementById('cti-more').addEventListener('click', () => {



                if (ctiView === 'recent') {



                    ctiLoadFeed(false);



                } else if (ctiView === 'sources') {



                    ctiSourceLimit += 25;



                    ctiRenderSources();



                }



            });



            document.getElementById('cti-sync').addEventListener('click', ctiSyncNow);



            const searchInput = document.getElementById('cti-search-input');



            if (searchInput) {



                searchInput.addEventListener('keypress', (e) => {



                    if (e.key === 'Enter') ctiLoadFeed(true);



                });



            }



            ctiEnsureArticleModalEvents();



            document.getElementById('cti-cat-modal-close')?.addEventListener('click', () => {



                document.getElementById('cti-cat-modal-overlay').style.display = 'none';



            });



            document.getElementById('cti-cat-modal-overlay')?.addEventListener('click', (e) => {



                if (e.target.id === 'cti-cat-modal-overlay') document.getElementById('cti-cat-modal-overlay').style.display = 'none';



            });



            document.getElementById('cti-cat-add-btn')?.addEventListener('click', (e) => {



                e.preventDefault();



                ctiAddCategory();



            });



            document.addEventListener('click', (e) => {



                const retry = e.target.closest('.cti-retry');



                if (retry) {



                    e.preventDefault();



                    ctiLoadFeed(true);



                    return;



                }



                const addToggle = e.target.closest('.cti-add-toggle');



                if (addToggle) {



                    e.preventDefault();



                    ctiShowAdd = !ctiShowAdd;



                    ctiRenderSources();



                    return;



                }



                if (e.target.closest('.cti-add-save')) {



                    e.preventDefault();



                    ctiAddFeed();



                    return;



                }



                if (e.target.closest('.cti-add-cancel')) {



                    e.preventDefault();



                    ctiShowAdd = false;



                    ctiRenderSources();



                    return;



                }



                const editBtn = e.target.closest('.cti-edit-source');



                if (editBtn) {



                    e.preventDefault();



                    ctiEditId = ctiEditId === editBtn.dataset.sourceId ? null : editBtn.dataset.sourceId;



                    ctiRenderSources();



                    return;



                }



                if (e.target.closest('.cti-edit-cancel')) {



                    e.preventDefault();



                    ctiEditId = null;



                    ctiRenderSources();



                    return;



                }



                const editSave = e.target.closest('.cti-edit-save');



                if (editSave) {



                    e.preventDefault();



                    ctiSaveSource(editSave.dataset.sourceId);



                    return;



                }



                const delSource = e.target.closest('.cti-delete-source');



                if (delSource) {



                    e.preventDefault();



                    ctiDeleteSource(delSource.dataset.sourceId, delSource.dataset.sourceName);



                    return;



                }



                const catEditBtn = e.target.closest('.cti-cat-edit-btn');



                if (catEditBtn) {



                    e.preventDefault();



                    ctiEditingCat = catEditBtn.dataset.cat;



                    ctiLoadCategoryModalList();



                    return;



                }



                const catRenameSave = e.target.closest('.cti-cat-rename-save');



                if (catRenameSave) {



                    e.preventDefault();



                    const row = catRenameSave.closest('div').parentElement;



                    const input = row.querySelector('.cti-cat-rename-input');



                    ctiRenameCategory(catRenameSave.dataset.oldCat, (input?.value || '').trim());



                    return;



                }



                if (e.target.closest('.cti-cat-rename-cancel')) {



                    e.preventDefault();



                    ctiEditingCat = null;



                    ctiLoadCategoryModalList();



                    return;



                }



                const catDelBtn = e.target.closest('.cti-cat-delete-btn');



                if (catDelBtn) {



                    e.preventDefault();



                    ctiDeleteCategory(catDelBtn.dataset.cat);



                    return;



                }



                const t = e.target.closest('.cti-toggle-source');



                if (t) {



                    e.preventDefault();



                    ctiToggleSource(t.dataset.sourceId, t.dataset.enabled === '1');



                    return;



                }



            });



            ctiLoadSources(true);



        } else {



            ctiLoadSources(true);



        }



        ctiSetView(ctiView);



    }







