    async function tgAddMonitoredChannel() {



        const username = (document.getElementById('tg-add-chan-input')?.value || '').trim();



        const category = document.getElementById('tg-add-chan-cat')?.value || 'threat_actor_public';



        if (!username) return showNotification('Enter channel username or link');



        try {



            const res = await fetch('/api/tg/monitor/channels', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ username, category })



            });



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(`Channel ${username} added to watchlist!`);



            document.getElementById('tg-add-chan-input').value = '';



            tgLoadMonitoredChannels();



            tgLoadMonitorStats();



            if (d.channel) {



                // Auto-sync new channel so it populates immediately



                tgSyncMonitoredChannel(d.channel.id, d.channel.username);



            }



        } catch (e) {



            showNotification(`Failed to add channel: ${e.message}`);



        }



    }







    async function tgDeleteMonitoredChannel(cid) {



        if (!confirm('Remove this channel from watchlist?')) return;



        try {



            const res = await fetch(`/api/tg/monitor/channels/${encodeURIComponent(cid)}`, { method: 'DELETE' });



            const data = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);



            showNotification('Channel removed.');



            tgLoadMonitoredChannels();



            tgLoadMonitorStats();



        } catch (e) {



            showNotification(`Delete failed: ${e.message}`);



        }



    }







    async function tgSyncMonitoredChannel(cid, username) {



        const btn = document.querySelector(`.tg-sync-chan-btn[data-id="${CSS.escape(cid)}"]`);



        if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Syncing...'; }



        try {



            const res = await fetch('/api/tg/mtproto/sync-history', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ channel_id: cid, channel_username: username, limit: 50 })



            });



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(`Synced ${d.synced_messages || 0} msgs, ${d.new_exposures || 0} exposures found.`);



            tgLoadMonitoredChannels();



            tgLoadLiveFeed();



            tgLoadMonitorStats();



        } catch (e) {



            showNotification(`Sync failed: ${e.message}`);



        } finally {



            if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-rotate"></i> Sync History'; }



        }



    }







    let tgIsSyncingAll = false;



    async function tgSyncAllChannels() {



        if (tgIsSyncingAll) return;



        tgIsSyncingAll = true;



        const btn = document.getElementById('tg-feed-refresh');



        if (btn) { btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Syncing...'; }



        try {



            const res = await fetch('/api/tg/monitor/channels');



            const chans = await res.json();



            if (!res.ok) throw new Error(chans.detail || `HTTP ${res.status}`);



            let failed = 0;



            if (chans && chans.length) {



                for (const c of chans) {



                    try {



                        const syncRes = await fetch('/api/tg/mtproto/sync-history', {



                            method: 'POST', headers: { 'Content-Type': 'application/json' },



                            body: JSON.stringify({ channel_id: c.id, channel_username: c.username, limit: 20 })



                        });



                        if (!syncRes.ok) failed += 1;



                    } catch (e) { failed += 1; }



                }



            }



            if (failed) showNotification(`${failed} channel sync${failed === 1 ? '' : 's'} failed. Check authentication and channel access.`);



        } catch (e) {



            console.error('Failed to sync all channels:', e);



        } finally {



            if (btn) { btn.innerHTML = '<i class="fa-solid fa-rotate"></i> Refresh Feed'; }



            tgIsSyncingAll = false;



        }



    }







    let tgLiveFeedState = { page: 1, pageSize: 20 };



    let tgFeedViewMode = localStorage.getItem('tg_feed_view_mode') || 'card';







    function setTgFeedViewMode(mode) {



        tgFeedViewMode = mode === 'list' ? 'list' : 'card';



        try { localStorage.setItem('tg_feed_view_mode', tgFeedViewMode); } catch (e) { }



        const listEl = document.getElementById('tg-live-feed-list');



        const cardBtn = document.getElementById('tg-feed-view-card');



        const listBtn = document.getElementById('tg-feed-view-list');



        if (listEl) {



            listEl.classList.remove('card-view', 'list-view');



            listEl.classList.add(tgFeedViewMode === 'list' ? 'list-view' : 'card-view');



        }



        if (cardBtn) cardBtn.classList.toggle('active', tgFeedViewMode === 'card');



        if (listBtn) listBtn.classList.toggle('active', tgFeedViewMode === 'list');



    }



    window.setTgFeedViewMode = setTgFeedViewMode;







    function formatTgText(rawText) {



        if (!rawText) return '';



        // 1. Remove ➡️ / ➡ arrow emojis (and pointer emojis preceding a URL)



        let clean = rawText.replace(/(?:[\u27A1\uFE0F\u27A1]|👉|🔗)+\s*(https?:\/\/)/gu, '\n\n$1');



        clean = clean.replace(/[\u27A1\uFE0F\u27A1]+/gu, '');







        // 2. Add extra blank line gap between body text / hashtags and the link



        clean = clean.replace(/([^\n])\s*\n\s*(https?:\/\/)/g, '$1\n\n$2');



        clean = clean.replace(/\n{3,}/g, '\n\n');







        let safe = escapeHtml(clean);



        // Highlight hashtags



        safe = safe.replace(/(#[\w\d_-]+)/g, '<span style="color:#38bdf8; font-weight:600;">$1</span>');



        // Linkify URLs with dedicated link class and icon



        safe = safe.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer" class="tg-feed-link"><i class="fa-solid fa-arrow-up-right-from-square"></i><span>$1</span></a>');



        return safe;



    }







    function renderTgLiveFeedPager(pagination = {}) {



        const pager = document.getElementById('tg-live-feed-pagination');



        if (!pager) return;



        const pages = Number(pagination.pages || 1);



        const page = Number(pagination.page || 1);



        const total = Number(pagination.total || 0);







        if (pages <= 1) {



            pager.innerHTML = total > 0 ? `<div style="color:var(--text-muted); font-size:0.75rem;">Showing ${total} message${total === 1 ? '' : 's'}</div>` : '';



            return;



        }







        const buttons = [];



        for (let p = 1; p <= pages; p += 1) {



            if (p === 1 || p === pages || Math.abs(p - page) <= 2) {



                buttons.push(`<button type="button" class="${p === page ? 'active' : ''}" onclick="window.tgLoadLiveFeed(${p})">${p}</button>`);



            } else if (!buttons[buttons.length - 1]?.includes('xmon-page-gap')) {



                buttons.push('<span class="xmon-page-gap">...</span>');



            }



        }



        pager.innerHTML = `



            <div style="display:flex; align-items:center; gap:10px; width:100%; justify-content:center; flex-wrap:wrap;">



                <span style="color:var(--text-muted); font-size:0.75rem; margin-right:8px;">Page ${page} of ${pages} (${total} total messages)</span>



                ${buttons.join('')}



            </div>



        `;



    }







    async function tgLoadLiveFeed(targetPage) {



        if (typeof targetPage === 'number') {



            tgLiveFeedState.page = targetPage;



        }



        const list = document.getElementById('tg-live-feed-list');



        const pager = document.getElementById('tg-live-feed-pagination');



        const cat = document.getElementById('tg-feed-cat-filter')?.value || '';



        if (!list) return;



        try {



            const res = await fetch(`/api/tg/monitor/live-feed?page=${tgLiveFeedState.page}&page_size=${tgLiveFeedState.pageSize}&category=${encodeURIComponent(cat)}`);



            const data = await res.json();



            if (!res.ok) throw new Error(`HTTP ${res.status}`);







            let msgs = [];



            let pagination = {};



            if (Array.isArray(data)) {



                msgs = data;



            } else {



                msgs = data.messages || [];



                pagination = data.pagination || {};



            }







            if (!msgs || !msgs.length) {



                list.innerHTML = '<div class="empty-state"><i class="fa-solid fa-tower-broadcast"></i><p>No messages in stream yet. Sync or monitor channels to populate feed.</p></div>';



                if (pager) pager.innerHTML = '';



                return;



            }







            list.innerHTML = msgs.map(m => {



                const rawChan = (m.channel_title || m.channel_username || 'Channel').replace(/[\u27A1\uFE0F\u27A1]+/gu, '').trim();



                const chanName = escapeHtml(rawChan || 'Channel');



                const catName = escapeHtml(m.channel_category || 'threat_actor_public');



                const timeStr = escapeHtml((m.timestamp || '').replace('T', ' '));



                const formattedBody = formatTgText(m.text || '');







                return `



                <div class="tg-feed-item">



                    <div class="tg-feed-item-header">



                        <span class="tg-feed-channel" style="display:inline-flex; align-items:center; gap:6px;">



                            <i class="fa-brands fa-telegram" style="color:#38bdf8; font-size:0.85rem;"></i>



                            <span>${chanName}</span>



                        </span>



                        <span class="tg-cat-badge tg-cat-${catName}">${catName}</span>



                        <span style="color:var(--text-muted); font-size:0.72rem; margin-left:auto; white-space:nowrap;">



                            <i class="fa-regular fa-clock"></i> ${timeStr}



                        </span>



                    </div>



                    <div class="tg-feed-body">${formattedBody}</div>



                    ${m.file_name ? `<div style="font-size:0.75rem; color:var(--accent); display:flex; align-items:center; gap:6px; background:rgba(255,204,0,0.06); border:1px solid rgba(255,204,0,0.2); padding:6px 10px; border-radius:6px; margin-top:auto;"><i class="fa-solid fa-paperclip"></i> <span>${escapeHtml(m.file_name)} (${escapeHtml(String(m.file_size || 0))} bytes) — Cleaned</span></div>` : ''}



                </div>



            `;



            }).join('');







            setTgFeedViewMode(tgFeedViewMode);



            renderTgLiveFeedPager(pagination);



        } catch (e) {



            list.innerHTML = `<div style="color:var(--danger);">Feed error: ${escapeHtml(e.message)}</div>`;



            if (pager) pager.innerHTML = '';



        }



    }



    window.tgLoadLiveFeed = tgLoadLiveFeed;







