    async function tgLoadBots() {



        const list = document.getElementById('tg-bots-list');



        if (list && list.innerHTML.trim() === '') {



            list.innerHTML = '<div style="color:var(--text-muted); padding:24px; text-align:center;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Initializing Telegram Bot metadata...</div>';



        }



        try {



            const res = await fetch('/api/tg/bots');



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            tgRenderBots(d.bots || []);



            const anyRunning = (d.bots || []).some(b => b.job_running);



            const banner = document.getElementById('tg-active-banner');



            if (banner) banner.style.display = anyRunning ? '' : 'none';



        } catch (e) {



            showNotification(`Could not load bots: ${e.message}`);



        }



    }







    function tgRenderBots(bots) {



        const box = document.getElementById('tg-bots');



        bots = bots || [];



        // bot filter for the explorer



        const msgSel = document.getElementById('tg-msg-bot');



        const mcur = msgSel.value;



        msgSel.innerHTML = '<option value="">All bots</option>' + bots.map(b => `<option value="${esc(b.id)}">${esc(b.username ? '@' + b.username : (b.bot_id || b.id.slice(-6)))}</option>`).join('');



        if ([...msgSel.options].some(o => o.value === mcur)) msgSel.value = mcur;



        if (!bots.length) {



            box.innerHTML = `<div class="empty-state" style="grid-column: 1 / -1;"><i class="fa-brands fa-telegram"></i><p>No bots tracked yet. Add one below — adding is passive, nothing contacts Telegram.</p></div>`;



            return;



        }



        box.innerHTML = '';



        bots.forEach(b => {



            const card = document.createElement('div');



            card.className = 'tg-bot-card';



            const running = !!b.job_running;



            const stateColor = running ? 'var(--success)' : (b.state === 'error' ? 'var(--danger)' : 'var(--text-muted)');



            const dumpPct = b.dump_total > 0 ? Math.round(((b.dump_done || 0) / b.dump_total) * 100) : (b.dump_total === -1 ? 'indeterminate' : -1);



            card.innerHTML = `



                <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">



                    <div style="display:flex; flex-direction:column; gap:2px; min-width:0;">



                        <span style="font-weight:700; font-size:1rem; color:var(--text-main); overflow-wrap:anywhere;">${esc(b.username ? '@' + b.username : (b.display_name || b.bot_id || 'Unverified bot'))}</span>



                        <span style="font-family:var(--font-mono); font-size:0.7rem; color:var(--text-muted); overflow-wrap:anywhere; word-break:break-all;">${esc(b.token_masked || '')}</span>



                    </div>



                    <div style="display:flex; gap:6px; align-items:center; flex-shrink:0;">



                        ${tgStateBadge(running ? 'running' : b.state)}



                        ${running ? '<span style="font-size:0.68rem; color:var(--success); font-weight:700; letter-spacing:0.5px;">● LIVE</span>' : ''}



                    </div>



                </div>



                <div style="display:grid; grid-template-columns:1fr 1fr; gap:4px 12px; font-size:0.75rem;">



                    <div style="color:var(--text-muted);">Chat ID: <b style="color:var(--text-main); font-family:var(--font-mono);">${esc(b.chat_id || '—')}</b></div>



                    <div style="color:var(--text-muted);">Mode: <b style="color:var(--text-main);">${esc(b.mode === 'live' ? 'Live' : 'Full')} / ${esc(b.transport === 'manual' ? 'Manual' : 'Native')}</b></div>



                    <div style="color:var(--text-muted);">Token State: <b style="color:${b.token_state === 'live' ? 'var(--success)' : 'var(--text-muted)'}">${esc(b.token_state || 'not-validated')}</b></div>



                    <div style="color:var(--text-muted);">Messages: <b style="color:var(--text-main);">${esc(String(b.total_messages || 0))}</b></div>



                    ${b.first_message_at ? `<div style="color:var(--text-muted); grid-column:1/-1;">First: ${esc(b.first_message_at.slice(0, 16).replace('T', ' '))} · Latest: ${esc((b.latest_message_at || '').slice(0, 16).replace('T', ' '))}</div>` : ''}



                </div>



                ${b.dump_total === -1 || b.dump_total > 0 ? `



                <div style="font-size:0.72rem; color:var(--text-muted);">



                    <div style="display:flex; justify-content:space-between; margin-bottom:3px;">



                        <span>Dump Progress</span>



                        <span>${esc(String(b.dump_done || 0))} ${b.dump_total > 0 ? `/ ${esc(String(b.dump_total))}` : ''} messages copied ${b.dump_total > 0 ? `(${dumpPct}%)` : '<i class="fa-solid fa-circle-notch mantis-spin"></i>'}</span>



                    </div>



                    <div style="height:5px; background:rgba(255,255,255,0.08); border-radius:3px; overflow:hidden;">



                        <div style="height:100%; width:${b.dump_total > 0 ? dumpPct : 100}%; background:var(--accent); border-radius:3px; transition:width 0.4s; ${b.dump_total === -1 ? 'animation: mantis-pulse 1.5s infinite;' : ''}"></div>



                    </div>



                    ${(b.failed_ids || []).length ? `<div style="color:var(--danger); margin-top:3px;"><i class="fa-solid fa-circle-exclamation"></i> ${esc(String(b.failed_ids.length))} message IDs failed to copy</div>` : ''}



                </div>` : ''}



                ${b.last_error ? `<div style="font-size:0.72rem; color:var(--danger); background:rgba(220,53,69,0.1); padding:5px 8px; border-radius:4px;"><i class="fa-solid fa-triangle-exclamation"></i> ${esc(b.last_error)}</div>` : ''}



                <div class="tg-card-actions">



                    <button class="btn-secondary tg-icon-btn" data-tg-bot-action="validate" data-bot-id="${esc(b.id)}" title="ACTIVE: getMe - confirms token is live"><i class="fa-solid fa-check-circle"></i> Validate</button>



                    ${running



                    ? `<button class="btn-secondary tg-icon-btn" data-tg-bot-action="pause" data-bot-id="${esc(b.id)}"><i class="fa-solid fa-pause"></i> Pause</button>



                           <button class="btn-secondary tg-icon-btn" data-tg-bot-action="stop" data-bot-id="${esc(b.id)}"><i class="fa-solid fa-stop"></i> Stop</button>`



                    : `<button class="btn-secondary tg-icon-btn" data-tg-bot-action="start" data-bot-id="${esc(b.id)}" title="ACTIVE: starts Telegram collection"><i class="fa-solid fa-play"></i> ${b.state === 'paused' ? 'Resume' : 'Start Collection'}</button>`}



                    <button class="btn-secondary tg-icon-btn" data-tg-bot-action="messages" data-bot-id="${esc(b.id)}"><i class="fa-solid fa-envelope-open-text"></i> Messages</button>



                    <button class="btn-secondary tg-icon-btn tg-danger-action" data-tg-bot-action="delete" data-bot-id="${esc(b.id)}" title="Remove this bot and all its collected data"><i class="fa-solid fa-trash"></i> Delete</button>



                </div>



                <div class="tg-bot-note" style="font-size:0.72rem; color:var(--text-muted);"></div>`;



            box.appendChild(card);



        });



        if (typeof tgToggleMode === 'function') {



            tgToggleMode();



        }



    }







    async function tgBotAction(id, action) {



        if (action === 'messages') {



            const sel = document.getElementById('tg-msg-bot');



            sel.value = id;



            tgLoadMessages(true);



            document.getElementById('tg-explorer-container').scrollIntoView({ behavior: 'smooth', block: 'start' });



            return;



        }



        if (action === 'delete') {



            if (!window.confirm('Delete this bot and all its collected messages? This cannot be undone.')) return;







            const btn = document.querySelector(`button[data-tg-bot-action="delete"][data-bot-id="${CSS.escape(id)}"]`);



            let origHtml = '';



            if (btn) {



                origHtml = btn.innerHTML;



                btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Deleting...';



                btn.disabled = true;



                btn.style.opacity = '0.7';



            }







            try {



                const res = await fetch(`/api/tg/bots/${encodeURIComponent(id)}`, { method: 'DELETE' });



                const d = await res.json().catch(() => ({}));



                if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



                showNotification('Bot deleted.');



                tgLoadBots();



                tgLoadMessages(true);



            } catch (e) {



                showNotification(`Delete failed: ${e.message}`);



                if (btn) {



                    btn.innerHTML = origHtml;



                    btn.disabled = false;



                    btn.style.opacity = '';



                }



            }



            return;



        }



        if (action === 'start' || action === 'validate') {



            const isModeB = document.getElementById('tg-global-mode-b')?.checked;



            if (action === 'start' && isModeB) {



                alert("Now go to your telegram to see the chat");



            } else {



                const label = action === 'start'



                    ? 'start Telegram message collection using the transport selected when this bot was added'



                    : 'validate this credential against Telegram (getMe)';



                if (!window.confirm(`ACTIVE OPERATION — this will ${label}. Continue?`)) return;



            }



        }



        const note = (msg) => showNotification(msg);



        try {



            let res;



            if (action === 'validate') {



                res = await fetch(`/api/tg/bots/${encodeURIComponent(id)}/validate`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({}) });



            } else {



                res = await fetch(`/api/tg/bots/${encodeURIComponent(id)}/${action}`, { method: 'POST' });



            }



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            if (action === 'validate') {



                note(d.username ? `Token valid — @${d.username}` : 'Token valid');



            } else {



                note('Done');



            }



            tgLoadBots();



            if (action === 'start' && typeof window._tgStartAutoRefresh === 'function') {



                window._tgStartAutoRefresh();



            }



        } catch (e) {



            note(`Failed: ${e.message}`);



        }



    }







    async function tgLoadMessages(reset, silent = false) {



        const box = document.getElementById('tg-messages');



        if (reset && !silent) { tgMsgOffset = 0; box.innerHTML = ''; }



        if (reset) { tgMsgOffset = 0; }



        document.getElementById('tg-msg-count').textContent = '…';



        if (reset && !silent) box.innerHTML = '<div style="color:var(--text-muted); padding:14px;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Loading messages…</div>';



        const q = new URLSearchParams({



            bot_id: document.getElementById('tg-msg-bot').value || '',



            text: document.getElementById('tg-msg-text').value || '',



            msg_type: document.getElementById('tg-msg-type').value || '',



            date_from: document.getElementById('tg-msg-from').value || '',



            date_to: document.getElementById('tg-msg-to').value || '',



            limit: String(TG_MSG_PAGE), offset: String(tgMsgOffset)



        });



        try {



            const res = await fetch(`/api/tg/messages?${q.toString()}`);



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            if (reset) box.innerHTML = '';



            document.getElementById('tg-msg-count').textContent = `${d.total || 0} messages`;



            if (!d.messages || !d.messages.length) {



                if (reset) box.innerHTML = `<div class="empty-state"><i class="fa-solid fa-envelope-open-text"></i><p>No messages match. Start collection to capture Telegram traffic.</p></div>`;



                document.getElementById('tg-msg-more').style.display = 'none';



                return;



            }



            d.messages.forEach(m => {



                const el = document.createElement('div');



                el.style.cssText = 'background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 8px; padding: 12px 14px; display:flex; flex-direction:column; gap:6px;';



                const typeIcon = { text: 'fa-comment', photo: 'fa-image', document: 'fa-file', video: 'fa-video', audio: 'fa-music', voice: 'fa-microphone', sticker: 'fa-face-smile' }[m.msg_type] || 'fa-comment';



                const typeBg = { text: 'rgba(0,168,142,0.12)', photo: 'rgba(74,158,255,0.12)', document: 'rgba(255,193,7,0.12)', video: 'rgba(156,39,176,0.12)', audio: 'rgba(233,30,99,0.12)' }[m.msg_type] || 'rgba(255,255,255,0.05)';



                const typeColor = { text: 'var(--accent)', photo: '#4a9eff', document: '#ffc107', video: '#9c27b0', audio: '#e91e63' }[m.msg_type] || 'var(--text-muted)';



                el.innerHTML = `



                    <div style="display:flex; align-items:center; gap:8px; justify-content:space-between;">



                        <div style="display:flex; align-items:center; gap:8px;">



                            <span style="display:inline-flex; align-items:center; justify-content:center; width:28px; height:28px; border-radius:50%; background:${typeBg}; color:${typeColor}; font-size:0.8rem;"><i class="fa-solid ${typeIcon}"></i></span>



                            <div>



                                <span style="font-weight:600; font-size:0.85rem; color:var(--text-main);">${esc(m.sender || 'Unknown')}</span>



                                <span style="font-size:0.75rem; color:var(--text-muted); margin-left:6px;">→ Chat <span style="font-family:var(--font-mono);">${esc(m.chat_id || '—')}</span></span>



                            </div>



                        </div>



                        <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">



                            ${m.forwarded ? '<span style="font-size:0.68rem; background:rgba(0,168,142,0.15); color:var(--accent); padding:2px 6px; border-radius:4px;">forwarded</span>' : ''}



                            ${m.copied ? '<span style="font-size:0.68rem; background:rgba(74,158,255,0.15); color:#4a9eff; padding:2px 6px; border-radius:4px;">copied</span>' : ''}



                            <span style="font-size:0.72rem; color:var(--text-muted); font-family:var(--font-mono);">${esc((m.timestamp || '').replace('T', ' '))}</span>



                            <span style="font-size:0.68rem; color:var(--text-muted); font-family:var(--font-mono);">#${esc(String(m.message_id))}</span>



                        </div>



                    </div>



                    ${m.text ? `<div style="font-size:0.88rem; color:var(--text-main); overflow-wrap:anywhere; white-space:pre-wrap; line-height:1.5; padding:8px 10px; background:rgba(0,0,0,0.2); border-radius:6px;">${esc(m.text)}</div>` : ''}



                    ${m.msg_type === 'photo' && !m.file_name ? `<div style="font-size:0.75rem; color:#4a9eff; display:flex; align-items:center; gap:6px; padding:6px 10px; background:rgba(74,158,255,0.07); border-radius:6px; border:1px solid rgba(74,158,255,0.15);"><i class="fa-solid fa-image" style="color:#4a9eff;"></i> <span style="font-family:var(--font-mono);">Photo</span></div>` : ''}



                    ${m.file_name ? `<div style="font-size:0.75rem; color:var(--text-muted); display:flex; align-items:center; gap:6px; padding:6px 10px; background:rgba(255,193,7,0.07); border-radius:6px; border:1px solid rgba(255,193,7,0.15);"><i class="fa-solid fa-paperclip" style="color:#ffc107;"></i> <span style="font-family:var(--font-mono);">${esc(m.file_name)}</span>${m.file_size ? ` <span>(${esc(String(m.file_size))} bytes)</span>` : ''}${m.mime_type ? ` · ${esc(m.mime_type)}` : ''}</div>` : ''}



                    ${m.caption ? `<div style="font-size:0.88rem; color:var(--text-main); overflow-wrap:anywhere; white-space:pre-wrap; line-height:1.5; padding:8px 10px; background:rgba(0,0,0,0.2); border-radius:6px; font-style:italic;">${esc(m.caption)}</div>` : ''}



                    ${m.reply_to ? `<div style="font-size:0.72rem; color:var(--text-muted);"><i class="fa-solid fa-reply"></i> Reply to msg #${esc(String(m.reply_to))}</div>` : ''}`;



                box.appendChild(el);



            });



            tgMsgOffset += d.messages.length;



            document.getElementById('tg-msg-more').style.display = tgMsgOffset < (d.total || 0) ? '' : 'none';



        } catch (e) {



            if (reset) box.innerHTML = `<div class="empty-state"><i class="fa-solid fa-triangle-exclamation" style="color:var(--danger);"></i><p>Could not load messages: ${esc(e.message)}</p></div>`;



            document.getElementById('tg-msg-more').style.display = 'none';



        }



    }







    function tgDownload(filename, content, mediaType) {



        const blob = new Blob([content], { type: mediaType });



        const a = document.createElement('a');



        a.href = URL.createObjectURL(blob);



        a.download = filename;



        document.body.appendChild(a);



        a.click();



        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);



    }







    async function tgExport(fmt) {



        if (!tgInvId) {



            showNotification('Select an investigation first');



            return;



        }



        try {



            const res = await fetch(`/api/tg/export/${encodeURIComponent(tgInvId)}?fmt=${fmt}`);



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            if (fmt === 'csv') {



                tgDownload(`${tgInvId}_messages.csv`, await res.text(), 'text/csv;charset=utf-8');



            } else {



                tgDownload(`${tgInvId}_investigation.json`, JSON.stringify(await res.json(), null, 2), 'application/json');



            }



            showNotification(`Exported (secrets excluded)`);



        } catch (e) {



            showNotification(`Export failed: ${e.message}`);



        }



    }







    let tgDiscData = { threatfox: [], urlscan: [], malwarebazaar: [], cti: [] };







    async function tgRunOneSource(source, query, size, keys) {



        // Independent per-source search: progress + failure isolated so one



        // dead provider never removes another provider's results.



        tgDiscStatusLine(source, 'searching');



        try {



            const res = await fetch('/api/tg/discover/search', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ source, query, size, ...keys })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) {



                if (res.status === 405) throw new Error('Server is running older code — stop it fully and restart run.bat');



                throw new Error(d.detail || `HTTP ${res.status}`);



            }



            const groups = ((d.grouped || {}).groups) || [];



            tgDiscStatusLine(source, 'done', ((d.grouped || {}).total || 0));



            return groups;



        } catch (e) {



            tgDiscStatusLine(source, 'failed', 0, e.message);



            return [];



        }



    }







    function tgDiscStatusLine(source, state, count, error) {



        const el = document.getElementById(`tg-disc-st-${source}`);



        if (!el) return;



        if (state === 'searching') {



            el.innerHTML = `<i class="fa-solid fa-circle-notch mantis-spin"></i> Searching ${esc(source)}…`;



        } else if (state === 'done') {



            el.innerHTML = `${esc(source)} — <b style="color:var(--accent);">${count}</b> artifact(s)`;



        } else {



            el.innerHTML = `${esc(source)} — <b style="color:var(--danger);">Failed</b>${error ? `: ${esc(error)}` : ''}`;



        }



    }







    async function tgRunDiscovery() {



        const box = document.getElementById('tg-disc-results');



        const query = document.getElementById('tg-disc-query').value || 'api.telegram.org';



        const size = parseInt(document.getElementById('tg-disc-size').value || '50', 10) || 50;



        const keys = {



            abusech_key: localStorage.getItem('ioc_abusech_key') || '',



            urlscan_key: localStorage.getItem('ioc_urlscan_key') || ''



        };



        tgDiscGroups = [];



        tgDiscKindFilter = '';



        tgDiscSourceFilter = '';



        box.innerHTML = `<div id="tg-disc-st-threatfox" style="font-size:0.8rem; color:var(--text-muted); margin-bottom:4px;"></div>



            <div id="tg-disc-st-urlscan" style="font-size:0.8rem; color:var(--text-muted); margin-bottom:8px;"></div>



            <div style="color:var(--text-muted); padding:6px 0;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Running passive discovery…</div>`;



        const [tf, us] = await Promise.all([



            tgRunOneSource('threatfox', query, size, keys),



            tgRunOneSource('urlscan', query, size, keys)



        ]);



        tgDiscGroups = [...tf, ...us];



        tgRenderDiscovery();



    }







    const tgDiscSourceSel = () => (document.getElementById('tg-disc-source')?.value || 'all');



    let tgDiscGroups = [];



    let tgDiscKindFilter = '';



    let tgDiscSourceFilter = '';







    async function tgSearchDiscovery() {



        const source = tgDiscSourceSel();



        if (source === 'all') {



            tgRunDiscovery();



            return;



        }



        const box = document.getElementById('tg-disc-results');



        const query = document.getElementById('tg-disc-query').value || '';



        const size = parseInt(document.getElementById('tg-disc-size').value || '50', 10) || 50;



        const keys = {



            abusech_key: localStorage.getItem('ioc_abusech_key') || '',



            urlscan_key: localStorage.getItem('ioc_urlscan_key') || ''



        };



        tgDiscGroups = [];



        tgDiscKindFilter = '';



        tgDiscSourceFilter = '';



        box.innerHTML = `<div id="tg-disc-st-${esc(source)}" style="font-size:0.8rem; color:var(--text-muted); margin-bottom:8px;"></div>



            <div style="color:var(--text-muted); padding:6px 0;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Searching…</div>`;



        tgDiscGroups = await tgRunOneSource(source, query, size, keys);



        tgRenderDiscovery();



    }







    const tgGroupHost = (link, fallback) => {



        try {



            const u = new URL(link);



            return u.hostname || fallback;



        } catch (_) {



            return fallback;



        }



    };







    const TG_KIND_LABEL = { bot_token: 'BOT TOKEN', chat_id: 'CHAT ID', api_url: 'API URL', bot_username: 'BOT USERNAME' };







    function tgRenderDiscovery() {



        const box = document.getElementById('tg-disc-results');



        let groups = tgDiscGroups || [];



        if (tgDiscSourceFilter) groups = groups.filter(g => g.source === tgDiscSourceFilter);



        if (tgDiscKindFilter) {



            groups = groups



                .map(g => ({ ...g, artifacts: (g.artifacts || []).filter(a => a.type === tgDiscKindFilter) }))



                .filter(g => g.artifacts.length);



        }



        const total = groups.reduce((n, g) => n + (g.artifacts || []).length, 0);



        const hosts = new Set(groups.map(g => g.host).filter(Boolean)).size;



        const sources = [...new Set(groups.map(g => g.source).filter(Boolean))];



        const kindPill = (label, kind) => `<button class="galaxy-subtab${tgDiscKindFilter === kind ? ' active' : ''}" data-tgkindf="${esc(kind)}" style="font-size: 0.75rem;">${esc(label)}</button>`;



        const srcPill = (label, src) => `<button class="galaxy-subtab${tgDiscSourceFilter === src ? ' active' : ''}" data-tgsrcf="${esc(src)}" style="font-size: 0.75rem;">${esc(label)}</button>`;



        let html = '';



        if (tgDiscGroups.length || total) {



            html += `<div style="font-size:0.85rem; font-weight:700; color:var(--text-main); margin:2px 0;">Discovery Results</div>`;



            html += `<div style="font-size:0.78rem; color:var(--text-muted); margin-bottom:6px;">Found ${total} artifact(s) across ${hosts} host(s)${sources.length > 1 ? ` from ${sources.length} sources` : sources.length ? ` from ${esc(sources[0])}` : ''}.</div>`;



            html += `<div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:4px;">`



                + kindPill('All', '') + kindPill('Bot Tokens', 'bot_token') + kindPill('API URLs', 'api_url') + kindPill('Chat IDs', 'chat_id') + kindPill('Bot Usernames', 'bot_username') + `</div>`;



            if (sources.length > 1) {



                html += `<div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:8px;">`



                    + srcPill('All sources', '') + sources.map(s => srcPill(s, s)).join('') + `</div>`;



            }



        }



        groups.forEach((g, gi) => {



            const tokens = (g.artifacts || []).filter(a => a.type === 'bot_token');



            const chats = [...new Set((g.artifacts || []).filter(a => a.type === 'chat_id').map(a => a.normalized_value))];



            const fams = [...new Set((g.artifacts || []).map(a => a.malware_family).filter(Boolean))];



            html += `<div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 8px; padding: 12px 14px; margin-bottom: 8px;">



                <div style="display:flex; justify-content:space-between; gap:10px; align-items:center; margin-bottom:2px;">



                    <span style="font-size:0.75rem; font-weight:700; color:var(--text-main);">${esc(g.source || '')}</span>



                    <span style="font-size:0.72rem; color:var(--text-muted);">${esc((g.observed_at || '').slice(0, 10))}</span>



                </div>



                ${g.source_url ? `<div style="font-family:var(--font-mono); font-size:0.75rem; color:var(--accent); overflow-wrap:anywhere; margin-bottom:8px;">${esc(g.source_url)}</div>` : ''}



                ${g.title && g.title !== g.source_url ? `<div style="font-size:0.78rem; color:var(--text-muted); margin-bottom:8px;">${esc(g.title)}</div>` : ''}`;



            tokens.forEach((t, ti) => {



                const key = `${gi}:${ti}`;



                const chatCsv = chats.join(', ');



                html += `<div style="margin:8px 0; padding:8px 10px; background:rgba(0,0,0,0.25); border-radius:6px;">



                    <div style="font-size:0.68rem; font-weight:700; letter-spacing:1px; color:var(--accent); margin-bottom:4px;">BOT TOKEN${t.seen_in && t.seen_in.length ? `<span style="color:var(--text-muted); font-weight:400;"> · seen in ${esc(t.seen_in.join(', '))}</span>` : ''}</div>



                    <div class="tg-tok" data-tgkey="${esc(key)}" data-full="${esc(t.normalized_value)}" data-masked="1" style="font-family:var(--font-mono); font-size:0.82rem; color:var(--text-main); overflow-wrap:anywhere; margin-bottom:6px;">${esc(tgMask(t.observed_value || t.normalized_value))}</div>



                    <div style="font-size:0.72rem; color:var(--text-muted); font-family:var(--font-mono); margin-bottom:6px;">Chat ID&nbsp;&nbsp;${esc(chatCsv || '—')}</div>



                    <div style="font-size:0.72rem; color:var(--text-muted); font-family:var(--font-mono); margin-bottom:6px;">Host&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;${esc(g.host || '—')}</div>



                    <div style="display:flex; gap:6px; flex-wrap:wrap;">



                        <button class="btn-secondary tg-tok-copy" data-tgkey="${esc(key)}" style="padding:4px 10px; font-size:0.75rem;">Copy</button>



                        <button class="btn-secondary tg-tok-reveal" data-tgkey="${esc(key)}" style="padding:4px 10px; font-size:0.75rem;">Reveal</button>



                        ${g.source_url ? `<a class="btn-secondary" href="${esc(g.source_url)}" target="_blank" rel="noopener" style="padding:4px 10px; font-size:0.75rem; text-decoration:none;">Open Source</a>` : ''}



                        <button class="btn-secondary tg-tok-use" data-token="${esc(t.normalized_value)}" data-chat="${esc(chatCsv)}" style="padding:4px 10px; font-size:0.75rem;" title="Fill the Dump Messages form (no Telegram contact)">Use in Dump Messages</button>



                    </div>



                </div>`;



            });



            const others = (g.artifacts || []).filter(a => a.type !== 'bot_token');



            others.forEach(a => {



                const label = TG_KIND_LABEL[a.type] || (a.type || '').toUpperCase();



                html += `<div style="display:flex; gap:10px; font-size:0.78rem; margin-top:4px; flex-wrap:wrap;">



                    <span style="font-size:0.68rem; font-weight:700; letter-spacing:1px; color:var(--text-muted); min-width:96px;">${esc(label)}</span>



                    <span style="font-family:var(--font-mono); color:var(--text-main); overflow-wrap:anywhere;">${esc(a.type === 'bot_token' ? tgMask(a.observed_value) : (a.observed_value || a.normalized_value))}</span>



                </div>`;



            });



            if (g.host) html += `<div style="display:flex; gap:10px; font-size:0.78rem; margin-top:4px;"><span style="font-size:0.68rem; font-weight:700; letter-spacing:1px; color:var(--text-muted); min-width:96px;">HOST</span><span style="font-family:var(--font-mono); color:var(--text-main);">${esc(g.host)}</span></div>`;



            if (fams.length) html += `<div style="margin-top:6px; display:flex; gap:6px; flex-wrap:wrap;">${fams.map(f => `<span class="galaxy-chip" style="cursor:default;">${esc(f)}</span>`).join('')}</div>`;



            html += `</div>`;



        });



        if (!tgDiscGroups.length && !total) {



            html = `<div style="background: rgba(255,255,255,0.02); border: 1px dashed rgba(255,255,255,0.12); border-radius: 8px; padding: 22px; text-align: center;">



                <div style="font-weight:700; color:var(--text-main); margin-bottom:4px;">No discovery results yet</div>



                <div style="font-size:0.8rem; color:var(--text-muted);">Search existing intelligence sources for Telegram bot artifacts.</div>



            </div>`;



        }



        box.innerHTML = html;



    }







    async function tgValidateToken(value) {



        if (!value) {



            showNotification('Nothing to validate');



            return;



        }



        if (!window.confirm('ACTIVE OPERATION — validate this credential against Telegram (getMe)? Continue?')) return;



        try {



            const res = await fetch('/api/tg/artifacts/validate-direct', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ value })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(d.username ? `Token valid — @${d.username}` : 'Token valid');



        } catch (e) {



            showNotification(`Validation failed: ${e.message}`);



        }



    }







    function tgCopyToken(value, btn) {



        if (!value) return;



        const done = () => showNotification('Token copied to clipboard');



        if (navigator.clipboard && navigator.clipboard.writeText) {



            navigator.clipboard.writeText(value).then(done).catch(() => showNotification('Copy failed'));



        } else {



            showNotification('Clipboard unavailable');



        }



        if (btn) {



            const orig = btn.textContent;



            btn.textContent = 'Copied';



            setTimeout(() => { btn.textContent = orig; }, 1200);



        }



    }







    function tgUseInDumpMessages(token, chatId) {



        // Passive: fill the Dump Messages form. Telegram is NOT contacted.



        const nav = document.querySelector('.nav-item[data-tab="tg-invest"]');



        if (nav) nav.click();



        setTimeout(() => {



            const tokInput = document.getElementById('tg-bot-token');



            const chatInput = document.getElementById('tg-bot-chat');



            if (tokInput) tokInput.value = token || '';



            if (chatInput && chatId) chatInput.value = chatId;



            showNotification('Dump Messages form filled — review and Start Collection when ready (Telegram untouched)');



            if (tokInput) tokInput.scrollIntoView({ behavior: 'smooth', block: 'center' });



        }, 150);



    }







    async function tgValidateArtifact(group, index) {



        const art = ((tgDiscData[group] || [])[index]) || null;



        const raw = (art && art.value) || '';



        if (!raw) {



            showNotification('Artifact data expired — run discovery again');



            return;



        }



        if (!window.confirm('ACTIVE OPERATION — validate this credential against Telegram (getMe)? Continue?')) return;



        try {



            const res = await fetch('/api/tg/artifacts/validate-direct', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ value: raw })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(d.username ? `Token valid — @${d.username}` : 'Token valid');



        } catch (e) {



            showNotification(`Validation failed: ${e.message}`);



        }



    }







    async function tgAddArtifactToInvestigation(group, index) {



        if (!tgInvId) {



            showNotification('Select or create an investigation first (Dump Messages)');



            return;



        }



        const art = ((tgDiscData[group] || [])[index]) || null;



        if (!art || !art.value) {



            showNotification('Artifact data expired — run discovery again');



            return;



        }



        // Passive: populate the workspace. Telegram is NOT contacted.



        try {



            const res = await fetch('/api/tg/investigations/seed-artifact', {



                method: 'POST', headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ investigation_id: tgInvId, artifact: art })



            });



            const d = await res.json().catch(() => ({}));



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            showNotification(d.note || 'Added to investigation (not validated, Telegram untouched)');



        } catch (e) {



            showNotification(`Failed: ${e.message}`);



        }



    }







    async function tgLoadStream() {



        const box = document.getElementById('tg-stream-results');



        box.innerHTML = '<div style="color:var(--text-muted); padding:14px;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Aggregating Telegram intelligence…</div>';



        try {



            const res = await fetch(`/api/tg/stream?abusech_key=${encodeURIComponent(localStorage.getItem('ioc_abusech_key') || '')}&urlscan_key=${encodeURIComponent(localStorage.getItem('ioc_urlscan_key') || '')}&limit=30`);



            const d = await res.json();



            if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



            box.dataset.stream = JSON.stringify({ reports: d.reports || [], artifacts: d.artifacts || [], malware: d.malware || [] });



            tgRenderStream();



        } catch (e) {



            box.innerHTML = `<div class="empty-state"><i class="fa-solid fa-triangle-exclamation" style="color: var(--danger);"></i><p>Stream failed: ${esc(e.message)}</p></div>`;



        }



    }







    const TG_SIGNAL_LABEL = { 'api.telegram.org': 'Telegram API', 'telegram bot api': 'Telegram API', 'bot token': 'Bot Token', 'chat_id': 'Chat ID', 'sendmessage': 'sendMessage', 'senddocument': 'sendDocument', 'sendphoto': 'sendPhoto' };







    function tgRenderStream() {



        const box = document.getElementById('tg-stream-results');



        let d = { reports: [], artifacts: [], malware: [] };



        try { d = { ...d, ...JSON.parse(box.dataset.stream || '{}') }; } catch (_) { /* keep empty */ }



        document.querySelectorAll('[data-tgstream]').forEach(b => b.classList.toggle('active', b.dataset.tgstream === tgStreamFilter));



        let html = '';



        const show = (k) => tgStreamFilter === 'all' || tgStreamFilter === k;



        if (show('reports')) {



            html += `<div style="font-weight:700; color:var(--text-main); margin:6px 0;">CTI Reports (${(d.reports || []).length})</div>`;



            html += (d.reports || []).slice(0, 30).map(r => {



                const sigs = r.signals && r.signals.length ? r.signals : (r.matched_signal ? [r.matched_signal] : []);



                return `



                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 8px; padding: 12px 14px; margin-bottom: 8px;">



                    <div style="display:flex; justify-content:space-between; gap:10px; align-items:center; margin-bottom:2px;">



                        <span style="font-size:0.68rem; font-weight:700; letter-spacing:1px; color:var(--text-muted);">CTI REPORT</span>



                        <span style="font-size:0.75rem; color:var(--accent); font-weight:600;">${esc(r.source || '')}</span>



                    </div>



                    <div style="font-weight:700; font-size:0.95rem; color:var(--text-main); overflow-wrap:anywhere; margin-bottom:2px;">${esc(r.title || 'Untitled')}</div>



                    <div style="font-size:0.72rem; color:var(--text-muted); margin-bottom:8px;">${esc((r.published || '').slice(0, 10))}</div>



                    <div style="font-size:0.68rem; font-weight:700; letter-spacing:1px; color:var(--text-muted); margin-bottom:4px;">SIGNALS</div>



                    <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:10px;">${sigs.map(s => `<span class="galaxy-chip" style="cursor:default;">${esc(TG_SIGNAL_LABEL[(s || '').toLowerCase()] || s)}</span>`).join('')}</div>



                    <div style="display:flex; gap:8px; flex-wrap:wrap;">



                        <button class="cti-open-article btn-secondary" data-article-id="${esc(String(r.article_id))}" style="padding:4px 10px; font-size:0.75rem;">Open Article</button>



                        <a href="#" class="pivot-link btn-secondary" data-type="keyword" data-indicator="${esc(r.title || '')}" style="padding:4px 10px; font-size:0.75rem; text-decoration:none;">Keyword Lookup</a>



                    </div>



                </div>`;



            }).join('') || `<div class="hash-intel-empty">No Telegram-signal reports collected yet.</div>`;



        }



        if (show('artifacts')) {



            html += `<div style="font-weight:700; color: var(--text-main); margin:6px 0;">Artifacts (${(d.artifacts || []).length})</div>`;



            html += (d.artifacts || []).slice(0, 30).map((a, i) => `



                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 10px 12px; margin-bottom: 8px; font-size:0.8rem;">



                    <div style="display:flex; justify-content:space-between; gap:10px; align-items:center;">



                        <span style="font-size:0.7rem; font-weight:700; letter-spacing:1px; color:var(--accent);">${esc((a.kind || '').toUpperCase().replace('_', ' '))}</span>



                        <span style="font-size:0.72rem; color:var(--text-muted);">${esc(a.source || '')} · obs ${esc((a.first_seen || '').slice(0, 10))} → ${esc((a.last_seen || '').slice(0, 10))}</span>



                    </div>



                    <div class="tg-tok" data-tgkey="stream:${i}" data-full="${esc(a.value || '')}" data-masked="1" style="font-family:var(--font-mono); overflow-wrap:anywhere; margin:6px 0;">${esc(tgMask(a.observed_value || a.value))}</div>



                    <div style="display:flex; gap:6px; flex-wrap:wrap;">



                        <button class="btn-secondary tg-tok-reveal" data-tgkey="stream:${i}" style="padding:4px 10px; font-size:0.75rem;">Reveal</button>



                        <button class="btn-secondary tg-tok-copy" data-tgkey="stream:${i}" style="padding:4px 10px; font-size:0.75rem;">Copy</button>



                        ${a.link ? `<a class="btn-secondary" href="${esc(a.link)}" target="_blank" rel="noopener" style="padding:4px 10px; font-size:0.75rem; text-decoration:none;">Open Source</a>` : ''}



                        ${(a.kind === 'bot_token') ? `<button class="btn-secondary tg-tok-use" data-token="${esc(a.value || '')}" data-chat="" style="padding:4px 10px; font-size:0.75rem;" title="Fill the Dump Messages form (no Telegram contact)">Use in Dump Messages</button>` : ''}



                    </div>



                </div>`).join('') || `<div class="hash-intel-empty">No stored artifacts. Run Find Bots discovery first.</div>`;



        }



        if (show('malware')) {



            html += `<div style="font-weight:700; color: var(--text-main); margin:6px 0;">Malware (${(d.malware || []).length})</div>`;



            html += (d.malware || []).slice(0, 30).map(s => `



                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 10px 12px; margin-bottom: 8px; font-size:0.8rem;">



                    <div style="font-weight:600; color:var(--text-main);">${esc(s.signature || s.file_name || 'Unknown family')}</div>



                    <div style="font-family:var(--font-mono); font-size:0.75rem; color:var(--text-muted); overflow-wrap:anywhere; margin:4px 0;">${esc(s.sha256 || '')}</div>



                    <div style="color:var(--text-muted); font-size:0.75rem;">${esc(s.file_name || '')} · first seen ${esc((s.first_seen || '').slice(0, 10))} · Telegram evidence: matched <span style="font-family:var(--font-mono);">telegram_bot_api</span> YARA rule</div>



                    <div style="margin-top:8px; display:flex; gap:6px; flex-wrap:wrap;">



                        <a href="#" class="pivot-link btn-secondary" data-type="hash" data-indicator="${esc(s.sha256 || '')}" style="padding:4px 10px; font-size:0.75rem; text-decoration:none;">Hash Lookup</a>



                        <a class="btn-secondary" href="https://bazaar.abuse.ch/sample/${esc(s.sha256 || '')}/" target="_blank" rel="noopener" style="padding:4px 10px; font-size:0.75rem; text-decoration:none;">Open Source</a>



                    </div>



                </div>`).join('') || `<div class="hash-intel-empty">No recent telegram_bot_api samples (needs Abuse.ch key).</div>`;



        }



        box.innerHTML = html;



    }







    function tgShowView(view) {



        if (view !== 'tg-invest' && view !== 'tg-info' && view !== 'tg-channel-mon' && view !== 'tg-auth-settings') view = 'tg-channel-mon';



        tgView = view;



        const monView = document.getElementById('tg-channel-mon-view');



        const authSettingsView = document.getElementById('tg-auth-settings-view');



        const investView = document.getElementById('tg-invest-view');



        const infoView = document.getElementById('tg-info-view');



        const explorerContainer = document.getElementById('tg-explorer-container');







        // Hide all views



        [monView, authSettingsView, investView, infoView].forEach(el => {



            if (el) {



                el.style.display = 'none';



                el.classList.remove('tg-toolkit-visible');



            }



        });







        // Show the active view



        const activeView = {



            'tg-channel-mon': monView,



            'tg-auth-settings': authSettingsView,



            'tg-invest': investView,



            'tg-info': infoView



        }[view];







        if (activeView) {



            activeView.style.removeProperty('display');



            activeView.classList.add('tg-toolkit-visible');



        }







        // Explorer container: visible only in dump messages view



        const nativeMode = document.getElementById('tg-global-mode-a')?.checked !== false;
        if (explorerContainer) explorerContainer.style.display = view === 'tg-invest' && nativeMode ? '' : 'none';







        if (view === 'tg-invest') { tgLoadBots(); tgLoadMessages(true); }



        if (view === 'tg-channel-mon') { tgLoadMonitorStats(); tgLoadLiveFeed(); }



        if (view === 'tg-auth-settings') {



            if (typeof window.checkAuthStatus === 'function') window.checkAuthStatus();



        }



    }







    async function openTg(tab) {



        document.getElementById('tg-pane').style.display = 'flex';



        if (!tgBound) {



            tgBound = true;







            // --- Telegram Channel Monitoring Event Listeners ---



            document.querySelectorAll('#tg-channel-mon-section .tg-mon-tab-btn').forEach(btn => {



                btn.addEventListener('click', () => {



                    document.querySelectorAll('#tg-channel-mon-section .tg-mon-tab-btn').forEach(b => b.classList.remove('active'));



                    document.querySelectorAll('.tg-subtab-content').forEach(c => c.style.display = 'none');



                    btn.classList.add('active');



                    const tabKey = btn.dataset.tgtab;



                    const contentEl = document.getElementById(`tg-subtab-${tabKey}`);



                    if (contentEl) contentEl.style.display = 'block';







                    if (tabKey === 'live-feed') tgLoadLiveFeed();



                    else if (tabKey === 'channels') tgLoadMonitoredChannels();



                    else if (tabKey === 'exposures') tgLoadExposures();



                    else if (tabKey === 'targets') tgLoadTargets();



                });



            });







            document.getElementById('tg-add-chan-btn')?.addEventListener('click', tgAddMonitoredChannel);



            document.getElementById('tg-target-add-btn')?.addEventListener('click', tgAddTargetAsset);



            document.getElementById('tg-disc-chan-btn')?.addEventListener('click', tgDiscoverChannelRecommendations);



            document.getElementById('tg-feed-refresh')?.addEventListener('click', async () => {



                await tgSyncAllChannels();



                tgLoadLiveFeed();



                tgLoadMonitorStats();



            });



            document.getElementById('tg-feed-cat-filter')?.addEventListener('change', () => tgLoadLiveFeed(1));



            document.getElementById('tg-feed-view-card')?.addEventListener('click', () => setTgFeedViewMode('card'));



            document.getElementById('tg-feed-view-list')?.addEventListener('click', () => setTgFeedViewMode('list'));



            document.getElementById('tg-exp-search-btn')?.addEventListener('click', tgLoadExposures);







            // Initial load for Channel Monitor



            setTgFeedViewMode(tgFeedViewMode);



            tgLoadMonitorStats();



            tgLoadLiveFeed();







            // Background Polling for true Live Feed (every 30s)



            setInterval(async () => {



                const subtab = document.getElementById('tg-subtab-live-feed');



                if (subtab && subtab.style.display !== 'none' && !tgIsSyncingAll) {



                    await tgSyncAllChannels();



                    tgLoadLiveFeed();



                    tgLoadMonitorStats();



                }



            }, 30000);







            document.getElementById('tg-bot-add').addEventListener('click', async (e) => {



                const btn = e.target.closest('button');



                const origHtml = btn.innerHTML;



                const token = document.getElementById('tg-bot-token').value.trim();



                if (!token) return showNotification("Bot token is required");



                const mode = document.getElementById('tg-bot-mode').value;



                const opchat = document.getElementById('tg-bot-chat').value.trim();



                const dstchat = document.getElementById('tg-bot-dstchat').value.trim();

                const transport = document.getElementById('tg-global-mode-b')?.checked ? 'manual' : 'native';

                if (transport === 'manual' && (!opchat || !dstchat)) {
                    return showNotification('Manual mode requires operator and destination chat IDs');
                }







                btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Adding...';



                btn.disabled = true;



                btn.style.opacity = '0.7';







                try {



                    const res = await fetch('/api/tg/bots', {



                        method: 'POST',



                        headers: { 'Content-Type': 'application/json' },



                        body: JSON.stringify({ token, chat_id: opchat, dest_chat_id: dstchat, mode, transport })



                    });



                    const d = await res.json();



                    if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



                    document.getElementById('tg-bot-token').value = '';



                    document.getElementById('tg-bot-chat').value = '';



                    document.getElementById('tg-bot-dstchat').value = '';



                    tgLoadBots();



                } catch (e) {



                    showNotification(`Error adding bot: ${e.message}`);



                } finally {



                    btn.innerHTML = origHtml;



                    btn.disabled = false;



                    btn.style.opacity = '';



                }



            });











            document.getElementById('tg-msg-search').addEventListener('click', () => tgLoadMessages(true));



            document.getElementById('tg-msg-more').addEventListener('click', () => tgLoadMessages(false));







            // Auto-refresh: poll every 5 s while any bot is RUNNING so the



            // message count, dump progress and new messages update automatically.



            let _tgRefreshTimer = null;



            const _tgAutoRefresh = async () => {



                try {



                    const r = await fetch('/api/tg/bots');



                    const d = await r.json();



                    const anyRunning = (d.bots || []).some(b => b.job_running);



                    tgRenderBots(d.bots || []);



                    const banner = document.getElementById('tg-active-banner');



                    if (banner) banner.style.display = anyRunning ? '' : 'none';



                    if (anyRunning) {



                        // Also refresh messages silently (preserve scroll position)



                        tgLoadMessages(true);



                        _tgRefreshTimer = setTimeout(_tgAutoRefresh, 5000);



                    } else {



                        _tgRefreshTimer = null;



                    }



                } catch (e) {



                    _tgRefreshTimer = null;



                }



            };



            // Kick off auto-refresh whenever Start Collection is clicked



            window._tgStartAutoRefresh = () => {



                if (!_tgRefreshTimer) {



                    _tgRefreshTimer = setTimeout(_tgAutoRefresh, 3000);



                }



            };











            // Global Mode toggle handlers



            const tgToggleMode = () => {



                const modeA = document.getElementById('tg-global-mode-a').checked;



                const lblA = document.getElementById('lbl-mode-a');



                const lblB = document.getElementById('lbl-mode-b');



                if (lblA) lblA.classList.toggle('active', modeA);



                if (lblB) lblB.classList.toggle('active', !modeA);



                // tg-auth-container is now in the dedicated Telegram Auth Settings page — no toggle needed here



                document.getElementById('tg-explorer-container').style.display = modeA ? '' : 'none';



                document.getElementById('tg-bot-dstchat').style.display = modeA ? 'none' : 'block';



                const instructions = document.getElementById('tg-mode-b-instructions');



                if (instructions) instructions.style.display = modeA ? 'none' : 'block';



                const viewMsgBtns = document.querySelectorAll('button[data-tg-bot-action="messages"]');



                viewMsgBtns.forEach(btn => {



                    btn.style.display = modeA ? '' : 'none';



                });



            };



            // attach global function so tgRenderBots can call it



            window.tgToggleMode = tgToggleMode;







            document.getElementById('tg-global-mode-a').addEventListener('change', tgToggleMode);



            document.getElementById('tg-global-mode-b').addEventListener('change', tgToggleMode);



            tgToggleMode();







            // MTProto Auth handlers



            const checkAuthStatus = async () => {



                try {



                    const res = await fetch('/api/tg/auth/status');



                    const d = await res.json();



                    if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



                    const status = document.getElementById('tg-auth-status');



                    if (d.authenticated) {



                        status.innerHTML = `



                            <div style="display: flex; align-items: center; justify-content: space-between; width: 100%;">



                                <span style="color:var(--success);"><i class="fa-solid fa-check"></i> Telegram session configured</span>



                                <div style="display: flex; gap: 8px;">



                                    <button class="btn-secondary" id="tg-auth-verify" style="padding: 4px 10px; font-size: 0.75rem;"><i class="fa-solid fa-plug-circle-check"></i> Test Connection</button>



                                    <button class="btn-secondary" id="tg-auth-reset" style="padding: 4px 10px; font-size: 0.75rem; color: var(--danger); border-color: rgba(220,53,69,0.3);"><i class="fa-solid fa-right-from-bracket"></i> Log Out</button>



                                </div>



                            </div>`;



                        document.getElementById('tg-auth-step1').style.display = 'none';



                        document.getElementById('tg-auth-step2').style.display = 'none';







                        document.getElementById('tg-auth-verify').addEventListener('click', async (e) => {



                            const btn = e.target.closest('button');



                            const orig = btn.innerHTML;



                            btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i>';



                            btn.disabled = true;



                            try {



                                const r = await fetch('/api/tg/auth/verify');



                                const vd = await r.json();



                                if (!r.ok) throw new Error(vd.detail || `HTTP ${r.status}`);



                                showNotification(`Success! Connected as ${vd.name} (@${vd.username})`);



                            } catch (err) {



                                showNotification(`Verification failed: ${err.message}`);



                            } finally {



                                btn.innerHTML = orig;



                                btn.disabled = false;



                            }



                        });







                        document.getElementById('tg-auth-reset').addEventListener('click', async (e) => {



                            if (!confirm("Are you sure you want to remove MTProto authentication? You will need to log in again.")) return;



                            const btn = e.target.closest('button');



                            btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i>';



                            btn.disabled = true;



                            try {



                                const response = await fetch('/api/tg/auth/logout', { method: 'POST' });



                                const data = await response.json().catch(() => ({}));



                                if (!response.ok) throw new Error(data.detail || `HTTP ${response.status}`);



                                showNotification("Authentication reset.");



                                checkAuthStatus();



                            } catch (err) {



                                showNotification(`Reset failed: ${err.message}`);



                                btn.innerHTML = '<i class="fa-solid fa-right-from-bracket"></i> Log Out';



                                btn.disabled = false;



                            }



                        });



                    } else {



                        status.innerHTML = '<span style="color:var(--danger);"><i class="fa-solid fa-xmark"></i> Not authenticated. Please login.</span>';



                        document.getElementById('tg-auth-step1').style.display = 'flex';



                        document.getElementById('tg-auth-step2').style.display = 'none';



                    }



                } catch (e) {
                    const status = document.getElementById('tg-auth-status');
                    status.innerHTML = `<span style="color:var(--danger);"><i class="fa-solid fa-xmark"></i> Status check failed: ${esc(e.message)}</span>`;
                }



            };



            window.checkAuthStatus = checkAuthStatus;







            document.getElementById('tg-auth-send').addEventListener('click', async () => {



                const api_id = parseInt(document.getElementById('tg-auth-api-id').value);



                const api_hash = document.getElementById('tg-auth-api-hash').value.trim();



                const phone = document.getElementById('tg-auth-phone').value.trim();



                if (!api_id || !api_hash || !phone) return showNotification("All step 1 fields required");







                const btn = document.getElementById('tg-auth-send');



                const origHtml = btn.innerHTML;



                btn.disabled = true;



                btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Sending code…';



                btn.style.opacity = '0.7';







                // Also show a status pulse in the auth status box



                const statusEl = document.getElementById('tg-auth-status');



                const prevStatus = statusEl.innerHTML;



                statusEl.innerHTML = '<span style="color:var(--text-muted);"><i class="fa-solid fa-circle-notch mantis-spin"></i> Contacting Telegram — this may take a few seconds…</span>';







                try {



                    const res = await fetch('/api/tg/auth/send_code', {



                        method: 'POST',



                        headers: { 'Content-Type': 'application/json' },



                        body: JSON.stringify({ api_id, api_hash, phone })



                    });



                    const d = await res.json();



                    if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



                    window.tgAuthAttemptId = d.attempt_id;



                    window.tgAuthNeedsPassword = false;



                    statusEl.innerHTML = '<span style="color:var(--success);"><i class="fa-solid fa-check"></i> Code sent! Check your Telegram app.</span>';



                    document.getElementById('tg-auth-step1').style.display = 'none';



                    document.getElementById('tg-auth-step2').style.display = 'flex';



                    showNotification("Code sent to Telegram app!");



                    btn.disabled = false;



                    btn.innerHTML = origHtml;



                    btn.style.opacity = '';



                } catch (e) {



                    statusEl.innerHTML = `<span style="color:var(--danger);"><i class="fa-solid fa-xmark"></i> Failed: ${esc(e.message)}</span>`;



                    showNotification(`Send code failed: ${e.message}`);



                    btn.disabled = false;



                    btn.innerHTML = origHtml;



                    btn.style.opacity = '';



                }



            });







            document.getElementById('tg-auth-login').addEventListener('click', async () => {



                const code = document.getElementById('tg-auth-code').value.trim();



                const password = document.getElementById('tg-auth-password').value.trim();



                if (!code && !window.tgAuthNeedsPassword) return showNotification("Code required");







                const btn = document.getElementById('tg-auth-login');



                const origHtml = btn.innerHTML;



                btn.disabled = true;



                btn.innerHTML = '<i class="fa-solid fa-circle-notch mantis-spin"></i> Logging in…';



                btn.style.opacity = '0.7';







                const statusEl = document.getElementById('tg-auth-status');



                statusEl.innerHTML = '<span style="color:var(--text-muted);"><i class="fa-solid fa-circle-notch mantis-spin"></i> Verifying login code…</span>';







                try {



                    const res = await fetch('/api/tg/auth/login', {



                        method: 'POST',



                        headers: { 'Content-Type': 'application/json' },



                        body: JSON.stringify({ attempt_id: window.tgAuthAttemptId || '', code, password })



                    });



                    const d = await res.json();



                    if (!res.ok) throw new Error(d.detail || `HTTP ${res.status}`);



                    if (d.password_required) {
                        window.tgAuthNeedsPassword = true;
                        statusEl.innerHTML = '<span style="color:var(--warning);"><i class="fa-solid fa-lock"></i> Two-factor authentication is enabled. Enter your 2FA password and click Login again.</span>';
                        showNotification("Two-factor password required");
                        btn.disabled = false;
                        btn.innerHTML = origHtml;
                        btn.style.opacity = '';
                        return;
                    }



                    showNotification("Login successful! Session saved to .env");



                    window.tgAuthAttemptId = '';



                    window.tgAuthNeedsPassword = false;



                    document.getElementById('tg-auth-code').value = '';



                    document.getElementById('tg-auth-password').value = '';



                    btn.disabled = false;



                    btn.innerHTML = origHtml;



                    btn.style.opacity = '';



                    checkAuthStatus();



                } catch (e) {



                    statusEl.innerHTML = `<span style="color:var(--danger);"><i class="fa-solid fa-xmark"></i> Login failed: ${esc(e.message)}</span>`;



                    showNotification(`Login failed: ${e.message}`);



                    btn.disabled = false;



                    btn.innerHTML = origHtml;



                    btn.style.opacity = '';



                }



            });











            checkAuthStatus();







            document.getElementById('tg-info-get').addEventListener('click', async () => {



                const token = document.getElementById('tg-info-token').value.trim();



                const resultsDiv = document.getElementById('tg-info-results');



                if (!token) {



                    resultsDiv.innerHTML = '<div class="error-card"><i class="fa-solid fa-triangle-exclamation"></i> Please enter a bot token.</div>';



                    return;



                }







                resultsDiv.innerHTML = '<div style="color:var(--text-muted); font-size:0.9rem;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Fetching bot info...</div>';



                try {



                    const res = await fetch('/api/tg/info', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ token })
                    });



                    const data = await res.json();



                    if (!res.ok) {
                        throw new Error(data.detail || `HTTP ${res.status}`);
                    }







                    if (!data.ok) {



                        resultsDiv.innerHTML = `<div class="error-card"><i class="fa-solid fa-triangle-exclamation"></i> Error: ${esc(data.description || 'Failed to fetch bot info')}</div>`;



                        return;



                    }







                    const b = data.result;



                    document.getElementById('tg-info-token').value = '';



                    const propsHtml = Object.entries(b).map(([k, v]) => {



                        const isBool = typeof v === 'boolean';



                        let valHtml = '';



                        if (isBool) {



                            valHtml = v ? '<span style="color:var(--success);"><i class="fa-solid fa-check"></i> True</span>' : '<span style="color:var(--danger);"><i class="fa-solid fa-xmark"></i> False</span>';



                        } else {



                            valHtml = `<span style="color:var(--text-main);">${esc(String(v))}</span>`;



                        }



                        return `<div style="display:flex; justify-content:space-between; padding:8px; border-bottom:1px solid rgba(255,255,255,0.05); font-size:0.85rem;">



                            <span style="color:var(--text-muted); font-family:var(--font-mono);">${esc(k)}</span>



                            ${valHtml}



                        </div>`;



                    }).join('');







                    resultsDiv.innerHTML = `



                        <div style="background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.08); border-radius:8px; padding:16px;">



                            <div style="display:flex; align-items:center; gap:12px; margin-bottom:16px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:12px;">



                                <div style="width:40px; height:40px; border-radius:50%; background:var(--accent); display:flex; align-items:center; justify-content:center; color:white; font-size:1.2rem;">



                                    <i class="fa-solid fa-robot"></i>



                                </div>



                                <div>



                                    <div style="font-size:1.1rem; font-weight:700; color:var(--text-main);">${esc(b.first_name || 'Bot')}</div>



                                    <div style="font-size:0.85rem; color:var(--accent); font-family:var(--font-mono);">@${esc(b.username || 'unknown')}</div>



                                </div>



                            </div>



                            <div style="display:flex; flex-direction:column;">



                                ${propsHtml}



                            </div>



                        </div>



                    `;



                } catch (err) {



                    resultsDiv.innerHTML = `<div class="error-card"><i class="fa-solid fa-triangle-exclamation"></i> Unable to fetch bot info: ${esc(err.message)}</div>`;



                }



            });



            document.getElementById('tg-info-token').addEventListener('keydown', (e) => {



                if (e.key === 'Enter') document.getElementById('tg-info-get').click();



            });



            document.addEventListener('click', (e) => {



                const act = e.target.closest('[data-tg-bot-action]');



                if (act) {



                    e.preventDefault();



                    tgBotAction(act.dataset.botId, act.dataset.tgBotAction);



                    return;



                }



                if (e.target.closest('.tg-tok-reveal')) {



                    e.preventDefault();



                    const btn = e.target.closest('.tg-tok-reveal');



                    const row = document.querySelector(`.tg-tok[data-tgkey="${CSS.escape(btn.dataset.tgkey || '')}"]`);



                    if (row) {



                        const masked = row.dataset.masked === '1';



                        row.textContent = masked ? (row.dataset.full || '') : tgMask(row.dataset.full || '');



                        row.dataset.masked = masked ? '0' : '1';



                        btn.textContent = masked ? 'Hide' : 'Reveal';



                    }



                    return;



                }



                if (e.target.closest('.tg-tok-copy')) {



                    e.preventDefault();



                    const btn = e.target.closest('.tg-tok-copy');



                    const row = document.querySelector(`.tg-tok[data-tgkey="${CSS.escape(btn.dataset.tgkey || '')}"]`);



                    tgCopyToken(row ? row.dataset.full : '', btn);



                    return;



                }



                if (e.target.closest('.tg-tok-use')) {



                    e.preventDefault();



                    const btn = e.target.closest('.tg-tok-use');



                    tgUseInDumpMessages(btn.dataset.token || '', btn.dataset.chat || '');



                    return;



                }



                if (e.target.closest('.tg-art-validate')) {



                    e.preventDefault();



                    const [group, index] = (e.target.closest('.tg-art-validate').dataset.artKey || ':').split(':');



                    tgValidateArtifact(group, parseInt(index || '0', 10));



                    return;



                }



                if (e.target.closest('.tg-art-add')) {



                    e.preventDefault();



                    const [group, index] = (e.target.closest('.tg-art-add').dataset.artKey || ':').split(':');



                    tgAddArtifactToInvestigation(group, parseInt(index || '0', 10));



                }



            });



        }



        tgShowView(tab || 'tg-invest');



    }







    // ---------------- History Lookups (IndexedDB) ----------------



    let historyActiveTab = 'hash';



    const DB_NAME = 'MantisHistoryDB';



    const DB_VERSION = 1;



    let mantisDB = null;







    function initHistoryDB() {



        return new Promise((resolve, reject) => {



            if (mantisDB) return resolve(mantisDB);



            const request = indexedDB.open(DB_NAME, DB_VERSION);



            request.onerror = (e) => reject(e.target.error);



            request.onsuccess = (e) => {



                mantisDB = e.target.result;



                resolve(mantisDB);



            };



            request.onupgradeneeded = (e) => {



                const db = e.target.result;



                if (!db.objectStoreNames.contains('history')) {



                    const store = db.createObjectStore('history', { keyPath: 'id', autoIncrement: true });



                    store.createIndex('type', 'type', { unique: false });



                    store.createIndex('t', 't', { unique: false });



                }



            };



        });



    }







    async function getHistory(type) {



        await initHistoryDB();



        return new Promise((resolve, reject) => {



            const tx = mantisDB.transaction(['history'], 'readonly');



            const store = tx.objectStore('history');



            const index = store.index('type');



            const req = index.getAll(IDBKeyRange.only(type));



            req.onsuccess = (e) => {



                const records = e.target.result || [];



                records.sort((a, b) => b.t - a.t);



                resolve(records);



            };



            req.onerror = (e) => reject(e.target.error);



        });



    }







    async function saveHistory(type, queryStr, dataObj) {



        if (!['hash', 'domain', 'ip', 'url', 'keyword', 'infra'].includes(type)) return;







        // Deep copy dataObj to avoid storing non-clonable elements or DOM references if any exist



        // (Though intelligence results are pure JSON)



        let cleanData;



        try {



            cleanData = JSON.parse(JSON.stringify(dataObj));



        } catch (e) {



            console.error("Could not clone history data", e);



            return;



        }







        await initHistoryDB();



        return new Promise((resolve, reject) => {



            const tx = mantisDB.transaction(['history'], 'readwrite');



            const store = tx.objectStore('history');







            const idx = store.index('type');



            const req = idx.getAll(IDBKeyRange.only(type));



            req.onsuccess = (e) => {



                let records = e.target.result || [];







                const dupes = records.filter(r => r.q === queryStr);



                dupes.forEach(d => store.delete(d.id));







                store.add({ type: type, q: queryStr, t: Date.now(), data: cleanData });







                records = records.filter(r => r.q !== queryStr);



                records.push({ type: type, q: queryStr, t: Date.now(), data: cleanData }); // placeholder for counting



                records.sort((a, b) => b.t - a.t);



                if (records.length > 10) {



                    const toDelete = records.slice(10);



                    toDelete.forEach(d => {



                        if (d.id) store.delete(d.id);



                    });



                }



            };



            tx.oncomplete = () => resolve();



            tx.onerror = (e) => reject(e.target.error);



        });



    }



    window.saveHistory = saveHistory; // export for performSearch







    function openHistoryPane() {



        document.querySelectorAll('#history-subtabs .galaxy-subtab').forEach(b => {



            b.classList.toggle('active', b.dataset.histtype === historyActiveTab);



        });



        renderHistoryGrid();



    }



    window.openHistoryPane = openHistoryPane;







    async function renderHistoryGrid() {



        const grid = document.getElementById('history-grid');



        grid.innerHTML = '<div style="grid-column: 1 / -1; padding: 24px; color: var(--text-muted); text-align: center;"><i class="fa-solid fa-circle-notch mantis-spin"></i> Loading...</div>';







        if (historyActiveTab === 'ai_reports') {



            try {



                const res = await fetch(`${API_BASE}/api/ai/reports`);



                const data = await res.json();



                const reports = data.reports || [];



                if (reports.length === 0) {



                    grid.innerHTML = `<div style="grid-column: 1 / -1; color: var(--text-muted); text-align: center; padding: 40px;"><i class="fa-solid fa-file-shield" style="font-size: 3rem; margin-bottom: 10px; opacity: 0.5;"></i><br>No delivered AI Reports found yet.<br><small style="margin-top:6px; display:inline-block;">Click the ✨ AI button during any IOC lookup to generate one!</small></div>`;



                    return;



                }



                grid.innerHTML = reports.map((item) => `



                    <div class="galaxy-card" style="padding: 16px 20px; display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 15px; background: rgba(0,0,0,0.25); border: 1px solid var(--border); border-radius: 8px;">



                        <div style="display: flex; flex-direction: column; gap: 6px; overflow: hidden; flex: 1; min-width: 0;">



                            <div style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">



                                <span style="font-size: 1.05rem; font-weight: bold; color: #fff; font-family: var(--font-mono);">${esc(item.target || item.case_id)}</span>



                                <span class="phase-tag" style="background:rgba(255,204,0,0.15); color:var(--accent); font-size:11px;">${esc(item.verdict)}</span>



                            </div>



                            <div style="font-size: 0.75rem; color: var(--text-muted); display: flex; gap: 14px; flex-wrap: wrap;">



                                <span><i class="fa-solid fa-clock"></i> ${new Date(item.created_at).toLocaleString()}</span>



                                <span><i class="fa-solid fa-hard-drive"></i> ${(item.size_bytes / 1024).toFixed(1)} KB</span>



                                <span class="mono-sm">Case: ${esc(item.case_id)}</span>



                            </div>



                        </div>



                        <div style="display: flex; gap: 8px; flex-shrink: 0; align-items: center;">



                            <button class="btn-primary hist-view-ai-report" data-url="${item.url}" data-case="${item.case_id}" data-target="${esc(item.target)}" title="Read interactive report modal" style="font-size: 0.82rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;"><i class="fa-solid fa-book-open"></i> Read</button>



                            <a class="btn-secondary" href="${API_BASE}${item.url}" target="_blank" title="Open report in new browser tab" style="font-size: 0.82rem; padding: 7px 12px; border-radius: 6px; text-decoration: none; display: inline-flex; align-items: center;"><i class="fa-solid fa-up-right-from-square"></i></a>



                            <button class="btn-secondary hist-del-ai-report" data-fname="${item.filename}" title="Delete report" style="font-size: 0.82rem; padding: 7px 12px; border-radius: 6px; color: var(--danger); cursor: pointer;"><i class="fa-solid fa-trash"></i></button>



                        </div>



                    </div>



                `).join('');







                grid.querySelectorAll('.hist-view-ai-report').forEach(b => {



                    b.addEventListener('click', async () => {



                        try {



                            const resp = await fetch(`${API_BASE}${b.dataset.url}`);



                            if (!resp.ok) {



                                throw new Error(`HTTP ${resp.status}`);



                            }



                            const html = await resp.text();



                            if (typeof window.mantisAI?.showReportViewerModal === 'function') {



                                window.mantisAI.showReportViewerModal(b.dataset.case, html, b.dataset.url.split('/').pop(), b.dataset.target);



                            } else {



                                window.open(`${API_BASE}${b.dataset.url}`, '_blank');



                            }



                        } catch (err) {



                            if (typeof showNotification === 'function') showNotification('Failed to load report: ' + err.message);



                        }



                    });



                });







                grid.querySelectorAll('.hist-del-ai-report').forEach(b => {



                    b.addEventListener('click', async () => {



                        if (!confirm(`Delete report ${b.dataset.fname}?`)) return;



                        try {



                            const res = await fetch(`${API_BASE}/api/ai/reports/${encodeURIComponent(b.dataset.fname)}`, { method: 'DELETE' });



                            if (!res.ok) {



                                throw new Error(`HTTP ${res.status}`);



                            }



                            if (typeof showNotification === 'function') showNotification('Report deleted');



                            renderHistoryGrid();



                        } catch (err) {



                            if (typeof showNotification === 'function') showNotification('Failed to delete report: ' + err.message);



                        }



                    });



                });



                return;



            } catch (e) {



                grid.innerHTML = `<div style="grid-column: 1 / -1; color: var(--danger); text-align: center; padding: 30px;">Failed to load AI reports: ${esc(e.message)}</div>`;



                return;



            }



        }







        let items = [];



        try {



            items = await getHistory(historyActiveTab);



        } catch (e) {



            console.error("Failed to load history", e);



        }







        if (items.length === 0) {



            grid.innerHTML = `<div style="grid-column: 1 / -1; color: var(--text-muted); text-align: center; padding: 40px;"><i class="fa-solid fa-clock-rotate-left" style="font-size: 3rem; margin-bottom: 10px; opacity: 0.5;"></i><br>No history for ${historyActiveTab.toUpperCase()} yet.</div>`;



            return;



        }







        grid.innerHTML = items.map((item, idx) => `



            <div class="galaxy-card" style="padding: 15px 20px; display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 15px; background: rgba(0,0,0,0.2); border: 1px solid var(--border); border-radius: 8px;">



                <div style="display: flex; flex-direction: column; gap: 4px; overflow: hidden; flex: 1; min-width: 0;">



                    <div style="font-size: 1.1rem; font-weight: bold; color: var(--text-main); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-family: var(--font-mono);">${esc(item.q)}</div>



                    <div style="font-size: 0.75rem; color: var(--text-muted);"><i class="fa-solid fa-clock" style="margin-right: 4px;"></i>${new Date(item.t).toLocaleString()}</div>



                </div>



                <div style="display: flex; gap: 8px; flex-shrink: 0; align-items: center;">



                    <button class="btn-secondary hist-rerun" data-idx="${idx}" title="View cached results without re-querying" style="font-size: 0.82rem; padding: 7px 14px; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; color: var(--text-muted); cursor: pointer; transition: all 0.2s; white-space: nowrap;"><i class="fa-solid fa-eye"></i> View</button>



                    <button class="btn-primary hist-relookup" data-idx="${idx}" title="Re-run a fresh live lookup with current sources &amp; API keys" style="font-size: 0.82rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; transition: all 0.2s; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px;"><i class="fa-solid fa-rotate-right"></i> Re-lookup</button>



                </div>



            </div>



        `).join('');







        // View Results — load cached data without re-querying



        grid.querySelectorAll('.hist-rerun').forEach(btn => {



            btn.addEventListener('click', (e) => {



                const item = items[parseInt(btn.dataset.idx)];



                const _IOC_HIST_TYPES = ['hash', 'domain', 'ip', 'url', 'keyword'];



                if (_IOC_HIST_TYPES.includes(historyActiveTab) && typeof switchToIocSearch === 'function') {



                    switchToIocSearch(historyActiveTab);



                } else {



                    const tabBtn = document.querySelector(`.nav-item[data-tab="${historyActiveTab}"]`);



                    if (tabBtn) tabBtn.click();



                }



                setTimeout(() => {



                    const iocInput = document.getElementById('ioc-input');



                    if (iocInput) iocInput.value = item.q;







                    currentResults = item.data;



                    document.getElementById('btn-save').style.display = 'inline-flex';







                    const resContainer = document.getElementById('results-container');



                    resContainer.innerHTML = '';



                    detachResultsNavigationObserver();



                    activeSourceTabs.clear();







                    const cachedResults = Array.isArray(item.data) ? item.data : [item.data];



                    cachedResults.forEach((result, index) => {



                        if (result?.error) {



                            renderLookupErrorResult(result.indicator || item.q, result.error, index, result.type || historyActiveTab);



                        } else if (result) {



                            renderResults(result, index);



                        }



                    });







                    restoreResultsNavigation(false);



                    saveCurrentTabState();



                }, 100);



            });



        });







        // Re-lookup — navigate to the correct tab, fill the input, and fire a fresh live query



        grid.querySelectorAll('.hist-relookup').forEach(btn => {



            btn.addEventListener('click', () => {



                const item = items[parseInt(btn.dataset.idx)];



                const type = item.type || historyActiveTab;







                // Navigate to the right tab



                const _IOC_RELOOKUP_TYPES = ['hash', 'domain', 'ip', 'url', 'keyword'];



                if (_IOC_RELOOKUP_TYPES.includes(type) && typeof switchToIocSearch === 'function') {



                    switchToIocSearch(type);



                } else {



                    const tabBtn = document.querySelector(`.nav-item[data-tab="${type}"]`);



                    if (tabBtn) tabBtn.click();



                }







                // Small delay to let tab switch settle, then populate input + trigger search



                setTimeout(() => {



                    const iocInput = document.getElementById('ioc-input');



                    if (iocInput) {



                        iocInput.value = item.q;



                        // Briefly highlight the input so the user sees what was loaded



                        iocInput.style.transition = 'box-shadow 0.3s';



                        iocInput.style.boxShadow = '0 0 0 2px var(--accent)';



                        setTimeout(() => { iocInput.style.boxShadow = ''; }, 800);



                    }







                    // Trigger the search



                    const searchBtn = document.getElementById('btn-search');



                    if (searchBtn && typeof performSearch === 'function') {



                        performSearch();



                    } else if (searchBtn) {



                        searchBtn.click();



                    }



                }, 150);



            });



        });



    }







    document.querySelectorAll('#history-subtabs .galaxy-subtab').forEach(btn => {



        btn.addEventListener('click', () => {



            if (historyActiveTab === btn.dataset.histtype) return;



            historyActiveTab = btn.dataset.histtype;



            openHistoryPane();



        });



    });







    document.getElementById('btn-clear-history')?.addEventListener('click', async () => {



        if (historyActiveTab === 'ai_reports') {



            if (!confirm('Are you sure you want to delete all saved AI threat reports?')) return;



            try {



                const res = await fetch(`${API_BASE}/api/ai/reports`);



                const data = await res.json();



                const reports = data.reports || [];



                for (const r of reports) {



                    await fetch(`${API_BASE}/api/ai/reports/${encodeURIComponent(r.filename)}`, { method: 'DELETE' });



                }



                showNotification('All AI reports deleted');



                renderHistoryGrid();



            } catch (err) {



                showNotification('Failed to clear reports: ' + err.message);



            }



            return;



        }



        if (!confirm('Are you sure you want to clear all lookup history?')) return;



        await initHistoryDB();



        const tx = mantisDB.transaction(['history'], 'readwrite');



        tx.objectStore('history').clear();



        tx.oncomplete = () => {



            openHistoryPane();



            showNotification('History cleared');



        };



    });







    // ---------------- Vulnerability Intelligence (PoC Index) ----------------



    let pocState = {



        page: 1,



        limit: 25,



        total: 0,



        sort: 'NEWEST',



        query: '',



        severity: new Set(),



        sources: new Set(),



        kevOnly: false,



        hasPocOnly: false,



        debounceTimer: null,



        initialized: false



    };







    let osvState = {



        page: 1,



        limit: 25,



        total: 0,



        query: '',



        ecosystem: '',



        debounceTimer: null



    };







    async function openPocIndexPane() {



        const pane = document.getElementById('poc-index-pane');



        if (pane) pane.style.display = 'block';







        if (!pocState.initialized) {



            pocState.initialized = true;



            initPocIndexEvents();



        }







        loadPocStats();



        checkPocSyncStatus();







        const input = document.getElementById('poc-search-input');



        if (input && input.value.trim()) {



            pocState.query = input.value.trim();



            runPocSearch();



        } else {



            loadPocTrending();



        }



    }



    window.openPocIndexPane = openPocIndexPane;







    async function checkPocSyncStatus() {



        const badge = document.getElementById('poc-sync-status');



        if (!badge) return;



        try {



            const res = await fetch('/api/poc/sync-status');



            if (!res.ok) return;



            const st = await res.json();



            if (st.state === 'running' || st.state === 'downloading' || st.state === 'syncing') {



                badge.style.display = 'inline-block';



                badge.innerHTML = `<i class="fa-solid fa-rotate mantis-spin"></i> Synchronizing CVE / PoC Intelligence database... (${escapeHtml(st.message || '')})`;



            } else {



                badge.style.display = 'none';



            }



        } catch (e) { }



    }







    async function loadPocStats() {



        try {



            const res = await fetch('/api/poc/stats');



            if (res.ok) {



                const stats = await res.json();



                const elCves = document.getElementById('poc-stat-cves');



                const elPocs = document.getElementById('poc-stat-pocs');



                const elKev = document.getElementById('poc-stat-kev');



                if (elCves) elCves.textContent = Number(stats.total_cves || 0).toLocaleString();



                if (elPocs) elPocs.textContent = Number(stats.with_pocs || 0).toLocaleString();



                if (elKev) elKev.textContent = Number(stats.kev_count || 0).toLocaleString();



            }



        } catch (e) {



            console.error('Failed to load Vulnerability Intelligence stats:', e);



        }







        try {



            const resOsv = await fetch('/api/osv/malicious-stats');



            if (resOsv.ok) {



                const osvStats = await resOsv.json();



                const elOsv = document.getElementById('poc-stat-osv');



                if (elOsv) elOsv.textContent = Number(osvStats.malicious_packages || osvStats.total_records || 0).toLocaleString();



            }



        } catch (e) {



            console.error('Failed to load OSV malicious package stats:', e);



        }



    }







    async function loadOsvMalicious(ecosystem = osvState.ecosystem, query = osvState.query, page = osvState.page) {



        osvState.ecosystem = ecosystem;



        osvState.query = query;



        osvState.page = page;







        const container = document.getElementById('osv-malicious-rows');



        const countEl = document.getElementById('osv-results-count');



        if (!container) return;







        container.innerHTML = '<div style="padding: 30px; text-align: center; color: var(--text-muted);"><i class="fa-solid fa-circle-notch mantis-spin"></i> Loading OSV malicious supply-chain packages...</div>';







        try {



            const offset = (page - 1) * osvState.limit;



            let url = `/api/osv/recent?malicious=true&limit=${osvState.limit}&offset=${offset}&include_details=true`;



            if (ecosystem && ecosystem !== 'ALL') {



                url += `&ecosystem=${encodeURIComponent(ecosystem)}`;



            }



            if (query) {



                url += `&q=${encodeURIComponent(query)}`;



            }







            const res = await fetch(url);



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            const data = await res.json();



            const items = Array.isArray(data) ? data : (data.items || data.results || []);



            const total = data.total || items.length || 0;



            osvState.total = total;







            if (countEl) {



                countEl.textContent = total > 0 ? `${Number(total).toLocaleString()} Malicious Package Record${total === 1 ? '' : 's'}` : '';



            }







            if (!items.length) {



                container.innerHTML = '<div style="padding: 40px; text-align: center; color: var(--text-muted);"><i class="fa-solid fa-box-open" style="font-size: 2.5rem; margin-bottom: 12px; opacity: 0.4;"></i><br>No malicious open-source packages found for this search / filter.</div>';



                renderOsvPagination(0);



                return;



            }







            container.innerHTML = items.map(item => renderOsvMaliciousRow(item)).join('');



            renderOsvPagination(total);



        } catch (e) {



            container.innerHTML = `<div style="padding: 24px; color: var(--danger); text-align: center;"><i class="fa-solid fa-triangle-exclamation"></i> Failed to load OSV packages: ${escapeHtml(e.message)}</div>`;



        }



    }







    function renderOsvPagination(total) {



        const pag = document.getElementById('osv-pagination');



        if (!pag) return;



        if (total <= osvState.limit) {



            pag.style.display = 'none';



            return;



        }



        pag.style.display = 'flex';



        const totalPages = Math.ceil(total / osvState.limit);



        const curr = osvState.page;







        let btns = '';



        btns += `<button class="poc-page-btn" ${curr <= 1 ? 'disabled' : ''} data-page="${curr - 1}"><i class="fa-solid fa-chevron-left"></i> Prev</button>`;







        let startPage = Math.max(1, curr - 2);



        let endPage = Math.min(totalPages, startPage + 4);



        if (endPage - startPage < 4) startPage = Math.max(1, endPage - 4);







        for (let i = startPage; i <= endPage; i++) {



            btns += `<button class="poc-page-btn ${i === curr ? 'active' : ''}" data-page="${i}">${i}</button>`;



        }



        btns += `<button class="poc-page-btn" ${curr >= totalPages ? 'disabled' : ''} data-page="${curr + 1}">Next <i class="fa-solid fa-chevron-right"></i></button>`;







        pag.innerHTML = btns;



        pag.querySelectorAll('.poc-page-btn:not(:disabled)').forEach(btn => {



            btn.addEventListener('click', () => {



                const p = parseInt(btn.dataset.page);



                if (p && p !== osvState.page) {



                    osvState.page = p;



                    loadOsvMalicious();



                    document.getElementById('poc-index-pane')?.scrollTo({ top: 0, behavior: 'smooth' });



                }



            });



        });



    }







    function renderOsvMaliciousRow(item) {



        const id = escapeHtml(item.id || item.osv_id || 'OSV-MALICIOUS');



        const summary = escapeHtml(item.summary || item.details || item.title || 'Malicious open-source package advisory');



        const modified = item.modified || item.published || '-';







        let eco = item.ecosystem || '';



        let pkgName = item.package_name || item.name || '';



        let versionsStr = '';







        if (Array.isArray(item.packages) && item.packages.length) {



            const firstPkg = item.packages[0];



            if (typeof firstPkg === 'string') {



                if (firstPkg.includes('/')) {



                    const parts = firstPkg.split('/');



                    if (!eco) eco = parts[0];



                    pkgName = parts.slice(1).join('/');



                } else {



                    pkgName = firstPkg;



                }



            } else if (typeof firstPkg === 'object' && firstPkg !== null) {



                if (!pkgName) pkgName = firstPkg.name || firstPkg.package || '';



                if (!eco) eco = firstPkg.ecosystem || '';



                if (firstPkg.versions && firstPkg.versions.length) {



                    versionsStr = firstPkg.versions.slice(0, 3).join(', ') + (firstPkg.versions.length > 3 ? '...' : '');



                }



            }



        } else if (Array.isArray(item.affected) && item.affected.length) {



            const firstAff = item.affected[0];



            if (firstAff.package) {



                if (!pkgName) pkgName = firstAff.package.name || '';



                if (!eco) eco = firstAff.package.ecosystem || '';



            }



        }







        if (!pkgName && summary) {



            const m = summary.match(/in\s+([^\s()]+)/i);



            if (m && m[1]) pkgName = m[1];



        }







        const ecoClass = (eco || '').toLowerCase().replace(/[^a-z0-9]/g, '');



        const ecoBadgeHtml = eco ? `<span class="poc-chip is-eco ${ecoClass}">${escapeHtml(eco)}</span>` : '';



        const osvUrl = `https://osv.dev/vulnerability/${encodeURIComponent(id)}`;







        return `



            <div class="poc-result-row">



                <div class="poc-result-meta" style="width: 260px; flex-shrink: 0;">



                    <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">



                        <a href="${osvUrl}" target="_blank" class="poc-cve-id" style="color: var(--accent); text-decoration: none;">



                            <i class="fa-solid fa-box-open"></i> ${id}



                        </a>



                    </div>



                    <div class="poc-chips" style="margin-top: 8px;">



                        <span class="poc-chip is-critical"><i class="fa-solid fa-biohazard"></i> MALICIOUS</span>



                        ${ecoBadgeHtml}



                    </div>



                    <div style="font-size: 0.73rem; color: var(--text-muted); margin-top: 6px;">



                        <i class="fa-regular fa-clock"></i> ${escapeHtml(modified)}



                    </div>



                </div>



                <div style="flex: 1; min-width: 0;">



                    <div style="font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 4px;">



                        ${pkgName ? `<span style="color: var(--accent-light); font-family: monospace;">${escapeHtml(pkgName)}</span>` : 'Malicious Package'}



                        ${versionsStr ? `<span style="font-size: 0.78rem; font-weight: normal; color: var(--text-muted); margin-left: 8px;">(affected: ${escapeHtml(versionsStr)})</span>` : ''}



                    </div>



                    <div style="font-size: 0.85rem; color: var(--text-main); line-height: 1.5; margin-bottom: 8px;">${summary}</div>



                    <div class="poc-chips">



                        <a href="${osvUrl}" target="_blank" class="poc-chip" style="text-decoration:none;">



                            <i class="fa-solid fa-up-right-from-square"></i> OSV.dev Advisory



                        </a>



                        ${id.startsWith('GHSA-') ? `



                            <a href="https://github.com/advisories/${encodeURIComponent(id)}" target="_blank" class="poc-chip" style="text-decoration:none;">



                                <i class="fa-brands fa-github"></i> GitHub Advisory



                            </a>



                        ` : ''}



                    </div>



                </div>



            </div>



        `;



    }







    async function loadPocTrending() {



        const trendingSec = document.getElementById('poc-trending-section');



        const resultsSec = document.getElementById('poc-search-results-section');



        const container = document.getElementById('poc-trending-rows');



        if (!container) return;







        if (trendingSec) trendingSec.style.display = 'block';



        if (resultsSec) resultsSec.style.display = 'none';



        container.innerHTML = '<div style="padding: 24px; text-align: center; color: var(--text-muted);"><i class="fa-solid fa-circle-notch mantis-spin"></i> Loading trending vulnerabilities...</div>';







        try {



            const res = await fetch('/api/poc/trending?limit=25');



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            const data = await res.json();



            const items = Array.isArray(data) ? data : (data.results || []);







            if (!items.length) {



                container.innerHTML = '<div style="padding: 24px; text-align: center; color: var(--text-muted);">No trending vulnerabilities at the moment.</div>';



                return;



            }







            container.innerHTML = items.map(item => renderPocTrendingRow(item)).join('');



            bindPocLinks(container);



        } catch (e) {



            container.innerHTML = `<div style="padding: 20px; color: var(--danger); text-align: center;"><i class="fa-solid fa-circle-exclamation"></i> Failed to load trending data: ${escapeHtml(e.message)}</div>`;



        }



    }







    function renderPocTrendingRow(item) {



        const cve = escapeHtml(item.cve || item.name || 'CVE');



        const stars = item.stars ? `<b style="color:var(--accent);">${Number(item.stars).toLocaleString()} ★</b>` : '-';



        const updated = item.updated || item.date || '-';



        const desc = escapeHtml(item.desc || item.description || item.title || '');



        const links = item.poc || item.links || [];



        const linksHtml = Array.isArray(links) && links.length ? links.slice(0, 3).map(link => `



            <a href="${escapeHtml(link)}" target="_blank" class="poc-chip" style="font-size: 0.72rem; text-decoration: none;">



                <i class="fa-brands fa-github"></i> ${escapeHtml(link.replace(/^https?:\/\/(www\.)?github\.com\//i, ''))}



            </a>



        `).join(' ') : '';







        return `



            <div class="poc-trend-row">



                <div class="col-stars">${stars}</div>



                <div class="col-updated" style="font-size: 0.75rem; color: var(--text-muted);">${updated}</div>



                <div class="col-name">



                    <span class="poc-cve-id" data-cve="${cve}">${cve}</span>



                    ${item.kev ? '<span class="poc-kev-badge">KEV</span>' : ''}



                </div>



                <div class="col-desc">



                    <div>${desc}</div>



                    ${linksHtml ? `<div style="margin-top: 6px; display: flex; flex-wrap: wrap; gap: 6px;">${linksHtml}</div>` : ''}



                </div>



            </div>



        `;



    }







    async function runPocSearch() {



        const trendingSec = document.getElementById('poc-trending-section');



        const resultsSec = document.getElementById('poc-search-results-section');



        const rowsContainer = document.getElementById('poc-search-rows');



        const countEl = document.getElementById('poc-results-count');



        const backBtn = document.getElementById('poc-btn-back-trending');







        if (trendingSec) trendingSec.style.display = 'none';



        if (resultsSec) resultsSec.style.display = 'block';



        if (backBtn) backBtn.style.display = 'inline-flex';



        if (rowsContainer) rowsContainer.innerHTML = '<div style="padding: 30px; text-align: center; color: var(--text-muted);"><i class="fa-solid fa-circle-notch mantis-spin"></i> Searching vulnerability intelligence database...</div>';







        const q = encodeURIComponent(pocState.query);



        const sev = encodeURIComponent([...pocState.severity].join(','));



        const src = encodeURIComponent([...pocState.sources].join(','));



        const kev = pocState.kevOnly ? 'true' : 'false';



        const hasPoc = pocState.hasPocOnly ? 'true' : 'false';



        const page = pocState.page;



        const limit = pocState.limit;



        const sort = pocState.sort;







        try {



            const res = await fetch(`/api/poc/search?q=${q}&severity=${sev}&source=${src}&kev=${kev}&has_poc=${hasPoc}&page=${page}&limit=${limit}&sort=${sort}`);



            if (!res.ok) throw new Error(`HTTP ${res.status}`);



            const data = await res.json();



            const total = data.total || 0;



            const results = data.results || [];



            pocState.total = total;







            if (countEl) countEl.textContent = `${Number(total).toLocaleString()} Vulnerability Result${total === 1 ? '' : 's'}`;







            if (!results.length) {



                if (rowsContainer) rowsContainer.innerHTML = '<div style="padding: 40px; text-align: center; color: var(--text-muted);"><i class="fa-solid fa-shield-virus" style="font-size: 2.5rem; margin-bottom: 12px; opacity: 0.4;"></i><br>No vulnerabilities match your query or filters.</div>';



                renderPocPagination(0);



                return;



            }







            if (rowsContainer) {



                rowsContainer.innerHTML = results.map(r => renderPocResultRow(r)).join('');



                bindPocLinks(rowsContainer);



            }



            renderPocPagination(total);



        } catch (e) {



            if (rowsContainer) rowsContainer.innerHTML = `<div style="padding: 24px; color: var(--danger); text-align: center;"><i class="fa-solid fa-triangle-exclamation"></i> Search failed: ${escapeHtml(e.message)}</div>`;



        }



    }







    function renderPocResultRow(item) {



        const cve = escapeHtml(item.cve || 'CVE');



        const desc = escapeHtml(item.desc || item.description || item.title || 'No description available');



        const sev = (item.severity || 'UNKNOWN').toUpperCase();







        let sevClass = 'is-low';



        if (sev === 'CRITICAL') sevClass = 'is-critical';



        else if (sev === 'HIGH') sevClass = 'is-high';



        else if (sev === 'MEDIUM') sevClass = 'is-medium';







        const kevChip = item.kev ? '<span class="poc-chip is-kev"><i class="fa-solid fa-fire"></i> KEV</span>' : '';



        const epssChip = item.epss ? `<span class="poc-chip is-epss">EPSS ${parseFloat(item.epss).toFixed(2)}</span>` : '';



        const sevChip = sev !== 'UNKNOWN' ? `<span class="poc-chip ${sevClass}">${sev}</span>` : '';







        const renderPocList = (list, label, iconClass, chipClass) => {



            if (!Array.isArray(list) || !list.length) return '';



            return list.map(link => `



                <a href="${escapeHtml(link)}" target="_blank" class="poc-chip ${chipClass}" style="text-decoration:none;">



                    <i class="${iconClass}"></i> ${escapeHtml(label)}: ${escapeHtml(link.replace(/^https?:\/\/(www\.)?/i, '').slice(0, 36))}



                </a>



            `).join(' ');



        };







        const githubLinks = renderPocList(item.poc, 'GitHub', 'fa-brands fa-github', '');



        const nucleiLinks = renderPocList(item.nuclei, 'Nuclei', 'fa-solid fa-bolt', 'is-hot');



        const msfLinks = renderPocList(item.msf, 'Metasploit', 'fa-solid fa-terminal', 'is-critical');



        const edbLinks = renderPocList(item.edb, 'ExploitDB', 'fa-solid fa-code', 'is-medium');



        const vulhubLinks = renderPocList(item.vulhub, 'Vulhub', 'fa-solid fa-docker', 'is-osv');







        const allPocs = [githubLinks, nucleiLinks, msfLinks, edbLinks, vulhubLinks].filter(Boolean).join(' ');







        return `



            <div class="poc-result-row">



                <div class="poc-result-meta" style="width: 250px; flex-shrink: 0;">



                    <span class="poc-cve-id" data-cve="${cve}">${cve}</span>



                    <div class="poc-chips" style="margin-top: 6px;">



                        ${sevChip}



                        ${kevChip}



                        ${epssChip}



                    </div>



                </div>



                <div style="flex: 1; min-width: 0;">



                    <div style="font-size: 0.88rem; color: var(--text-main); line-height: 1.5; margin-bottom: 8px;">${desc}</div>



                    ${allPocs ? `<div class="poc-chips">${allPocs}</div>` : '<div style="font-size: 0.75rem; color: var(--text-muted); font-style: italic;">No verified public exploit code linked</div>'}



                </div>



            </div>



        `;



    }







    function renderPocPagination(total) {



        const pag = document.getElementById('poc-pagination');



        if (!pag) return;



        if (total <= pocState.limit) {



            pag.style.display = 'none';



            return;



        }



        pag.style.display = 'flex';



        const totalPages = Math.ceil(total / pocState.limit);



        const curr = pocState.page;







        let btns = '';



        btns += `<button class="poc-page-btn" ${curr <= 1 ? 'disabled' : ''} data-page="${curr - 1}"><i class="fa-solid fa-chevron-left"></i> Prev</button>`;







        let startPage = Math.max(1, curr - 2);



        let endPage = Math.min(totalPages, startPage + 4);



        if (endPage - startPage < 4) startPage = Math.max(1, endPage - 4);







        for (let i = startPage; i <= endPage; i++) {



            btns += `<button class="poc-page-btn ${i === curr ? 'active' : ''}" data-page="${i}">${i}</button>`;



        }



        btns += `<button class="poc-page-btn" ${curr >= totalPages ? 'disabled' : ''} data-page="${curr + 1}">Next <i class="fa-solid fa-chevron-right"></i></button>`;







        pag.innerHTML = btns;



        pag.querySelectorAll('.poc-page-btn:not(:disabled)').forEach(btn => {



            btn.addEventListener('click', () => {



                const p = parseInt(btn.dataset.page);



                if (p && p !== pocState.page) {



                    pocState.page = p;



                    runPocSearch();



                    document.getElementById('poc-index-pane')?.scrollTo({ top: 0, behavior: 'smooth' });



                }



            });



        });



    }







    function bindPocLinks(container) {



        if (!container) return;



        container.querySelectorAll('.poc-cve-id').forEach(el => {



            el.style.cursor = 'pointer';



            el.addEventListener('click', () => {



                const cve = el.dataset.cve || el.textContent.trim();



                const input = document.getElementById('poc-search-input');



                if (input) {



                    input.value = cve;



                    pocState.query = cve;



                    pocState.page = 1;



                    runPocSearch();



                }



            });



        });



    }







    function initPocIndexEvents() {



        const searchInput = document.getElementById('poc-search-input');



        if (searchInput) {



            searchInput.addEventListener('input', () => {



                clearTimeout(pocState.debounceTimer);



                pocState.debounceTimer = setTimeout(() => {



                    pocState.query = searchInput.value.trim();



                    pocState.page = 1;



                    if (pocState.query || pocState.severity.size || pocState.sources.size || pocState.kevOnly || pocState.hasPocOnly) {



                        runPocSearch();



                    } else {



                        loadPocTrending();



                    }



                }, 300);



            });



        }







        document.querySelectorAll('#poc-filter-severity .filter-chip').forEach(chip => {



            chip.addEventListener('click', () => {



                const val = chip.dataset.val;



                if (pocState.severity.has(val)) {



                    pocState.severity.delete(val);



                    chip.classList.remove('active');



                } else {



                    pocState.severity.add(val);



                    chip.classList.add('active');



                }



                pocState.page = 1;



                runPocSearch();



            });



        });







        const kevBtn = document.getElementById('poc-filter-kev');



        if (kevBtn) {



            kevBtn.addEventListener('click', () => {



                pocState.kevOnly = !pocState.kevOnly;



                kevBtn.classList.toggle('active', pocState.kevOnly);



                pocState.page = 1;



                runPocSearch();



            });



        }







        document.querySelectorAll('#poc-filter-source .filter-chip').forEach(chip => {



            chip.addEventListener('click', () => {



                const val = chip.dataset.val;



                if (pocState.sources.has(val)) {



                    pocState.sources.delete(val);



                    chip.classList.remove('active');



                } else {



                    pocState.sources.add(val);



                    chip.classList.add('active');



                }



                pocState.page = 1;



                runPocSearch();



            });



        });







        document.querySelectorAll('#poc-sort-switch button').forEach(btn => {



            btn.addEventListener('click', () => {



                document.querySelectorAll('#poc-sort-switch button').forEach(b => b.classList.remove('active'));



                btn.classList.add('active');



                pocState.sort = btn.dataset.sort || 'RELEVANCE';



                pocState.page = 1;



                runPocSearch();



            });



        });







        function switchToCveSubtab() {



            document.querySelectorAll('#vuln-view-tabs .galaxy-subtab').forEach(b => b.classList.remove('active'));



            const cveSubtab = document.querySelector('#vuln-view-tabs .galaxy-subtab[data-vtab="cve"]');



            if (cveSubtab) cveSubtab.classList.add('active');



            const cveView = document.getElementById('cve-view-container');



            const osvView = document.getElementById('osv-view-container');



            if (osvView) osvView.style.display = 'none';



            if (cveView) cveView.style.display = 'block';



        }







        document.getElementById('poc-box-cves')?.addEventListener('click', () => {



            switchToCveSubtab();



            pocState.query = '';



            pocState.severity.clear();



            pocState.sources.clear();



            pocState.kevOnly = false;



            pocState.hasPocOnly = false;



            pocState.page = 1;



            document.querySelectorAll('.poc-filters .filter-chip').forEach(c => c.classList.remove('active'));



            const input = document.getElementById('poc-search-input');



            if (input) input.value = '';



            runPocSearch();



        });







        document.getElementById('poc-box-pocs')?.addEventListener('click', () => {



            switchToCveSubtab();



            pocState.hasPocOnly = true;



            pocState.page = 1;



            runPocSearch();



        });







        document.getElementById('poc-box-kev')?.addEventListener('click', () => {



            switchToCveSubtab();



            pocState.kevOnly = true;



            const kevBtn = document.getElementById('poc-filter-kev');



            if (kevBtn) kevBtn.classList.add('active');



            pocState.page = 1;



            runPocSearch();



        });







        document.getElementById('poc-btn-browse-all')?.addEventListener('click', () => {



            pocState.query = '';



            pocState.page = 1;



            runPocSearch();



        });







        document.getElementById('poc-btn-back-trending')?.addEventListener('click', () => {



            const input = document.getElementById('poc-search-input');



            if (input) input.value = '';



            pocState.query = '';



            pocState.severity.clear();



            pocState.sources.clear();



            pocState.kevOnly = false;



            pocState.hasPocOnly = false;



            document.querySelectorAll('.poc-filters .filter-chip').forEach(c => c.classList.remove('active'));



            loadPocTrending();



        });







        document.querySelectorAll('#vuln-view-tabs .galaxy-subtab').forEach(btn => {



            btn.addEventListener('click', () => {



                document.querySelectorAll('#vuln-view-tabs .galaxy-subtab').forEach(b => b.classList.remove('active'));



                btn.classList.add('active');



                const targetTab = btn.dataset.vtab || btn.dataset.tab;



                const cveView = document.getElementById('cve-view-container');



                const osvView = document.getElementById('osv-view-container');







                if (targetTab === 'osv') {



                    if (cveView) cveView.style.display = 'none';



                    if (osvView) osvView.style.display = 'block';



                    loadOsvMalicious();



                } else {



                    if (osvView) osvView.style.display = 'none';



                    if (cveView) cveView.style.display = 'block';



                }



            });



        });







        const osvSearchInput = document.getElementById('osv-search-input');



        if (osvSearchInput) {



            osvSearchInput.addEventListener('input', () => {



                clearTimeout(osvState.debounceTimer);



                osvState.debounceTimer = setTimeout(() => {



                    osvState.query = osvSearchInput.value.trim();



                    osvState.page = 1;



                    loadOsvMalicious();



                }, 300);



            });



        }







        document.querySelectorAll('#osv-ecosystem-tabs .galaxy-subtab').forEach(btn => {



            btn.addEventListener('click', () => {



                document.querySelectorAll('#osv-ecosystem-tabs .galaxy-subtab').forEach(b => b.classList.remove('active'));



                btn.classList.add('active');



                const eco = btn.dataset.eco || '';



                osvState.page = 1;



                loadOsvMalicious(eco);



            });



        });







        document.getElementById('poc-box-osv')?.addEventListener('click', () => {



            const osvSubtab = document.querySelector('#vuln-view-tabs .galaxy-subtab[data-vtab="osv"]');



            if (osvSubtab) osvSubtab.click();



        });



    }







    // ---------------------------------------------------------------------------



    // Breach Watcher Implementation



    // ---------------------------------------------------------------------------



    let bwFeedState = { page: 1, pageSize: 20, query: '', source: '' };
let bwFeedRequestSeq = 0;
const bwSafeUrl = (u) => /^https?:\/\//i.test(String(u || '').trim()) ? String(u).trim() : '';







    function decodeHtmlEntities(str) {



        if (!str) return '';



        const txt = document.createElement('textarea');



        txt.innerHTML = str;



        return txt.value;



    }







    function cleanBwText(val, limit = 500) {



        if (!val) return '';



        let text = String(val).replace(/<[^>]+>/g, ' ');



        text = decodeHtmlEntities(text);



        text = text.replace(/\s+/g, ' ').trim();



        return limit && text.length > limit ? text.slice(0, limit) + '...' : text;



    }



    const _clean_text = cleanBwText;







    function renderBwFeedPager(pagination = {}) {



        const pager = document.getElementById('bw-live-feed-pagination');



        if (!pager) return;



        const pages = Number(pagination.pages || 1);



        const page = Number(pagination.page || 1);



        const total = Number(pagination.total || 0);







        if (pages <= 1) {



            pager.innerHTML = total > 0 ? `<div style="color:var(--text-muted); font-size:0.75rem;">Showing ${total} record${total === 1 ? '' : 's'}</div>` : '';



            return;



        }







        const buttons = [];



        for (let p = 1; p <= pages; p += 1) {



            if (p === 1 || p === pages || Math.abs(p - page) <= 2) {



                buttons.push(`<button type="button" class="${p === page ? 'active' : ''}" onclick="window.bwLoadFeed(${p})">${p}</button>`);



            } else if (!buttons[buttons.length - 1]?.includes('xmon-page-gap')) {



                buttons.push('<span class="xmon-page-gap">...</span>');



            }



        }



        pager.innerHTML = `



            <div style="display:flex; align-items:center; gap:10px; width:100%; justify-content:center; flex-wrap:wrap;">



                <span style="color:var(--text-muted); font-size:0.75rem; margin-right:8px;">Page ${page} of ${pages} (${total} total records)</span>



                ${buttons.join('')}



            </div>



        `;



    }







    async function bwLoadFeed(targetPage, forceRefresh = false) {
        const requestSeq = ++bwFeedRequestSeq;



        if (typeof targetPage === 'number') {



            bwFeedState.page = targetPage;



        }



        const q = (document.getElementById('bw-feed-search')?.value || '').trim();



        const sf = (document.getElementById('bw-feed-source-filter')?.value || '').trim();



        bwFeedState.query = q;



        bwFeedState.source = sf;







        const list = document.getElementById('bw-live-feed-list');



        const pager = document.getElementById('bw-live-feed-pagination');



        if (!list) return;







        list.innerHTML = '<div class="empty-state"><i class="fa-solid fa-circle-notch mantis-spin"></i><p>Loading breach feed...</p></div>';







        try {



            const res = await fetch(`${API_BASE}/api/breach-watcher/feed?page=${bwFeedState.page}&page_size=${bwFeedState.pageSize}&query=${encodeURIComponent(bwFeedState.query)}&source=${encodeURIComponent(bwFeedState.source)}${forceRefresh ? '&refresh=true' : ''}`);



            const data = await res.json().catch(() => ({}));

            if (requestSeq !== bwFeedRequestSeq) return;

            if (!res.ok) throw new Error(typeof data.detail === 'string' ? data.detail : `HTTP ${res.status}`);







            const items = data.items || [];



            const pagination = data.pagination || {};







            if (!items.length) {



                list.innerHTML = '<div class="empty-state"><i class="fa-solid fa-user-shield"></i><p>No breach records match your filters.</p></div>';



                if (pager) pager.innerHTML = '';



                return;



            }







            list.innerHTML = items.map(item => {



                const titleClean = cleanBwText(item.title, 200);



                const summaryClean = cleanBwText(item.summary, 600);



                const sourceRaw = item.source || 'Breach';



                const sourceClass = 'bw-source-' + sourceRaw.replace(/[^a-zA-Z0-9]/g, '');



                const sourceLinkLabel = sourceRaw.startsWith('RecentBreaches')



                    ? 'Breach data from RecentBreaches'



                    : (sourceRaw === 'DataBreach.watch' ? 'Data from Data Breach Watch' : 'View Source');



                return `



                <div class="bw-feed-card tg-feed-item">



                    <div class="tg-feed-item-header">



                        <span class="bw-feed-title tg-feed-channel">${escapeHtml(titleClean)}</span>



                        <span class="bw-source-badge ${sourceClass} tg-cat-badge">${escapeHtml(sourceRaw)}</span>



                        <span style="color:var(--text-muted); font-size:0.72rem; margin-left:auto; white-space:nowrap;"><i class="fa-regular fa-clock"></i> ${escapeHtml(item.published || 'Recent')}</span>



                    </div>



                    <div class="bw-feed-summary">${escapeHtml(summaryClean)}</div>



                    ${bwSafeUrl(item.url) ? `<div style="margin-top:8px;"><a href="${escapeHtml(bwSafeUrl(item.url))}" target="_blank" rel="noopener noreferrer" style="color:var(--accent); font-size:0.75rem; font-weight:600; text-decoration:none; display:inline-flex; align-items:center; gap:5px;"><i class="fa-solid fa-up-right-from-square"></i> ${escapeHtml(sourceLinkLabel)}</a></div>` : ''}



                </div>



            `;



            }).join('');







            renderBwFeedPager(pagination);



        } catch (e) {



            if (requestSeq !== bwFeedRequestSeq) return;

            list.innerHTML = `<div style="color:var(--danger);">Error loading breach feed: ${escapeHtml(e.message)}</div>`;



            if (pager) pager.innerHTML = '';



        }



    }



    window.bwLoadFeed = bwLoadFeed;







    async function bwLoadStats(forceRefresh = false) {



        try {



            const res = await fetch(`${API_BASE}/api/breach-watcher/stats${forceRefresh ? '?refresh=true' : ''}`);



            const d = await res.json();



            if (!res.ok) return;







            const recEl = document.getElementById('bw-metric-records');



            const hibpEl = document.getElementById('bw-metric-hibp');



            const pwnEl = document.getElementById('bw-metric-pwned');



            const latEl = document.getElementById('bw-metric-latest');







            if (recEl) recEl.textContent = Number(d.total_feed_records || 0).toLocaleString();



            if (hibpEl) hibpEl.textContent = Number(d.total_hibp_breaches || 0).toLocaleString();







            const pwned = Number(d.total_pwned_accounts || 0);



            if (pwnEl) pwnEl.textContent = pwned > 1e9 ? `${(pwned / 1e9).toFixed(1)}B` : (pwned > 1e6 ? `${(pwned / 1e6).toFixed(1)}M` : pwned.toLocaleString());







            if (latEl) latEl.textContent = d.latest_breach_name || 'N/A';



        } catch (e) {



            console.warn('Error loading breach watcher stats:', e);



        }



    }







    async function bwLoadHibpCatalog(forceRefresh = false) {



        const wrap = document.getElementById('bw-hibp-list-wrap');



        const hero = document.getElementById('bw-hibp-hero-container');



        const q = (document.getElementById('bw-hibp-search')?.value || '').trim();



        if (!wrap) return;







        wrap.innerHTML = '<div class="empty-state"><i class="fa-solid fa-circle-notch mantis-spin"></i><p>Loading HaveIBeenPwned catalog...</p></div>';







        try {



            const [breachesRes, latestRes] = await Promise.all([



                fetch(`${API_BASE}/api/breach-watcher/hibp/breaches?search=${encodeURIComponent(q)}${forceRefresh ? '&refresh=true' : ''}`),



                fetch(`${API_BASE}/api/breach-watcher/hibp/latest${forceRefresh ? '?refresh=true' : ''}`)



            ]);







            if (!breachesRes.ok) throw new Error(`HIBP catalog request failed (HTTP ${breachesRes.status})`);

            const breaches = await breachesRes.json();



            const latest = latestRes.ok ? await latestRes.json().catch(() => ({})) : {};







            if (hero) hero.innerHTML = '';

            if (hero && latest && latest.Name) {



                hero.innerHTML = `



                    <div style="background:rgba(255,204,0,0.05); border:1px solid rgba(255,204,0,0.2); border-radius:8px; padding:14px 16px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">



                        <div>



                            <div style="font-size:0.7rem; font-weight:800; color:var(--accent); text-transform:uppercase;"><i class="fa-solid fa-bullhorn"></i> Latest HIBP Breach Added</div>



                            <div style="font-size:1.1rem; font-weight:700; color:var(--text-main); margin-top:2px;">${escapeHtml(latest.Title || latest.Name)} (${escapeHtml(latest.Domain || 'N/A')})</div>



                            <div style="font-size:0.78rem; color:var(--text-muted); margin-top:4px;">Breach Date: ${escapeHtml(latest.BreachDate)} &bull; ${Number(latest.PwnCount || 0).toLocaleString()} pwned accounts</div>



                        </div>



                        <div style="display:flex; gap:6px; flex-wrap:wrap;">



                            ${(latest.DataClasses || []).slice(0, 4).map(dc => `<span class="tg-cat-badge tg-cat-stealer_logs">${escapeHtml(dc)}</span>`).join('')}



                        </div>



                    </div>



                `;



            }







            if (!breaches || !breaches.length) {



                wrap.innerHTML = '<div class="empty-state"><i class="fa-solid fa-database"></i><p>No HIBP breach catalog records match your query.</p></div>';



                return;



            }







            wrap.innerHTML = `



                <table class="yara-det-table" style="width:100%;">



                    <thead>



                        <tr>



                            <th>Breach / Domain</th>



                            <th>Breach Date</th>



                            <th>Pwn Count</th>



                            <th>Compromised Data Classes</th>



                            <th>Description</th>



                        </tr>



                    </thead>



                    <tbody>



                        ${breaches.map(b => `



                            <tr>



                                <td style="font-weight:700; color:var(--accent); min-width:140px;">



                                    ${escapeHtml(b.Title || b.Name)}



                                    <div style="font-size:0.7rem; font-weight:400; color:var(--text-muted);">${escapeHtml(b.Domain || '')}</div>



                                </td>



                                <td style="font-size:0.75rem; white-space:nowrap;">${escapeHtml(b.BreachDate || '')}</td>



                                <td style="font-weight:700; color:#ff5d9e; white-space:nowrap;">${Number(b.PwnCount || 0).toLocaleString()}</td>



                                <td>



                                    <div style="display:flex; gap:4px; flex-wrap:wrap;">



                                        ${(b.DataClasses || []).slice(0, 5).map(dc => `<span class="tg-cat-badge tg-cat-cti_research" style="font-size:0.65rem;">${escapeHtml(dc)}</span>`).join('')}



                                        ${(b.DataClasses || []).length > 5 ? `<span style="font-size:0.68rem; color:var(--text-muted);">+${b.DataClasses.length - 5} more</span>` : ''}



                                    </div>



                                </td>



                                <td style="font-size:0.78rem; color:var(--text-main); max-width:300px; line-height:1.4;">



                                    ${escapeHtml(cleanBwText(b.Description, 180))}



                                </td>



                            </tr>



                        `).join('')}



                    </tbody>



                </table>



            `;



        } catch (e) {



            wrap.innerHTML = `<div style="color:var(--danger);">Error loading HIBP catalog: ${escapeHtml(e.message)}</div>`;



        }



    }







    async function bwSearchLeakLookup() {



        const box = document.getElementById('bw-ll-results');



        const q = (document.getElementById('bw-ll-query')?.value || '').trim();



        const type = (document.getElementById('bw-ll-type')?.value || 'domain').trim();



        const key = (document.getElementById('leaklookup-key')?.value || localStorage.getItem('ioc_leaklookup_key') || '').trim();







        if (!box) return;



        if (!q) {



            box.innerHTML = '<div style="color:var(--danger); padding:10px;">Please enter a domain, email, or username to search.</div>';



            return;



        }







        box.innerHTML = '<div class="empty-state"><i class="fa-solid fa-circle-notch mantis-spin"></i><p>Querying Leak-Lookup database...</p></div>';







        try {



            const res = await fetch(`${API_BASE}/api/breach-watcher/leak-lookup/search`, {



                method: 'POST',



                headers: { 'Content-Type': 'application/json' },



                body: JSON.stringify({ query: q, query_type: type, key: key })



            });



            const d = await res.json();



            if (!res.ok) throw new Error(typeof d.detail === 'string' ? d.detail : (d.detail ? JSON.stringify(d.detail) : `HTTP ${res.status}`));







            if (d.error === "true" || d.error === true) {



                box.innerHTML = `<div style="color:var(--danger); padding:10px;">Leak-Lookup error: ${escapeHtml(d.message || 'Search failed')}</div>`;



                return;



            }







            if (d.message && typeof d.message !== 'object') {

                box.innerHTML = `<div style="color:var(--text-muted); padding:10px;">${escapeHtml(String(d.message))}</div>`;

                return;

            }

            const resultsMap = d.message || {};



            const databases = Object.keys(resultsMap);







            if (!databases.length) {



                box.innerHTML = '<div class="empty-state"><i class="fa-solid fa-shield-check"></i><p>No leak entries found in Leak-Lookup database for this target.</p></div>';



                return;



            }







            const totalReturnedRecords = databases.reduce((acc, db) => acc + (Array.isArray(resultsMap[db]) ? resultsMap[db].length : 0), 0);



            const isPublicRedacted = totalReturnedRecords === 0;







            const headerBannerHtml = isPublicRedacted ? `



                <div style="background:rgba(255,204,0,0.06); border:1px solid rgba(255,204,0,0.25); border-radius:8px; padding:14px 16px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">



                    <div>



                        <div style="font-size:0.95rem; font-weight:800; color:var(--accent); display:flex; align-items:center; gap:8px;">



                            <i class="fa-solid fa-triangle-exclamation"></i> Target Exposed in ${databases.length} Breach Database${databases.length === 1 ? '' : 's'} for "${escapeHtml(q)}"



                        </div>



                        <div style="font-size:0.78rem; color:var(--text-muted); margin-top:4px; line-height:1.4;">



                            Breach presence confirmed across all indexed collections below. Individual credential rows are redacted by the provider on Public API key queries.



                        </div>



                    </div>



                    <span class="tg-cat-badge tg-cat-stealer_logs" style="font-size:0.7rem; padding:4px 10px; display:inline-flex; align-items:center; gap:6px;">



                        <i class="fa-solid fa-lock"></i> Public API Mode &bull; Presence Confirmed



                    </span>



                </div>



            ` : `



                <div style="background:rgba(239,68,68,0.08); border:1px solid rgba(239,68,68,0.3); border-radius:8px; padding:14px 16px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">



                    <div>



                        <div style="font-size:0.95rem; font-weight:800; color:#f87171; display:flex; align-items:center; gap:8px;">



                            <i class="fa-solid fa-radiation"></i> Target Exposed in ${databases.length} Database${databases.length === 1 ? '' : 's'} (${totalReturnedRecords.toLocaleString()} Records Retrieved)



                        </div>



                        <div style="font-size:0.78rem; color:var(--text-muted); margin-top:4px;">



                            Full credential rows and indexed entries retrieved from Leak-Lookup repository.



                        </div>



                    </div>



                    <span class="tg-cat-badge tg-cat-ransomware_leaks" style="font-size:0.7rem; padding:4px 10px; display:inline-flex; align-items:center; gap:6px;">



                        <i class="fa-solid fa-unlock"></i> Private API Key &bull; Records Accessible



                    </span>



                </div>



            `;







            const quickFilterHtml = databases.length > 6 ? `



                <div style="margin-bottom:12px; display:flex; align-items:center; gap:10px; flex-wrap:wrap;">



                    <div style="position:relative; flex:1; max-width:420px; display:flex; align-items:center;">



                        <i class="fa-solid fa-filter" style="position:absolute; left:12px; color:var(--text-muted); font-size:0.76rem; pointer-events:none;"></i>



                        <input type="text" id="bw-ll-db-filter" placeholder="Filter ${databases.length} database collections (e.g. linkedin, adobe)..." style="width:100%; background:#080d17; border:1px solid rgba(255,255,255,0.12); color:white; border-radius:6px; padding:7px 12px 7px 32px; font-size:0.78rem;">



                    </div>



                    <span id="bw-ll-filter-count" style="font-size:0.75rem; color:var(--text-muted); font-weight:600;">Showing ${databases.length} of ${databases.length} databases</span>



                </div>



            ` : '';







            const cardsHtml = `



                <div id="bw-ll-cards-container" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(280px, 1fr)); gap:10px;">



                    ${databases.map(dbName => {



                        const rows = Array.isArray(resultsMap[dbName]) ? resultsMap[dbName] : [];



                        const hasRows = rows.length > 0;



                        return `



                        <div class="bw-feed-card tg-feed-item bw-ll-db-card" data-dbname="${escapeHtml(dbName.toLowerCase())}" style="margin:0;">



                            <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">



                                <div style="font-weight:700; color:var(--text-main); font-size:0.88rem; display:flex; align-items:center; gap:6px; word-break:break-all;">



                                    <i class="fa-solid fa-database" style="color:var(--accent); font-size:0.8rem; flex-shrink:0;"></i>



                                    <span>${escapeHtml(dbName)}</span>



                                </div>



                                <span style="font-size:0.65rem; font-weight:800; padding:2px 8px; border-radius:999px; flex-shrink:0; letter-spacing:0.3px; ${hasRows ? 'background:rgba(239,68,68,0.18); color:#f87171; border:1px solid rgba(239,68,68,0.35);' : 'background:rgba(245,158,11,0.15); color:#fbbf24; border:1px solid rgba(245,158,11,0.3);'}">



                                    ${hasRows ? `${rows.length} RECORD${rows.length === 1 ? '' : 'S'}` : 'EXPOSED'}



                                </span>



                            </div>



                            <div style="font-size:0.76rem; color:${hasRows ? '#f87171' : 'var(--text-muted)'}; margin-top:4px; display:flex; align-items:center; gap:6px;">



                                ${hasRows ? `<i class="fa-solid fa-key" style="font-size:0.7rem;"></i> ${rows.length} record(s) accessible` : '<i class="fa-solid fa-circle-exclamation" style="color:#fbbf24; font-size:0.7rem;"></i> Presence confirmed in breach'}



                            </div>



                            ${hasRows ? `



                                <details style="margin-top:8px; font-size:0.74rem;">



                                    <summary style="cursor:pointer; color:var(--accent); font-weight:600;">View exposed rows</summary>



                                    <div style="margin-top:6px; max-height:140px; overflow-y:auto; background:rgba(0,0,0,0.5); padding:6px 8px; border-radius:4px; font-family:monospace; font-size:0.72rem; line-height:1.4;">



                                        ${rows.map(r => `<div>${escapeHtml(typeof r === 'object' ? JSON.stringify(r) : String(r))}</div>`).join('')}



                                    </div>



                                </details>



                            ` : ''}



                        </div>



                    `;



                    }).join('')}



                </div>



            `;







            box.innerHTML = headerBannerHtml + quickFilterHtml + cardsHtml;







            // In-page filter listener



            const filterInput = document.getElementById('bw-ll-db-filter');



            const countEl = document.getElementById('bw-ll-filter-count');



            if (filterInput) {



                filterInput.addEventListener('input', (e) => {



                    const term = e.target.value.toLowerCase().trim();



                    let visible = 0;



                    document.querySelectorAll('.bw-ll-db-card').forEach(card => {



                        const name = card.dataset.dbname || '';



                        const matches = !term || name.includes(term);



                        card.style.display = matches ? 'block' : 'none';



                        if (matches) visible += 1;



                    });



                    if (countEl) {



                        countEl.textContent = `Showing ${visible} of ${databases.length} databases`;



                    }



                });



            }



        } catch (e) {



            box.innerHTML = `<div style="color:var(--danger); padding:10px;">Search error: ${escapeHtml(e.message)}</div>`;



        }



    }







